// ═══════════════════════════════════════════════════════════════════════════════
// SMART QUESTION RENDERER
// ═══════════════════════════════════════════════════════════════════════════════

interface Question {
  field: string;
  label: string;
  subtitle?: string;
  type: 'select' | 'boolean' | 'multiselect' | 'number' | 'range' | 'text';
  options?: PanelOption[];
  min?: number;
  max?: number;
  step?: number;
  unit?: string;
  icon?: React.ComponentType<{ className?: string }>;
  gradient?: string;
  optional?: boolean;
}

interface SmartQuestionProps {
  question: Question;
  value: any;
  onChange: (value: any) => void;
}

export const SmartQuestion: React.FC<SmartQuestionProps> = ({
  question,
  value,
  onChange,
}) => {
  const optionCount = question.options?.length || 0;

  // Boolean or 2 options → Toggle Buttons
  if (question.type === 'boolean' || optionCount === 2) {
    const options: [PanelOption, PanelOption] = question.options as [PanelOption, PanelOption] || [
      { value: 'true', label: 'Yes' },
      { value: 'false', label: 'No' },
    ];
    return (
      <ToggleButtons
        label={question.label}
        subtitle={question.subtitle}
        options={options}
        value={value}
        onChange={onChange}
        icon={question.icon}
        gradient={question.gradient}
      />
    );
  }

  // Multi-select → Checkbox Grid
  if (question.type === 'multiselect') {
    return (
      <CheckboxGrid
        label={question.label}
        subtitle={question.subtitle}
        options={question.options || []}
        value={value || []}
        onChange={onChange}
        icon={question.icon}
        gradient={question.gradient}
      />
    );
  }

  // Numeric range → Slider
  if (question.type === 'number' || question.type === 'range') {
    return (
      <RangeSlider
        label={question.label}
        subtitle={question.subtitle}
        min={question.min || 0}
        max={question.max || 100}
        step={question.step || 1}
        value={value || question.min || 0}
        onChange={onChange}
        unit={question.unit}
        icon={question.icon}
        gradient={question.gradient}
      />
    );
  }

  // Text → Clean Input
  if (question.type === 'text') {
    return (
      <CleanInput
        label={question.label}
        subtitle={question.subtitle}
        value={value || ''}
        onChange={onChange}
        icon={question.icon}
        gradient={question.gradient}
        optional={question.optional}
      />
    );
  }

  // 3-5 options → Panel Buttons
  if (optionCount >= 3 && optionCount <= 5) {
    return (
      <PanelButtons
        label={question.label}
        subtitle={question.subtitle}
        options={question.options || []}
        value={value}
        onChange={onChange}
        icon={question.icon}
        gradient={question.gradient}
      />
    );
  }

  // 6+ options → Searchable Dropdown
  if (optionCount > 5) {
    return (
      <SearchableDropdown
        label={question.label}
        subtitle={question.subtitle}
        options={question.options || []}
        value={value}
        onChange={onChange}
        icon={question.icon}
        gradient={question.gradient}
      />
    );
  }

  // Fallback to Panel Buttons
  return (
    <PanelButtons
      label={question.label}
      subtitle={question.subtitle}
      options={question.options || []}
      value={value}
      onChange={onChange}
      icon={question.icon}
      gradient={question.gradient}
    />
  );
};

