  extractedAt: Date;
}>> {
  try {
    let query = supabase
      .from('collected_market_prices')
      .select('*')
      .eq('equipment_type', equipmentType)
      .order('price_date', { ascending: false });

    if (options?.region) {
      query = query.eq('region', options.region);
