import React, { useState } from "react";
import { X, Mail, Lock, Eye, EyeOff, User, Building2 } from "lucide-react";
import { authService } from "../services/authService";

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLoginSuccess: (user: any) => void;
  defaultMode?: "login" | "signup";
}

export default function AuthModal({
  isOpen,
  onClose,
  onLoginSuccess,
  defaultMode = "login",
}: AuthModalProps) {
  const [mode, setMode] = useState<"login" | "signup">(defaultMode);
  const [showPassword, setShowPassword] = useState(false);
  const [accountType, setAccountType] = useState<"individual" | "company">("individual");
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    firstName: "",
    lastName: "",
    company: "",
  });
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (mode === "signup") {
        const result = await authService.signUp(
          formData.email,
          formData.password,
          formData.firstName,
          formData.lastName,
          formData.company,
          accountType
        );

        if (result.success && result.user) {
          alert(
            `✅ Welcome to Merlin Energy, ${result.user.firstName}!\n\nYour account has been created successfully.`
          );
          onLoginSuccess(result.user);
          onClose();
        } else {
          alert(result.error || "Signup failed");
          if (result.error?.includes("already exists")) {
            setMode("login");
          }
        }
      } else {
        const result = await authService.signIn(formData.email, formData.password);

        if (result.success && result.user) {
          alert(`✅ Welcome back, ${result.user.firstName}!`);
          onLoginSuccess(result.user);
          onClose();
        } else {
          alert(result.error || "Login failed");
          if (result.error?.includes("No account found")) {
            setMode("signup");
          }
        }
      }
    } catch (error) {
      console.error('Authentication error:', error);
      alert("Authentication failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full mx-4 p-8 border-4 border-purple-300 relative">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
        >
          <X size={24} />
        </button>

        <div className="text-center mb-8">
          <div className="text-4xl mb-4">🧙‍♂️</div>
          <h2 className="text-3xl font-bold text-purple-700 mb-2">
            {mode === "login" ? "Welcome Back!" : "Join Merlin Energy"}
          </h2>
          <p className="text-gray-600">
            {mode === "login"
              ? "Sign in to access your saved quotes"
              : "Create an account to save your BESS quotes"}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {mode === "signup" && (
            <>
              {/* Account Type Selection */}
              <div className="mb-6">
                <label className="block text-sm font-bold text-gray-700 mb-3">Account Type</label>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    type="button"
                    onClick={() => setAccountType("individual")}
                    className={`p-4 rounded-xl border-2 transition-all ${
                      accountType === "individual"
                        ? "border-purple-500 bg-purple-50"
                        : "border-gray-300 hover:border-purple-300"
                    }`}
                  >
                    <User
                      className={`mx-auto mb-2 ${accountType === "individual" ? "text-purple-600" : "text-gray-400"}`}
                      size={32}
                    />
                    <div className="text-center">
                      <div className="font-bold text-gray-900">Individual</div>
                      <div className="text-xs text-gray-600 mt-1">Personal account</div>
                    </div>
                  </button>
                  <button
                    type="button"
                    onClick={() => setAccountType("company")}
                    className={`p-4 rounded-xl border-2 transition-all ${
                      accountType === "company"
                        ? "border-purple-500 bg-purple-50"
                        : "border-gray-300 hover:border-purple-300"
                    }`}
                  >
                    <Building2
                      className={`mx-auto mb-2 ${accountType === "company" ? "text-purple-600" : "text-gray-400"}`}
                      size={32}
                    />
                    <div className="text-center">
                      <div className="font-bold text-gray-900">Company</div>
                      <div className="text-xs text-gray-600 mt-1">Team account (5 free seats)</div>
                    </div>
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">First Name</label>
                  <input
                    type="text"
                    required
                    value={formData.firstName}
                    onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 focus:border-purple-400 focus:outline-none text-gray-900"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">Last Name</label>
                  <input
                    type="text"
                    required
                    value={formData.lastName}
                    onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                    className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 focus:border-purple-400 focus:outline-none text-gray-900"
                  />
                </div>
              </div>

              {/* Company Name - Required for company accounts, optional for individual */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">
                  Company {accountType === "company" && <span className="text-red-500">*</span>}
                </label>
                <input
                  type="text"
                  required={accountType === "company"}
                  value={formData.company}
                  onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                  className="w-full border-2 border-gray-300 rounded-xl px-4 py-3 focus:border-purple-400 focus:outline-none text-gray-900"
                  placeholder={accountType === "company" ? "Your Company Name" : "Optional"}
                />
                {accountType === "company" && (
                  <p className="text-xs text-gray-500 mt-1">Your team gets 5 free user seats</p>
                )}
              </div>
            </>
          )}

          <div>
            <label className="block text-sm font-bold text-gray-700 mb-2">Email</label>
            <div className="relative">
              <Mail
                className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                size={20}
              />
              <input
                type="email"
                required
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full border-2 border-gray-300 rounded-xl px-12 py-3 focus:border-purple-400 focus:outline-none text-gray-900"
                placeholder="your@email.com"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-bold text-gray-700 mb-2">Password</label>
            <div className="relative">
              <Lock
                className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                size={20}
              />
              <input
                type={showPassword ? "text" : "password"}
                required
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                className="w-full border-2 border-gray-300 rounded-xl px-12 py-3 pr-12 focus:border-purple-400 focus:outline-none text-gray-900"
                placeholder="••••••••"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
              </button>
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-gradient-to-b from-purple-500 to-purple-700 text-white py-3 rounded-xl font-bold text-lg hover:from-purple-600 hover:to-purple-800 transition-all disabled:opacity-50"
          >
            {loading ? "Please wait..." : mode === "login" ? "Sign In" : "Create Account"}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button
            onClick={() => setMode(mode === "login" ? "signup" : "login")}
            className="text-purple-600 hover:text-purple-800 font-semibold"
          >
            {mode === "login"
              ? "Don't have an account? Sign up"
              : "Already have an account? Sign in"}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { getCachedConstants, calculateFinancialMetrics } from "../services/centralizedCalculations";

interface DatabaseTestProps {
  isOpen: boolean;
  onClose: () => void;
}

const DatabaseTest: React.FC<DatabaseTestProps> = ({ isOpen, onClose }) => {
  const [stats, setStats] = useState<any>(null);
  const [vendors, setVendors] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [calcTest, setCalcTest] = useState<any>(null);

  const API_BASE = "/api/db";

  const testCalculationService = async () => {
    setLoading(true);
    setError(null);

    try {
      console.log("🧪 Testing Centralized Calculation Service...");

      // 1. Test fetching constants
      const constants = await getCachedConstants();
      console.log("📊 Constants loaded:", constants);

      // 2. Test calculation
      const result = await calculateFinancialMetrics({
        storageSizeMW: 2,
        durationHours: 4,
        solarMW: 0,
        location: "California",
        electricityRate: 0.15,
      });

      console.log("💰 Calculation result:", result);

      setCalcTest({
        constants,
        result,
        dataSource: result.dataSource,
        success: true,
      });
    } catch (err) {
      console.error("❌ Error testing calculations:", err);
      setError(err instanceof Error ? err.message : "Unknown error");
      setCalcTest({ success: false, error: err });
    } finally {
      setLoading(false);
    }
  };

  const testAPI = async () => {
    setLoading(true);
    setError(null);

    try {
      // Test database stats
      const statsResponse = await fetch(`${API_BASE}/stats`);
      if (!statsResponse.ok) {
        throw new Error(`Stats API failed: ${statsResponse.status}`);
      }
      const statsData = await statsResponse.json();
      setStats(statsData);

      // Test vendors API
      const vendorsResponse = await fetch(`${API_BASE}/vendors`);
      if (!vendorsResponse.ok) {
        throw new Error(`Vendors API failed: ${vendorsResponse.status}`);
      }
      const vendorsData = await vendorsResponse.json();
      setVendors(vendorsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  };

  const addTestVendor = async () => {
    try {
      const testVendor = {
        name: "Test Energy Solutions",
        contact_email: "contact@testenergy.com",
        contact_phone: "+1-555-0123",
        specialty: "Battery Systems",
        website: "https://testenergy.com",
        notes: "Test vendor created from database test",
      };

      const response = await fetch(`${API_BASE}/vendors`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(testVendor),
      });

      if (!response.ok) {
        throw new Error(`Create vendor failed: ${response.status}`);
      }

      // Refresh data
      testAPI();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to create vendor");
    }
  };

  useEffect(() => {
    if (isOpen) {
      testAPI();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl h-4/5 flex flex-col">
        <div className="flex items-center justify-between p-6 border-b">
          <h2 className="text-2xl font-bold text-gray-800">Database Test</h2>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700 text-2xl">
            ×
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          <div className="space-y-6">
            {/* Controls */}
            <div className="flex gap-3">
              <button
                onClick={testAPI}
                disabled={loading}
                className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:bg-gray-300"
              >
                {loading ? "Testing..." : "Test Database API"}
              </button>
              <button
                onClick={testCalculationService}
                disabled={loading}
                className="px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 disabled:bg-gray-300"
              >
                Test Calculation Service
              </button>
              <button
                onClick={addTestVendor}
                disabled={loading}
                className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 disabled:bg-gray-300"
              >
                Add Test Vendor
              </button>
            </div>

            {/* Error Display */}
            {error && (
              <div className="bg-red-100 border border-red-300 text-red-700 px-4 py-3 rounded">
                <strong>Error:</strong> {error}
              </div>
            )}

            {/* API Connection Status */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Calculation Service Test */}
              {calcTest && (
                <div className="bg-purple-50 p-4 rounded-lg md:col-span-2">
                  <h3 className="text-lg font-semibold mb-3">Calculation Service Test</h3>
                  {calcTest.success ? (
                    <div className="space-y-3">
                      <div className="bg-white p-3 rounded border">
                        <div className="font-semibold text-green-600">
                          ✅ Data Source: {calcTest.dataSource}
                        </div>
                        {calcTest.dataSource === "database" ? (
                          <div className="text-sm text-gray-600 mt-1">
                            Successfully reading from Supabase!
                          </div>
                        ) : (
                          <div className="text-sm text-orange-600 mt-1">
                            ⚠️ Using fallback constants
                          </div>
                        )}
                      </div>
                      <div className="bg-white p-3 rounded border">
                        <div className="font-semibold mb-2">Test Results (2MW/4hr BESS):</div>
                        <div className="text-sm space-y-1">
                          <div>
                            Total Cost:{" "}
                            <span className="font-bold">
                              ${calcTest.result.totalCost.toLocaleString()}
                            </span>
                          </div>
                          <div>
                            Annual Savings:{" "}
                            <span className="font-bold">
                              ${calcTest.result.annualSavings.toLocaleString()}
                            </span>
                          </div>
                          <div>
                            ROI:{" "}
                            <span className="font-bold">{calcTest.result.roi.toFixed(1)}%</span>
                          </div>
                          <div>
                            Payback:{" "}
                            <span className="font-bold">
                              {calcTest.result.paybackYears.toFixed(1)} years
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className="bg-white p-3 rounded border">
                        <div className="font-semibold mb-2">Constants Used:</div>
                        <div className="text-xs space-y-1 text-gray-700">
                          <div>
                            Peak Shaving: {calcTest.constants.peakShavingMultiplier} cycles/year
                          </div>
                          <div>
                            Demand Charge: $
                            {calcTest.constants.demandChargeMonthlyPerMW.toLocaleString()}/MW-month
                          </div>
                          <div>
                            Grid Services: $
                            {calcTest.constants.gridServiceRevenuePerMW.toLocaleString()}/MW-year
                          </div>
                          <div>
                            Efficiency: {(calcTest.constants.roundTripEfficiency * 100).toFixed(0)}%
                          </div>
                          <div>
                            Tax Credit: {(calcTest.constants.federalTaxCreditRate * 100).toFixed(0)}
                            %
                          </div>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="text-red-600">Test failed - check console for details</div>
                  )}
                </div>
              )}

              {/* Database Stats */}
              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="text-lg font-semibold mb-3">Database Stats</h3>
                {stats ? (
                  <div className="space-y-2">
                    <div>
                      Vendors: <span className="font-bold">{stats.vendors}</span>
                    </div>
                    <div>
                      Products: <span className="font-bold">{stats.products}</span>
                    </div>
                    <div>
                      Materials: <span className="font-bold">{stats.materials}</span>
                    </div>
                    <div>
                      Configurations: <span className="font-bold">{stats.configurations}</span>
                    </div>
                    <div>
                      Categories: <span className="font-bold">{stats.categories}</span>
                    </div>
                  </div>
                ) : (
                  <div className="text-gray-500">No stats loaded</div>
                )}
              </div>

              {/* Vendors List */}
              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="text-lg font-semibold mb-3">Vendors ({vendors.length})</h3>
                <div className="space-y-2 max-h-64 overflow-y-auto">
                  {vendors.length > 0 ? (
                    vendors.map((vendor, index) => (
                      <div key={vendor.id || index} className="bg-white p-3 rounded border">
                        <div className="font-semibold">{vendor.name}</div>
                        <div className="text-sm text-gray-600">{vendor.contact_email}</div>
                        {vendor.specialty && (
                          <div className="text-xs text-blue-600">{vendor.specialty}</div>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="text-gray-500">No vendors found</div>
                  )}
                </div>
              </div>
            </div>

            {/* API Endpoint Tests */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="text-lg font-semibold mb-3">API Endpoint Information</h3>
              <div className="space-y-2 text-sm">
                <div>
                  <strong>Base URL:</strong> {API_BASE}
                </div>
                <div>
                  <strong>Available Endpoints:</strong>
                </div>
                <ul className="list-disc list-inside ml-4 space-y-1">
                  <li>GET /stats - Database statistics</li>
                  <li>GET /vendors - List all vendors</li>
                  <li>POST /vendors - Create new vendor</li>
                  <li>GET /vendors/:id - Get single vendor</li>
                  <li>GET /vendors/:id/products - Get vendor products</li>
                  <li>GET /products/search?q=query - Search products</li>
                  <li>GET /bess-configs - List BESS configurations</li>
                  <li>GET /materials - Get materials library</li>
                </ul>
              </div>
            </div>

            {/* Raw Data Display */}
            {(stats || vendors.length > 0) && (
              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="text-lg font-semibold mb-3">Raw Data</h3>
                <pre className="text-xs bg-white p-3 rounded border overflow-auto max-h-64">
                  {JSON.stringify({ stats, vendors }, null, 2)}
                </pre>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default DatabaseTest;

import React, { useState, useEffect, useRef } from "react";
import {
  X,
  User,
  Settings,
  Users,
  Mail,
  Building2,
  Copy,
  Check,
  UserCog,
  Shield,
  Camera,
  Globe,
  Linkedin,
  Phone,
  Share2,
  Eye,
  EyeOff,
  ExternalLink,
  Save,
} from "lucide-react";
import { authService } from "../services/authService";
import type { User as UserType, Company, TeamMember } from "@/types";

interface EditableUserProfileProps {
  isLoggedIn: boolean;
  onClose: () => void;
  onLoginSuccess: () => void;
  onLogout: () => void;
  onShowQuoteTemplates?: () => void;
  onShowPricingPresets?: () => void;
  onShowVendorLeads?: () => void;
}

type Tab = "profile" | "team" | "invites";

const EditableUserProfile: React.FC<EditableUserProfileProps> = ({
  isLoggedIn,
  onClose,
  onLoginSuccess,
  onLogout,
  onShowQuoteTemplates,
  onShowPricingPresets,
  onShowVendorLeads,
}) => {
  const [activeTab, setActiveTab] = useState<Tab>("profile");
  const [user, setUser] = useState<UserType | null>(null);
  const [company, setCompany] = useState<Company | null>(null);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [inviteCode, setInviteCode] = useState<string>("");
  const [copiedInvite, setCopiedInvite] = useState(false);
  const [copiedProfile, setCopiedProfile] = useState(false);

  // Edit mode states
  const [isEditing, setIsEditing] = useState(false);
  const [editedData, setEditedData] = useState<Partial<UserType>>({});
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isLoggedIn) {
      loadUserData();
    }
  }, [isLoggedIn]);

  const loadUserData = () => {
    const currentUser = authService.getCurrentUser();
    setUser(currentUser);
    setEditedData({
      bio: currentUser?.bio || "",
      companyWebsite: currentUser?.companyWebsite || "",
      linkedIn: currentUser?.linkedIn || "",
      phone: currentUser?.phone || "",
      profileVisibility: currentUser?.profileVisibility || "private",
      profilePhoto: currentUser?.profilePhoto || "",
    });

    if (currentUser?.companyId) {
      const companyData = authService.getCompanyById(currentUser.companyId);
      setCompany(companyData);

      if (companyData) {
        const members = authService.getCompanyMembers(companyData.id);
        // Map User[] to TeamMember[] with required fields
        setTeamMembers(
          members.map((m) => ({
            ...m,
            role: (m as any).role || "user",
            status: "active" as const,
          }))
        );
      }
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Check file size (max 2MB)
      if (file.size > 2 * 1024 * 1024) {
        alert("Image size must be less than 2MB");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setEditedData({ ...editedData, profilePhoto: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = async () => {
    if (!user) return;

    // Generate profile slug if making profile public and doesn't have one
    const updates = { ...editedData };
    if (editedData.profileVisibility === "public" && !user.publicProfileSlug) {
      const slug = authService.generateProfileSlug(user.firstName || "", user.lastName || "");
      updates.publicProfileSlug = slug;
    }

    await authService.updateUserProfile(user.id, updates);
    setSaved(true);
    setIsEditing(false);
    setTimeout(() => {
      setSaved(false);
      loadUserData(); // Reload to get updated data
    }, 1500);
  };

  const handleGenerateInvite = async () => {
    if (user && company) {
      const result = await authService.inviteTeamMember(company.id, user.email);
      if (result.success && result.inviteCode) {
        setInviteCode(result.inviteCode);
      }
    }
  };

  const handleCopyInvite = () => {
    const inviteLink = `${window.location.origin}?invite=${inviteCode}`;
    navigator.clipboard.writeText(inviteLink);
    setCopiedInvite(true);
    setTimeout(() => setCopiedInvite(false), 2000);
  };

  const handleShareProfile = () => {
    if (!user?.publicProfileSlug) {
      alert("Please make your profile public first to enable sharing");
      return;
    }
    const profileLink = `${window.location.origin}/profile/${user.publicProfileSlug}`;
    navigator.clipboard.writeText(profileLink);
    setCopiedProfile(true);

    // Track share action
    authService.trackVisitor(user.publicProfileSlug, "profile_shared_by_owner");

    setTimeout(() => setCopiedProfile(false), 2000);
  };

  const getRoleBadge = (role?: string) => {
    switch (role) {
      case "owner":
        return (
          <span className="text-xs bg-purple-100 text-purple-700 px-2 py-1 rounded-full font-bold flex items-center gap-1">
            <Shield size={12} /> Owner
          </span>
        );
      case "admin":
        return (
          <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-bold flex items-center gap-1">
            <UserCog size={12} /> Admin
          </span>
        );
      case "member":
        return (
          <span className="text-xs bg-gray-100 text-gray-700 px-2 py-1 rounded-full font-bold">
            Member
          </span>
        );
      default:
        return null;
    }
  };

  const isCompanyAccount = user?.accountType === "company";
  const canInvite =
    isCompanyAccount && (user?.companyRole === "owner" || user?.companyRole === "admin");

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4">
