import React, { useState, useEffect } from "react";
import { TrendingUp, TrendingDown, Zap, DollarSign, Newspaper } from "lucide-react";
import { supabase } from "../services/supabase";

interface TickerItem {
  type: "price" | "news" | "funding";
  content: string;
  value?: string;
  change?: number;
  icon: React.ReactNode;
}

const EnergyNewsTicker: React.FC = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [tickerItems, setTickerItems] = useState<TickerItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Fallback ticker items - used immediately and when database is unavailable
  const getFallbackTickerItems = (): TickerItem[] => [
    {
      type: "news",
      content: "Tesla completes 730 MWh Megapack installation at Moss Landing, CA",
      icon: <Newspaper className="w-4 h-4" />,
    },
    {
      type: "price",
      content: "LFP Battery Cells",
      value: "$145/kWh",
      change: -5.2,
      icon: <DollarSign className="w-4 h-4" />,
    },
    {
      type: "funding",
      content: "Amazon invests $500M in solar+storage microgrid for data centers",
      value: "$500M",
      icon: <DollarSign className="w-4 h-4" />,
    },
    {
      type: "news",
      content: "California mandates 52 GW of energy storage by 2045",
      icon: <Newspaper className="w-4 h-4" />,
    },
    {
      type: "price",
      content: "NMC Battery Cells",
      value: "$128/kWh",
      change: -8.3,
      icon: <DollarSign className="w-4 h-4" />,
    },
  ];

  // Initialize with fallback data immediately (no loading state)
  useEffect(() => {
    // Start with fallback data immediately
    setTickerItems(getFallbackTickerItems());
    setIsLoading(false);

    // Then try to fetch live data in the background
    const fetchTickerData = async () => {
      try {
        // Add timeout to prevent hanging
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        // Fetch latest news from database
        const { data: newsData, error: newsError } = await supabase
          .from("industry_news")
          .select("*")
          .order("publishDate", { ascending: false })
          .limit(10);

        clearTimeout(timeoutId);

        if (newsError || !newsData || newsData.length === 0) {
          // Keep using fallback data
          return;
        }

        // Transform database news into ticker items
        const newsItems: TickerItem[] = newsData.map((item) => ({
          type:
            item.category === "pricing"
              ? "price"
              : item.category === "deployment"
                ? "funding"
                : "news",
          content: item.title,
          icon:
            item.category === "pricing" ? (
              <DollarSign className="w-4 h-4" />
            ) : item.category === "deployment" ? (
              <Zap className="w-4 h-4" />
            ) : (
              <Newspaper className="w-4 h-4" />
            ),
        }));

        // Fetch latest pricing data
        const { data: pricingData, error: pricingError } = await supabase
          .from("battery_pricing")
          .select("*")
          .order("date", { ascending: false })
          .limit(3);

        if (!pricingError && pricingData && pricingData.length > 0) {
          const priceItems: TickerItem[] = pricingData.map((item) => ({
            type: "price",
            content: `${item.chemistry.toUpperCase()} Battery (${item.systemSize})`,
            value: `$${item.pricePerKWh}/kWh`,
            change: -5.2,
            icon: <DollarSign className="w-4 h-4" />,
          }));
          newsItems.push(...priceItems);
        }

        // Only update if we got data
        if (newsItems.length > 0) {
          setTickerItems(newsItems);
        }
      } catch (error) {
        // Keep using fallback data - no console error needed
      }
    };

    // Fetch live data after a short delay
    const fetchTimeout = setTimeout(fetchTickerData, 1000);

    // Refresh ticker data every 5 minutes
    const refreshInterval = setInterval(fetchTickerData, 5 * 60 * 1000);

    return () => {
      clearTimeout(fetchTimeout);
      clearInterval(refreshInterval);
    };
  }, []);

  // Rotate ticker items
  useEffect(() => {
    if (tickerItems.length === 0) return;

    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % tickerItems.length);
    }, 8000); // Change every 8 seconds

    return () => clearInterval(interval);
  }, [tickerItems.length]);

  if (isLoading || tickerItems.length === 0) {
    return (
      <div className="bg-gradient-to-r from-gray-600 to-gray-700 text-white py-3 px-6 rounded-xl shadow-lg">
        <div className="flex items-center justify-center">
          <span className="text-sm">Loading market data...</span>
        </div>
      </div>
    );
  }

  const currentItem = tickerItems[currentIndex];

  const getBackgroundColor = () => {
    switch (currentItem.type) {
      case "price":
        return "from-purple-600 to-purple-700";
      case "news":
        return "from-blue-600 to-blue-700";
      case "funding":
        return "from-amber-600 to-amber-700";
      default:
        return "from-gray-600 to-gray-700";
    }
  };

  const getTypeLabel = () => {
    switch (currentItem.type) {
      case "price":
        return "PRICING";
      case "news":
        return "NEWS";
      case "funding":
        return "FUNDING";
      default:
        return "INFO";
    }
  };

  return (
    <div
      className={`bg-gradient-to-r ${getBackgroundColor()} text-white py-3 px-6 rounded-xl shadow-lg`}
    >
      <div className="flex items-center justify-between gap-4">
        {/* Type Badge */}
        <div className="flex items-center gap-2 min-w-fit">
          <div className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold">
            {getTypeLabel()}
          </div>
        </div>

        {/* Content - Animates in */}
        <div className="flex-1 flex items-center gap-3 animate-fadeIn">
          <div className="flex items-center gap-2">
            {currentItem.icon}
            <span className="font-semibold">{currentItem.content}</span>
          </div>

          {currentItem.value && (
            <div className="flex items-center gap-2">
              <span className="text-xl font-bold">{currentItem.value}</span>
              {currentItem.change !== undefined && (
                <div
                  className={`flex items-center gap-1 text-sm ${
                    currentItem.change >= 0 ? "text-green-300" : "text-red-300"
                  }`}
                >
                  {currentItem.change >= 0 ? (
                    <TrendingUp className="w-4 h-4" />
                  ) : (
                    <TrendingDown className="w-4 h-4" />
                  )}
                  <span className="font-semibold">
                    {currentItem.change >= 0 ? "+" : ""}
                    {currentItem.change}%
                  </span>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Progress Dots */}
        <div className="flex gap-1 min-w-fit">
          {[...Array(5)].map((_, i) => (
            <div
              key={i}
              className={`w-2 h-2 rounded-full ${
                i === Math.floor(currentIndex / (tickerItems.length / 5))
                  ? "bg-white"
                  : "bg-white/30"
              }`}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default EnergyNewsTicker;

import React, { useState, useEffect } from "react";
import { LoadProfileAnalyzer, BatteryElectrochemicalModel, BESSMLForecasting, BESSOptimizationEngine } from "../services/advancedBessAnalytics";
import type {
  LoadProfile,
  BatteryModel,
  ControlStrategy,
  OptimizationResult,
} from "../services/advancedBessAnalytics";

interface EnhancedBESSAnalyticsProps {
  isOpen: boolean;
  onClose: () => void;
  projectData: {
    quoteName: string;
    storageSizeMW: number;
    durationHours: number;
    useCase: string;
    location: string;
  };
}

export const EnhancedBESSAnalytics: React.FC<EnhancedBESSAnalyticsProps> = ({
  isOpen,
  onClose,
  projectData,
}) => {
  const [activeTab, setActiveTab] = useState(0);
  const [analysisResults, setAnalysisResults] = useState<{
    loadAnalysis: any;
    batteryModel: any;
    optimization: OptimizationResult;
    forecasting: any;
  } | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const tabs = [
    {
      id: "overview",
      label: "Overview",
      icon: "📊",
      desc: "System summary and key metrics",
    },
    {
      id: "load-clustering",
      label: "Load Analysis",
      icon: "📈",
      desc: "Load patterns and clustering",
    },
    {
      id: "battery-modeling",
      label: "Battery Model",
      icon: "🔋",
      desc: "Electrochemical analysis",
    },
    {
      id: "optimization",
      label: "Optimization",
      icon: "⚡",
      desc: "Control strategy analysis",
    },
    {
      id: "forecasting",
      label: "ML Forecasting",
      icon: "🤖",
      desc: "Machine learning predictions",
    },
  ];

  useEffect(() => {
    if (isOpen && !analysisResults) {
      runAnalysis();
    }
  }, [isOpen]);

  const generateSyntheticLoadProfile = (): LoadProfile[] => {
    const data: LoadProfile[] = [];
    const baseDate = new Date("2024-01-01");

    for (let day = 0; day < 30; day++) {
      for (let hour = 0; hour < 24; hour++) {
        const timestamp = new Date(
          baseDate.getTime() + day * 24 * 60 * 60 * 1000 + hour * 60 * 60 * 1000
        );

        // Industry-specific load patterns
        let demandMultiplier = 1.0;
        if (projectData.useCase === "EV Charging") {
          demandMultiplier = (hour >= 7 && hour <= 9) || (hour >= 17 && hour <= 19) ? 1.8 : 0.6;
        } else if (projectData.useCase === "Data Center") {
          demandMultiplier = hour >= 18 && hour <= 22 ? 1.2 : 1.0;
        } else if (projectData.useCase === "Manufacturing") {
          demandMultiplier = hour >= 8 && hour <= 17 ? 1.5 : 0.4;
        } else {
          demandMultiplier = 0.3 + (0.7 * (Math.sin(((hour - 6) * Math.PI) / 12) + 1)) / 2;
        }

        const demand_kW =
          projectData.storageSizeMW * 1000 * demandMultiplier * (0.8 + 0.4 * Math.random());

        data.push({
          timestamp,
          demand_kW: Math.max(10, demand_kW),
          solar_kW:
            hour >= 6 && hour <= 18
              ? projectData.storageSizeMW * 500 * Math.sin(((hour - 6) * Math.PI) / 12)
              : 0,
          grid_price_per_kWh: hour >= 16 && hour <= 20 ? 0.25 : 0.1,
          temperature_C: 20 + 5 * Math.sin((day * Math.PI) / 15),
        });
      }
    }
    return data;
  };

  const runAnalysis = async () => {
    setIsLoading(true);

    try {
      // Generate synthetic data
      const historicalData = generateSyntheticLoadProfile();

      // SSOT: Standard battery model using Power × Duration = Energy formula
      const batteryModel: BatteryModel = {
        capacity_kWh: projectData.storageSizeMW * projectData.durationHours * 1000, // SSOT: MW × hrs × 1000 = kWh
        power_kW: projectData.storageSizeMW * 1000, // SSOT: MW × 1000 = kW
        efficiency_charge: 0.92,
        efficiency_discharge: 0.95,
        voltage_nominal: 3.2,
        soc_min: 0.1,
        soc_max: 0.9,
        degradation_rate_per_cycle: 0.00002,
        calendar_degradation_per_year: 0.02,
        depth_of_discharge_factor: 0.8,
      };

      // Create control strategy
      const controlStrategy: ControlStrategy = {
        type: "peak_shaving",
        demand_threshold_kW: projectData.storageSizeMW * 1000 * 0.8,
        soc_target_min: 0.2,
        soc_target_max: 0.9,
        priority_order: ["peak_shaving", "arbitrage"],
      };

      // Run analyses
      const loadAnalysis = LoadProfileAnalyzer.analyzePeakDemandPatterns(historicalData);
      const batteryModelInstance = new BatteryElectrochemicalModel(batteryModel);
      const batteryAnalysis = {
        degradation_rate: 0.025,
        cycles_completed: 1000,
      };
      const optimization = BESSOptimizationEngine.optimize(
        historicalData,
        batteryModel,
        controlStrategy,
        24 * 7
      );
      const forecasting = BESSMLForecasting.predictBatteryHealth(1000, 2, 25, 0.8);

      setAnalysisResults({
        loadAnalysis,
        batteryModel: batteryAnalysis,
        optimization,
        forecasting,
      });
    } catch (error) {
      console.error("Analysis failed:", error);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div
      className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden"
      onClick={(e) => {
        // Stop event propagation to prevent modal from closing when clicking inside
        e.stopPropagation();
      }}
    >
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-6">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-2xl font-bold">🧠 ML Analytics Suite</h2>
            <p className="text-blue-100 mt-1">{projectData.quoteName}</p>
          </div>
          <button onClick={onClose} className="text-white hover:bg-white/20 rounded-lg px-3 py-1">
            ✕
          </button>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="border-b border-gray-200">
        <nav className="flex overflow-x-auto px-6">
          {tabs.map((tab, index) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(index)}
              className={`py-3 px-4 border-b-2 font-medium text-sm whitespace-nowrap ${
                activeTab === index
                  ? "border-blue-500 text-blue-600"
                  : "border-transparent text-gray-500 hover:text-gray-700"
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </nav>
      </div>

