            </p>
          </div>
        </div>

        {/* Sync Results */}
        {syncResult && (
          <div
            className={`border rounded-lg p-4 ${syncResult.success ? "bg-green-50 border-green-200" : "bg-red-50 border-red-200"}`}
          >
            <div className="flex items-center space-x-2">
              {syncResult.success ? (
                <CheckCircle className="w-5 h-5 text-green-600" />
              ) : (
                <AlertTriangle className="w-5 h-5 text-red-600" />
              )}
              <h4 className="font-semibold">
                {syncResult.success ? "Sync Successful" : "Sync Failed"}
              </h4>
            </div>
            <p className="text-sm mt-2">{syncResult.message}</p>
            {syncResult.error && (
              <p className="text-sm text-red-600 mt-1">Error: {syncResult.error}</p>
            )}
            {syncResult.data &&
              typeof syncResult.data === "object" &&
              "summary" in syncResult.data && (
                <details className="mt-2">
                  <summary className="text-sm cursor-pointer">View Sync Report</summary>
                  <pre className="text-xs bg-gray-100 p-2 rounded mt-2 overflow-x-auto">
                    {JSON.stringify(syncResult.data, null, 2)}
                  </pre>
                </details>
              )}
          </div>
        )}

        {/* Daily Sync Service Status */}
        <div className="bg-white border rounded-lg p-6">
          <h4 className="font-semibold mb-4">Daily Sync Service</h4>
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-600">Service Status</span>
              <span
                className={`px-2 py-1 rounded text-xs ${databaseStatus === "connected" ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}`}
              >
                {databaseStatus === "connected" ? "Running" : "Offline"}
              </span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-600">Next Scheduled Sync</span>
              <span className="text-sm font-mono">Daily at 6:00 AM UTC</span>
            </div>
            <div className="text-xs text-gray-500 bg-gray-50 p-3 rounded">
              <p>The daily sync service automatically:</p>
              <ul className="mt-2 space-y-1 ml-4 list-disc">
                <li>Validates pricing against market sources (NREL, Bloomberg, Wood Mackenzie)</li>
                <li>
                  Updates vendor-specific pricing data (Dynapower, Sinexcel, Great Power,
                  Mainspring)
                </li>
                <li>Backs up pricing configurations to Supabase</li>
                <li>Processes and cleans up pricing alerts</li>
                <li>Generates daily pricing reports and statistics</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderSectionContent = () => {
    switch (activeSection) {
      case "validation":
        return renderValidationSection();
      case "database":
        return renderDatabaseSection();
      case "bess":
        return renderBESSSection();
      case "solar":
        return renderSolarSection();
      case "wind":
        return renderWindSection();
      case "generators":
        return renderGeneratorSection();
      case "powerElectronics":
        return renderPowerElectronicsSection();
      case "systemControls":
        return renderSystemControlsSection();
      case "evCharging":
        return renderEVChargingSection();
      case "balanceOfPlant":
        return renderBalanceOfPlantSection();
      default:
        return <div>Section content not yet implemented</div>;
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg max-w-7xl w-full h-5/6 m-4 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b">
          <div className="flex items-center space-x-3">
            <Settings className="w-6 h-6 text-purple-600" />
            <div>
              <h2 className="text-xl font-bold">Pricing Administration Dashboard</h2>
              <p className="text-sm text-gray-600">
                Version {config.version} • Last updated:{" "}
                {new Date(config.lastUpdated).toLocaleString()}
              </p>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            {/* Save Status */}
            {saveStatus === "saving" && <span className="text-purple-600 text-sm">Saving...</span>}
            {saveStatus === "saved" && (
              <span className="text-green-600 text-sm flex items-center">
                <CheckCircle className="w-4 h-4 mr-1" /> Saved
              </span>
            )}
            {saveStatus === "error" && <span className="text-red-600 text-sm">Save failed</span>}

            {/* Action Buttons */}
            <button
              onClick={saveChanges}
              disabled={!hasChanges || saveStatus === "saving"}
              className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
            >
              <Save className="w-4 h-4 mr-2" />
              Save Changes
            </button>

            <button
              onClick={exportConfig}
              className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center"
            >
              <Download className="w-4 h-4 mr-2" />
              Export
            </button>

            <label
              className={`bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 flex items-center ${!canImport ? "opacity-50 cursor-not-allowed" : "cursor-pointer"}`}
              title={!canImport ? "You do not have permission to import configuration" : ""}
            >
              <Upload className="w-4 h-4 mr-2" />
              Import
              <input
                type="file"
                accept=".json"
                onChange={importConfig}
                className="hidden"
                disabled={!canImport}
              />
            </label>

            <button
              onClick={resetToDefaults}
              disabled={!canReset}
              className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
              title={!canReset ? "You do not have permission to reset to defaults" : ""}
            >
              <RotateCcw className="w-4 h-4 mr-2" />
              Reset
            </button>

            <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
              ✕
            </button>
          </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
          {/* Sidebar */}
          <div className="w-64 bg-gray-50 border-r overflow-y-auto">
            <div className="p-4">
              <h3 className="font-semibold text-gray-800 mb-4">Equipment Categories</h3>
              <nav className="space-y-2">
                {sections.map((section) => (
                  <button
                    key={section.id}
                    onClick={() => setActiveSection(section.id)}
                    className={`w-full text-left px-3 py-2 rounded-lg text-sm transition-colors ${
                      activeSection === section.id
                        ? "bg-gradient-to-r from-purple-100 to-indigo-100 text-purple-700 border border-purple-300 shadow-sm"
                        : "hover:bg-purple-50 text-gray-700"
                    }`}
                  >
                    <span className="mr-2">{section.icon}</span>
                    {section.name}
                  </button>
                ))}
              </nav>
            </div>
          </div>

          {/* Main Content */}
          <div className="flex-1 overflow-y-auto p-6">
            <div className="max-w-4xl">
              <h3 className="text-lg font-semibold mb-6">
                {sections.find((s) => s.id === activeSection)?.icon}{" "}
                {sections.find((s) => s.id === activeSection)?.name} Configuration
              </h3>

              {renderSectionContent()}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from "react";

interface PricingDataCaptureProps {
  onClose: () => void;
  userEmail?: string;
}

interface ExtractedPricingData {
  id: string;
  fileName: string;
  uploadDate: Date;
  status: "pending" | "extracted" | "reviewed" | "validated";
  confidence: number;
  data: {
    // Equipment Costs
    batterySystem?: {
      manufacturer?: string;
      model?: string;
      capacity_kwh?: number;
      power_kw?: number;
      price_total?: number;
      price_per_kwh?: number;
      price_per_kw?: number;
    };
    inverter?: {
      manufacturer?: string;
      model?: string;
      power_kw?: number;
      price?: number;
    };
    bos?: {
      description?: string;
      price?: number;
    };

    // Installation & Soft Costs
    installation?: {
      labor_cost?: number;
      labor_hours?: number;
      labor_rate_per_hour?: number;
    };
    engineering?: number;
    permitting?: number;
    interconnection?: number;

    // Project Details
    project?: {
      location?: string;
      state?: string;
      country?: string;
      system_size_kwh?: number;
      system_size_kw?: number;
      application?: string;
      quote_date?: string;
    };

    // Pricing Summary
    summary?: {
      total_cost?: number;
      cost_per_kwh?: number;
      cost_per_kw?: number;
      warranty_years?: number;
    };

    // Vendor Info (anonymized)
    vendor?: {
      type?: "manufacturer" | "distributor" | "installer" | "epc";
      region?: string;
    };
  };
}

const PricingDataCapture: React.FC<PricingDataCaptureProps> = ({ onClose, userEmail }) => {
  const [activeTab, setActiveTab] = useState<"upload" | "review" | "history">("upload");
  const [uploadedFiles, setUploadedFiles] = useState<ExtractedPricingData[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<ExtractedPricingData | null>(null);
  const [consentGiven, setConsentGiven] = useState(false);

  // Handle file drag events
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  }, []);

  // Handle file drop
  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(Array.from(e.dataTransfer.files));
    }
  }, []);

  // Handle file input
  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      handleFiles(Array.from(e.target.files));
    }
  };

  // Process uploaded files
  const handleFiles = async (files: File[]) => {
    if (!consentGiven) {
      alert("Please consent to data usage terms before uploading.");
      return;
    }

    setUploading(true);

    // Simulate file upload and AI extraction
    // In production, this would call your backend API
    for (const file of files) {
      // Simulate API call delay
      await new Promise((resolve) => setTimeout(resolve, 1500));

      const mockExtractedData: ExtractedPricingData = {
