                  Available Utilities ({filteredRates.length})
                </h3>
              </div>
              <div className="overflow-y-auto max-h-96">
                {filteredRates.map((rate) => (
                  <button
                    key={rate.id}
                    onClick={() => setSelectedUtility(rate.utility)}
                    className={`w-full text-left p-3 border-b border-gray-100 hover:bg-purple-50 transition-colors ${
                      selectedUtility === rate.utility
                        ? "bg-purple-100 border-l-4 border-l-purple-600"
                        : ""
                    }`}
                  >
                    <div className="font-medium text-gray-900">{rate.utility}</div>
                    <div className="text-sm text-gray-600">{rate.state}</div>
                    <div className="text-sm font-semibold text-purple-600 mt-1">
                      ${getRateValue(rate).toFixed(3)}/kWh
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Right Column - Rate Details */}
            <div className="border border-gray-200 rounded-lg">
              {selectedRateData ? (
                <div className="p-4">
                  <h3 className="font-bold text-lg text-gray-900 mb-4">
                    {selectedRateData.utility}
                  </h3>

                  <div className="space-y-4">
                    <div>
                      <h4 className="text-sm font-medium text-gray-700 mb-2">Standard Rates</h4>
                      <div className="space-y-2">
                        <div className="flex justify-between items-center p-2 bg-gray-50 rounded">
                          <span className="text-sm">Residential</span>
                          <span className="font-semibold">
                            ${selectedRateData.residentialRate.toFixed(3)}/kWh
                          </span>
                        </div>
                        <div className="flex justify-between items-center p-2 bg-gray-50 rounded">
                          <span className="text-sm">Commercial</span>
                          <span className="font-semibold">
                            ${selectedRateData.commercialRate.toFixed(3)}/kWh
                          </span>
                        </div>
                        <div className="flex justify-between items-center p-2 bg-gray-50 rounded">
                          <span className="text-sm">Industrial</span>
                          <span className="font-semibold">
                            ${selectedRateData.industrialRate.toFixed(3)}/kWh
                          </span>
                        </div>
                      </div>
                    </div>

                    {selectedRateData.demandCharge && (
                      <div>
                        <h4 className="text-sm font-medium text-gray-700 mb-2">Demand Charge</h4>
                        <div className="p-2 bg-orange-50 rounded">
                          <span className="font-semibold text-orange-700">
                            ${selectedRateData.demandCharge.toFixed(2)}/kW
                          </span>
                        </div>
                      </div>
                    )}

                    {selectedRateData.hasTOU && selectedRateData.touRates && (
                      <div>
                        <h4 className="text-sm font-medium text-gray-700 mb-2">
                          Time-of-Use Rates
                        </h4>
                        <div className="space-y-2">
                          <div className="p-2 bg-red-50 rounded">
                            <div className="text-xs text-red-600 font-medium">Peak</div>
                            <div className="font-semibold text-red-700">
                              ${selectedRateData.touRates.peak.toFixed(3)}/kWh
                            </div>
                            <div className="text-xs text-red-600 mt-1">
                              {selectedRateData.touRates.peakHours}
                            </div>
                          </div>
                          <div className="p-2 bg-green-50 rounded">
                            <div className="text-xs text-green-600 font-medium">Off-Peak</div>
                            <div className="font-semibold text-green-700">
                              ${selectedRateData.touRates.offPeak.toFixed(3)}/kWh
                            </div>
                            <div className="text-xs text-green-600 mt-1">
                              {selectedRateData.touRates.offPeakHours}
                            </div>
                          </div>
                          {selectedRateData.touRates.superOffPeak && (
                            <div className="p-2 bg-blue-50 rounded">
                              <div className="text-xs text-blue-600 font-medium">
                                Super Off-Peak
                              </div>
                              <div className="font-semibold text-blue-700">
                                ${selectedRateData.touRates.superOffPeak.toFixed(3)}/kWh
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    )}

                    <div className="pt-4 border-t border-gray-200">
                      <div className="text-xs text-gray-500">
                        <div className="mb-1">
                          <strong>Effective:</strong> {selectedRateData.effectiveDate}
                        </div>
                        <div>
                          <strong>Source:</strong> {selectedRateData.source}
                        </div>
                      </div>
                    </div>

                    <div className="pt-4">
                      <div className="p-4 bg-purple-50 rounded-lg">
                        <div className="text-sm text-purple-900 mb-2">Selected Rate</div>
                        <div className="text-3xl font-bold text-purple-600">
                          ${getRateValue(selectedRateData).toFixed(3)}
                          <span className="text-lg">/kWh</span>
                        </div>
                        {useTOU && selectedRateData.hasTOU && (
                          <div className="text-xs text-purple-700 mt-1">Peak TOU Rate</div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="p-8 text-center text-gray-500">
                  <div className="text-4xl mb-2">⚡</div>
                  <p>Select a utility to view rate details</p>
                </div>
              )}
            </div>
          </div>

          {/* Info Banner */}
          <div className="mt-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
            <div className="flex items-start">
              <span className="text-2xl mr-3">💡</span>
              <div className="flex-1">
                <h4 className="font-semibold text-yellow-900 mb-1">About These Rates</h4>
                <p className="text-sm text-yellow-800">
                  Rates are updated regularly from public utility tariff schedules. Actual rates may
                  vary based on specific rate schedules, time of use, demand charges, and other
                  factors. Always verify with your local utility for the most accurate pricing.
                  These rates are for estimation purposes only.
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 flex justify-between items-center">
          <button
            onClick={onClose}
            className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-md"
          >
            Cancel
          </button>
          <button
            onClick={handleApplyRate}
            disabled={!selectedRateData}
            className={`px-6 py-2 rounded-md font-semibold ${
              selectedRateData
                ? "bg-purple-600 text-white hover:bg-purple-700"
                : "bg-gray-300 text-gray-500 cursor-not-allowed"
            }`}
          >
            Apply Rate to Quote
          </button>
        </div>
      </div>
    </div>
  );
};

export default UtilityRatesManager;

import React, { useState, useEffect } from "react";

interface Vendor {
  id: string;
  name: string;
  contact_email: string;
  contact_phone?: string;
  address?: string;
  website?: string;
  specialty?: string;
  notes?: string;
  created_at?: string;
  updated_at?: string;
}

interface Product {
  id: string;
  vendor_id: string;
  name: string;
  category: string;
  model_number?: string;
  specifications?: any;
  price?: number;
  unit?: string;
  availability?: string;
  created_at?: string;
  updated_at?: string;
}

interface VendorQuote {
  id: string;
  vendor_id: string;
  vendor_name?: string;
  file_name: string;
  file_url?: string;
  upload_date: string;
  pricing_data?: {
    battery_kwh?: number;
    pcs_kw?: number;
    bos_percent?: number;
    epc_percent?: number;
    notes?: string;
  };
}

interface VendorManagerProps {
  isOpen: boolean;
  onClose: () => void;
}

const VendorManager: React.FC<VendorManagerProps> = ({ isOpen, onClose }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendorQuotes, setVendorQuotes] = useState<VendorQuote[]>([]);
  const [selectedVendor, setSelectedVendor] = useState<Vendor | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<"vendors" | "products" | "quotes">("quotes");
  const [showAddVendor, setShowAddVendor] = useState(false);
  const [showUploadQuote, setShowUploadQuote] = useState(false);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [quotePricing, setQuotePricing] = useState({
    battery_kwh: "",
    pcs_kw: "",
    bos_percent: "",
    epc_percent: "",
    notes: "",
  });

  const [newVendor, setNewVendor] = useState({
    name: "",
    contact_email: "",
    contact_phone: "",
    address: "",
    website: "",
    specialty: "",
    notes: "",
  });

  // Disabled localhost API since server is down - using local storage fallback
  const API_BASE = "/api/db"; // Always use production API path or fallback to local storage

  useEffect(() => {
    if (isOpen) {
      fetchVendors();
      fetchVendorQuotes();
    }
  }, [isOpen]);

  const fetchVendorQuotes = async () => {
    // For now, use local storage
    const stored = localStorage.getItem("vendor_quotes");
    if (stored) {
      setVendorQuotes(JSON.parse(stored));
    }
  };

  const fetchVendors = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`${API_BASE}/vendors`);
      if (response.ok) {
        const data = await response.json();
        setVendors(data);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };

  const fetchVendorProducts = async (vendorId: string) => {
    try {
      const response = await fetch(`${API_BASE}/vendors/${vendorId}/products`);
      if (response.ok) {
        const data = await response.json();
        setProducts(data);
      }
    } catch (error) {
      console.error('Failed to fetch vendor products:', error);
    }
  };

  const createVendor = async () => {
    if (!newVendor.name || !newVendor.contact_email) return;

    try {
      const response = await fetch(`${API_BASE}/vendors`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newVendor),
      });

      if (response.ok) {
        setNewVendor({
          name: "",
          contact_email: "",
          contact_phone: "",
          address: "",
          website: "",
          specialty: "",
          notes: "",
        });
        setShowAddVendor(false);
        fetchVendors();
      }
    } catch (error) {
      console.error('Failed to create vendor:', error);
    }
  };

  const handleVendorSelect = (vendor: Vendor) => {
    setSelectedVendor(vendor);
    setActiveTab("products");
    fetchVendorProducts(vendor.id);
  };

  const handleUploadQuote = () => {
    if (!uploadFile || !selectedVendor) return;

    const newQuote: VendorQuote = {
      id: Date.now().toString(),
      vendor_id: selectedVendor.id,
      vendor_name: selectedVendor.name,
      file_name: uploadFile.name,
      upload_date: new Date().toISOString(),
      pricing_data: {
        battery_kwh: quotePricing.battery_kwh ? parseFloat(quotePricing.battery_kwh) : undefined,
        pcs_kw: quotePricing.pcs_kw ? parseFloat(quotePricing.pcs_kw) : undefined,
        bos_percent: quotePricing.bos_percent
          ? parseFloat(quotePricing.bos_percent) / 100
          : undefined,
        epc_percent: quotePricing.epc_percent
          ? parseFloat(quotePricing.epc_percent) / 100
          : undefined,
        notes: quotePricing.notes,
      },
    };

    const updated = [...vendorQuotes, newQuote];
    setVendorQuotes(updated);
    localStorage.setItem("vendor_quotes", JSON.stringify(updated));

    // Reset form
    setUploadFile(null);
    setQuotePricing({ battery_kwh: "", pcs_kw: "", bos_percent: "", epc_percent: "", notes: "" });
    setShowUploadQuote(false);
  };

  const deleteQuote = (quoteId: string) => {
    const updated = vendorQuotes.filter((q) => q.id !== quoteId);
    setVendorQuotes(updated);
    localStorage.setItem("vendor_quotes", JSON.stringify(updated));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-6xl h-5/6 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b">
          <h2 className="text-2xl font-bold text-gray-800">Vendor & Product Manager</h2>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700 text-2xl">
            ×
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b">
          <button
            onClick={() => setActiveTab("quotes")}
            className={`px-6 py-3 font-medium ${
              activeTab === "quotes"
                ? "text-blue-600 border-b-2 border-blue-600"
                : "text-gray-500 hover:text-gray-700"
            }`}
          >
            📋 Vendor Quotes ({vendorQuotes.length})
          </button>
          <button
            onClick={() => setActiveTab("vendors")}
            className={`px-6 py-3 font-medium ${
              activeTab === "vendors"
                ? "text-blue-600 border-b-2 border-blue-600"
                : "text-gray-500 hover:text-gray-700"
            }`}
          >
            🏢 Vendors ({vendors.length})
          </button>
          <button
            onClick={() => setActiveTab("products")}
            className={`px-6 py-3 font-medium ${
              activeTab === "products"
                ? "text-blue-600 border-b-2 border-blue-600"
                : "text-gray-500 hover:text-gray-700"
            }`}
          >
            📦 Products ({products.length})
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden">
          {activeTab === "quotes" && (
            <div className="h-full p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold">Uploaded Vendor Quotes</h3>
                <button
                  onClick={() => {
                    if (vendors.length === 0) {
                      alert("Please add vendors first in the Vendors tab");
                      return;
                    }
                    setShowUploadQuote(true);
                  }}
                  className="bg-green-600 text-white py-2 px-4 rounded hover:bg-green-700 flex items-center gap-2"
                >
                  📤 Upload Quote
                </button>
              </div>

              {vendorQuotes.length === 0 ? (
                <div className="text-center text-gray-500 mt-12">
                  <div className="text-6xl mb-4">📋</div>
                  <p className="text-lg">No vendor quotes uploaded yet</p>
                  <p className="text-sm mt-2">
                    Upload vendor quotes to compare pricing with Merlin's estimates
                  </p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {vendorQuotes.map((quote) => (
                    <div
                      key={quote.id}
                      className="border rounded-lg p-4 hover:shadow-lg transition-shadow"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h4 className="font-bold text-lg">
                            {quote.vendor_name || "Unknown Vendor"}
                          </h4>
                          <p className="text-sm text-gray-600">{quote.file_name}</p>
                          <p className="text-xs text-gray-400">
                            {new Date(quote.upload_date).toLocaleDateString()}
                          </p>
                        </div>
                        <button
                          onClick={() => deleteQuote(quote.id)}
                          className="text-red-500 hover:text-red-700 text-xl"
                          title="Delete quote"
                        >
                          🗑️
                        </button>
                      </div>

                      {quote.pricing_data && (
                        <div className="bg-gray-50 p-3 rounded space-y-2">
                          <div className="text-sm font-medium text-gray-700">Pricing Data:</div>
                          {quote.pricing_data.battery_kwh && (
                            <div className="flex justify-between text-sm">
                              <span>Battery:</span>
                              <span className="font-bold">
                                ${quote.pricing_data.battery_kwh}/kWh
                              </span>
                            </div>
                          )}
                          {quote.pricing_data.pcs_kw && (
                            <div className="flex justify-between text-sm">
                              <span>PCS:</span>
                              <span className="font-bold">${quote.pricing_data.pcs_kw}/kW</span>
                            </div>
                          )}
                          {quote.pricing_data.bos_percent !== undefined && (
                            <div className="flex justify-between text-sm">
                              <span>BOS:</span>
                              <span className="font-bold">
                                {(quote.pricing_data.bos_percent * 100).toFixed(1)}%
                              </span>
                            </div>
                          )}
                          {quote.pricing_data.epc_percent !== undefined && (
                            <div className="flex justify-between text-sm">
                              <span>EPC:</span>
                              <span className="font-bold">
                                {(quote.pricing_data.epc_percent * 100).toFixed(1)}%
                              </span>
                            </div>
                          )}
                          {quote.pricing_data.notes && (
                            <div className="text-xs text-gray-600 mt-2 italic">
                              {quote.pricing_data.notes}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === "vendors" && (
            <div className="h-full flex">
              {/* Vendor List */}
              <div className="w-1/3 border-r h-full overflow-y-auto">
                <div className="p-4 border-b">
                  <button
                    onClick={() => setShowAddVendor(true)}
                    className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700"
                  >
                    Add New Vendor
                  </button>
                </div>

                {isLoading ? (
                  <div className="p-4 text-center">Loading vendors...</div>
                ) : (
                  <div className="space-y-2 p-4">
                    {vendors.map((vendor) => (
                      <div
                        key={vendor.id}
                        onClick={() => handleVendorSelect(vendor)}
                        className={`p-3 rounded border cursor-pointer hover:bg-gray-50 ${
                          selectedVendor?.id === vendor.id ? "bg-blue-50 border-blue-300" : ""
                        }`}
                      >
                        <div className="font-semibold">{vendor.name}</div>
                        <div className="text-sm text-gray-600">{vendor.contact_email}</div>
                        {vendor.specialty && (
                          <div className="text-xs text-blue-600 mt-1">{vendor.specialty}</div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Vendor Details */}
              <div className="flex-1 p-6">
                {selectedVendor ? (
                  <div className="space-y-4">
                    <h3 className="text-xl font-bold">{selectedVendor.name}</h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700">Email</label>
                        <div className="text-gray-900">{selectedVendor.contact_email}</div>
                      </div>
                      {selectedVendor.contact_phone && (
                        <div>
                          <label className="block text-sm font-medium text-gray-700">Phone</label>
                          <div className="text-gray-900">{selectedVendor.contact_phone}</div>
                        </div>
                      )}
                      {selectedVendor.website && (
                        <div>
                          <label className="block text-sm font-medium text-gray-700">Website</label>
                          <a
                            href={selectedVendor.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-blue-600 hover:underline"
                          >
                            {selectedVendor.website}
                          </a>
                        </div>
                      )}
                      {selectedVendor.specialty && (
                        <div>
                          <label className="block text-sm font-medium text-gray-700">
                            Specialty
                          </label>
                          <div className="text-gray-900">{selectedVendor.specialty}</div>
                        </div>
                      )}
                    </div>
                    {selectedVendor.address && (
                      <div>
                        <label className="block text-sm font-medium text-gray-700">Address</label>
                        <div className="text-gray-900">{selectedVendor.address}</div>
                      </div>
                    )}
                    {selectedVendor.notes && (
                      <div>
                        <label className="block text-sm font-medium text-gray-700">Notes</label>
                        <div className="text-gray-900">{selectedVendor.notes}</div>
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="text-center text-gray-500 mt-8">
                    Select a vendor to view details
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === "products" && (
            <div className="h-full p-6">
              {selectedVendor ? (
                <div>
                  <h3 className="text-xl font-bold mb-4">Products from {selectedVendor.name}</h3>
                  {products.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                      {products.map((product) => (
                        <div key={product.id} className="border rounded-lg p-4">
                          <h4 className="font-semibold">{product.name}</h4>
                          <div className="text-sm text-gray-600 mb-2">{product.category}</div>
                          {product.model_number && (
                            <div className="text-sm">Model: {product.model_number}</div>
                          )}
                          {product.price && (
                            <div className="text-lg font-bold text-green-600 mt-2">
                              ${product.price.toLocaleString()}
                              {product.unit && ` / ${product.unit}`}
                            </div>
                          )}
                          {product.availability && (
                            <div className="text-xs text-blue-600 mt-1">{product.availability}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center text-gray-500 mt-8">
                      No products found for this vendor
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-center text-gray-500 mt-8">
                  Select a vendor to view their products
                </div>
              )}
            </div>
          )}
        </div>

        {/* Add Vendor Modal */}
        {showAddVendor && (
          <div className="absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center">
            <div className="bg-white rounded-lg p-6 w-full max-w-md">
              <h3 className="text-lg font-bold mb-4">Add New Vendor</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Company Name *
                  </label>
                  <input
                    type="text"
                    value={newVendor.name}
                    onChange={(e) => setNewVendor({ ...newVendor, name: e.target.value })}
                    className="w-full border rounded-md px-3 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Contact Email *
                  </label>
                  <input
                    type="email"
                    value={newVendor.contact_email}
                    onChange={(e) => setNewVendor({ ...newVendor, contact_email: e.target.value })}
                    className="w-full border rounded-md px-3 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                  <input
                    type="tel"
                    value={newVendor.contact_phone}
                    onChange={(e) => setNewVendor({ ...newVendor, contact_phone: e.target.value })}
                    className="w-full border rounded-md px-3 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Specialty</label>
                  <input
                    type="text"
                    value={newVendor.specialty}
                    onChange={(e) => setNewVendor({ ...newVendor, specialty: e.target.value })}
                    className="w-full border rounded-md px-3 py-2"
                    placeholder="e.g., Battery Systems, Solar Panels"
                  />
                </div>
              </div>
              <div className="flex justify-end space-x-3 mt-6">
                <button
                  onClick={() => setShowAddVendor(false)}
                  className="px-4 py-2 border rounded-md hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={createVendor}
