                      <label className="block text-xs text-gray-700 mb-1">Battery ($/kWh)</label>
                      <input
                        type="number"
                        step="0.01"
                        value={quotePricing.battery_kwh}
                        onChange={(e) =>
                          setQuotePricing({ ...quotePricing, battery_kwh: e.target.value })
                        }
                        className="w-full border rounded-md px-2 py-1 text-sm"
                        placeholder="250.00"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-gray-700 mb-1">PCS ($/kW)</label>
                      <input
                        type="number"
                        step="0.01"
                        value={quotePricing.pcs_kw}
                        onChange={(e) =>
                          setQuotePricing({ ...quotePricing, pcs_kw: e.target.value })
                        }
                        className="w-full border rounded-md px-2 py-1 text-sm"
                        placeholder="200.00"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-gray-700 mb-1">BOS (%)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={quotePricing.bos_percent}
                        onChange={(e) =>
                          setQuotePricing({ ...quotePricing, bos_percent: e.target.value })
                        }
                        className="w-full border rounded-md px-2 py-1 text-sm"
                        placeholder="15"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-gray-700 mb-1">EPC (%)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={quotePricing.epc_percent}
                        onChange={(e) =>
                          setQuotePricing({ ...quotePricing, epc_percent: e.target.value })
                        }
                        className="w-full border rounded-md px-2 py-1 text-sm"
                        placeholder="10"
                      />
                    </div>
                  </div>
                  <div className="mt-3">
                    <label className="block text-xs text-gray-700 mb-1">Notes</label>
                    <textarea
                      value={quotePricing.notes}
                      onChange={(e) => setQuotePricing({ ...quotePricing, notes: e.target.value })}
                      className="w-full border rounded-md px-2 py-1 text-sm"
                      rows={2}
                      placeholder="Additional notes about this quote..."
                    />
                  </div>
                </div>
              </div>
              <div className="flex justify-end space-x-3 mt-6">
                <button
                  onClick={() => {
                    setShowUploadQuote(false);
                    setUploadFile(null);
                    setQuotePricing({
                      battery_kwh: "",
                      pcs_kw: "",
                      bos_percent: "",
                      epc_percent: "",
                      notes: "",
                    });
                  }}
                  className="px-4 py-2 border rounded-md hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleUploadQuote}
                  disabled={!uploadFile || !selectedVendor}
                  className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-gray-300"
                >
                  Upload Quote
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorManager;

import React, { useState, useEffect } from "react";
import { Upload, FileText, DollarSign, CheckCircle, Clock, TrendingUp, Building2, AlertCircle, Loader2 } from "lucide-react";
import {
  registerVendor,
  loginVendor,
  logoutVendor,
  getCurrentVendor,
  submitProduct,
  getVendorProducts,
  getOpenRFQs,
  getVendorStats,
  type VendorRegistrationData,
  type ProductSubmissionData,
} from "@/services/vendorService";
import type { Vendor, VendorProduct, RFQ } from "@/services/supabaseClient";

interface PricingSubmission {
  id: string;
  product_category: string;
  model: string;
  price_per_kwh?: number;
  price_per_kw?: number;
  lead_time_weeks: number;
  warranty_years: number;
  status: "pending" | "approved" | "rejected";
  submitted_date: string;
}

const VendorPortal: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentVendor, setCurrentVendor] = useState<Vendor | null>(null);
  const [activeTab, setActiveTab] = useState<"dashboard" | "submit-pricing" | "rfqs" | "profile">(
    "dashboard"
  );
  const [showRegistration, setShowRegistration] = useState(false);

  // Dashboard data
  const [vendorProducts, setVendorProducts] = useState<VendorProduct[]>([]);
  const [openRFQs, setOpenRFQs] = useState<RFQ[]>([]);
  const [stats, setStats] = useState<{
    pendingProducts: number;
    approvedProducts: number;
    activeSubmissions: number;
    openRFQs: number;
    quotesThisMonth: number;
    unreadNotifications: number;
  } | null>(null);

  const [loginForm, setLoginForm] = useState({ email: "", password: "" });
  const [registrationForm, setRegistrationForm] = useState({
    company: "",
    contact_name: "",
    email: "",
    phone: "",
    password: "",
    specialty: "" as "battery" | "inverter" | "ems" | "bos" | "epc" | "integrator" | "",
    website: "",
    description: "",
  });

  const [pricingForm, setPricingForm] = useState({
    product_category: "battery" as "battery" | "inverter" | "ems" | "bos" | "container",
    manufacturer: "",
    model: "",
    capacity_kwh: "",
    power_kw: "",
    price_per_kwh: "",
    price_per_kw: "",
    lead_time_weeks: "",
    warranty_years: "",
    certifications: "",
    datasheet: null as File | null,
  });

  // Check for existing session on mount
  useEffect(() => {
    const checkSession = async () => {
      try {
        const vendor = await getCurrentVendor();
        if (vendor) {
          setCurrentVendor(vendor);
          setIsLoggedIn(true);
          await loadDashboardData();
        }
      } catch (err) {
        // No session, that's fine
        console.log("No active vendor session");
      } finally {
        setIsLoading(false);
      }
    };
    checkSession();
  }, []);

  // Load dashboard data when logged in
  const loadDashboardData = async () => {
    try {
      const [products, rfqs, vendorStats] = await Promise.all([
        getVendorProducts(),
        getOpenRFQs(),
        getVendorStats(),
      ]);
      setVendorProducts(products);
      setOpenRFQs(rfqs);
      setStats(vendorStats);
    } catch (err: any) {
      console.error("Error loading dashboard data:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      const result = await loginVendor({
        email: loginForm.email,
        password: loginForm.password,
      });

      if (result.success && result.vendor) {
        setCurrentVendor(result.vendor);
        setIsLoggedIn(true);
        await loadDashboardData();
      } else {
        setError(result.error || "Login failed. Please check your credentials.");
      }
    } catch (err: any) {
      setError(err.message || "An error occurred during login.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = async () => {
    try {
      await logoutVendor();
      setIsLoggedIn(false);
      setCurrentVendor(null);
      setVendorProducts([]);
      setOpenRFQs([]);
      setStats(null);
    } catch (err: any) {
      console.error("Logout error:", err);
    }
  };

  const handleRegistration = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (
      !registrationForm.company ||
      !registrationForm.email ||
      !registrationForm.contact_name ||
      !registrationForm.password ||
      !registrationForm.specialty
    ) {
      setError("Please fill in all required fields");
      return;
    }

    if (registrationForm.password.length < 8) {
      setError("Password must be at least 8 characters");
      return;
    }

    setIsLoading(true);

    try {
      const registrationData: VendorRegistrationData = {
        company_name: registrationForm.company,
        contact_name: registrationForm.contact_name,
        email: registrationForm.email,
        phone: registrationForm.phone || undefined,
        password: registrationForm.password,
        specialty: registrationForm.specialty as VendorRegistrationData["specialty"],
        website: registrationForm.website || undefined,
        description: registrationForm.description || undefined,
      };

      const result = await registerVendor(registrationData);

      if (result.success) {
        alert(
          "Registration submitted successfully! Your account is pending approval. You'll receive an email confirmation once approved."
        );
        setShowRegistration(false);
        setRegistrationForm({
          company: "",
          contact_name: "",
          email: "",
          phone: "",
          password: "",
          specialty: "",
          website: "",
          description: "",
        });
      } else {
        setError(result.error || "Registration failed");
      }
    } catch (err: any) {
      setError(err.message || "An error occurred during registration.");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePricingSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!pricingForm.manufacturer || !pricingForm.model) {
      setError("Please fill in manufacturer and model");
      return;
    }

    if (!pricingForm.price_per_kwh && !pricingForm.price_per_kw) {
      setError("Please provide either price per kWh or price per kW");
      return;
    }

    if (!pricingForm.lead_time_weeks || !pricingForm.warranty_years) {
      setError("Please provide lead time and warranty information");
      return;
    }

    setIsLoading(true);

    try {
      const productData: ProductSubmissionData = {
        product_category: pricingForm.product_category,
        manufacturer: pricingForm.manufacturer,
        model: pricingForm.model,
        capacity_kwh: pricingForm.capacity_kwh ? parseFloat(pricingForm.capacity_kwh) : undefined,
        power_kw: pricingForm.power_kw ? parseFloat(pricingForm.power_kw) : undefined,
        price_per_kwh: pricingForm.price_per_kwh
          ? parseFloat(pricingForm.price_per_kwh)
          : undefined,
        price_per_kw: pricingForm.price_per_kw ? parseFloat(pricingForm.price_per_kw) : undefined,
        lead_time_weeks: parseInt(pricingForm.lead_time_weeks),
        warranty_years: parseInt(pricingForm.warranty_years),
        certifications: pricingForm.certifications
          ? pricingForm.certifications.split(",").map((c) => c.trim())
          : undefined,
      };

      await submitProduct(productData);

      alert(
        "Pricing submitted successfully! Our team will review and update our pricing database within 48 hours."
      );
      setPricingForm({
        product_category: "battery",
        manufacturer: "",
        model: "",
        capacity_kwh: "",
        power_kw: "",
        price_per_kwh: "",
        price_per_kw: "",
        lead_time_weeks: "",
        warranty_years: "",
        certifications: "",
        datasheet: null,
      });

      // Reload products
      const products = await getVendorProducts();
      setVendorProducts(products);
    } catch (err: any) {
      setError(err.message || "Failed to submit pricing");
    } finally {
      setIsLoading(false);
    }
  };

  // Show loading spinner while checking session
  if (isLoading && !isLoggedIn && !showRegistration) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 via-white to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-purple-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-600">Loading vendor portal...</p>
        </div>
      </div>
    );
  }

  // Login/Registration Screen
  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 via-white to-blue-50 py-12 px-4">
