/**
 * Migration Manager Component
 * 
 * Purpose: Admin UI for managing the migration from useCaseTemplates.ts to database
 * Features: Run migration, validate, rollback, cache management
 */

import React, { useState, useEffect } from 'react';
import {
  migrateTemplatesToDatabase,
  validateMigration,
  rollbackMigration,
  getMigrationStatus,
  type MigrationResult
} from '../../services/templateMigrationService';
import {
  clearExpiredCache,
  clearAllCache,
  getCacheStats
} from '../../services/dataIntegrationService';

interface MigrationStatus {
  templatesInCode: number;
  templatesInDatabase: number;
  equipmentInCode: number;
  equipmentInDatabase: number;
  needsMigration: boolean;
  details: Array<{
    slug: string;
    name: string;
    inDatabase: boolean;
    equipmentInCode: number;
    equipmentInDatabase: number;
  }>;
}

interface CacheStats {
  total: number;
  avgExecutionTimeMs: number;
  oldestEntry: any;
  newestEntry: any;
}

const MigrationManager: React.FC = () => {
  const [status, setStatus] = useState<MigrationStatus | null>(null);
  const [cacheStats, setCacheStats] = useState<CacheStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<MigrationResult | null>(null);
  const [validationResult, setValidationResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadStatus();
    loadCacheStats();
  }, []);

  const loadStatus = async () => {
    setLoading(true);
    setError(null);
    try {
      const statusData = await getMigrationStatus();
      setStatus(statusData);
    } catch (err: any) {
      setError(err.message || 'Failed to load migration status');
    } finally {
      setLoading(false);
    }
  };

  const loadCacheStats = async () => {
    try {
      const stats = await getCacheStats();
      setCacheStats(stats);
    } catch (err: any) {
      console.error('Failed to load cache stats:', err);
    }
  };

  const handleMigrate = async () => {
    if (!confirm('This will migrate all use case templates and equipment from code to the database. Continue?')) {
      return;
    }

    setError(null);
    setResult(null);
    try {
      const migrationResult = await migrateTemplatesToDatabase();
      setResult(migrationResult);
      await loadStatus();
      await loadCacheStats();
    } catch (err: any) {
      setError(err.message || 'Migration failed');
    }
  };

  const handleValidate = async () => {
    setError(null);
    setValidationResult(null);
    try {
      const validation = await validateMigration();
      setValidationResult(validation);
    } catch (err: any) {
      setError(err.message || 'Validation failed');
    }
  };

  const handleRollback = async () => {
    if (!confirm('⚠️ WARNING: This will DELETE all migrated data from the database and cannot be undone. Are you sure?')) {
      return;
    }

    setError(null);
    try {
      const rollbackResult = await rollbackMigration();
      alert(`Rollback complete. Deleted: ${rollbackResult.templatesDeleted} templates.`);
      await loadStatus();
    } catch (err: any) {
      setError(err.message || 'Rollback failed');
    }
  };

  const handleClearExpiredCache = async () => {
    try {
      const deleted = await clearExpiredCache();
      alert(`Cleared ${deleted} expired cache entries`);
      await loadCacheStats();
    } catch (err: any) {
      setError(err.message || 'Failed to clear expired cache');
    }
  };

  const handleClearAllCache = async () => {
    if (!confirm('Clear ALL cache entries? This will force recalculation for all requests.')) {
      return;
    }

    try {
      const deleted = await clearAllCache();
      alert(`Cleared ${deleted} cache entries`);
      await loadCacheStats();
    } catch (err: any) {
      setError(err.message || 'Failed to clear cache');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-white">🔄 Data Migration Manager</h2>
        <button
          onClick={loadStatus}
          disabled={loading}
          className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-lg font-semibold transition-all disabled:opacity-50"
        >
          ↻ Refresh Status
        </button>
      </div>

      {error && (
        <div className="bg-red-600/20 border border-red-500/50 p-4 rounded-lg">
          <p className="text-red-300">
            <strong>❌ Error:</strong> {error}
          </p>
        </div>
      )}

      {status && (
        <>
          <div className="bg-slate-800/50 p-6 rounded-lg border border-purple-500/30">
            <h3 className="text-xl font-bold text-white mb-4">📊 Migration Status</h3>

            <div className="grid md:grid-cols-3 gap-4 mb-6">
              <div className="bg-blue-600/20 p-4 rounded-lg border border-blue-500/30">
                <p className="text-blue-300 text-sm mb-1">IN CODE</p>
                <p className="text-white font-bold text-3xl">{status.templatesInCode}</p>
              </div>
              <div className="bg-green-600/20 p-4 rounded-lg border border-green-500/30">
                <p className="text-green-300 text-sm mb-1">IN DATABASE</p>
                <p className="text-white font-bold text-3xl">{status.templatesInDatabase}</p>
              </div>
              <div className="bg-orange-600/20 p-4 rounded-lg border border-orange-500/30">
                <p className="text-orange-300 text-sm mb-1">NEEDS MIGRATION</p>
                <p className="text-white font-bold text-3xl">{status.templatesInCode - status.templatesInDatabase}</p>
              </div>
            </div>

            <div className="bg-slate-900/50 rounded-lg p-4">
              <h4 className="text-white font-semibold mb-3">Template Details</h4>
              <div className="space-y-2">
                {status.details.map((template) => (
                  <div
                    key={template.slug}
                    className="flex items-center justify-between py-2 border-b border-slate-700/50 last:border-0"
                  >
                    <div className="flex items-center gap-3">
                      <span className="text-2xl">{template.inDatabase ? '✅' : '❌'}</span>
                      <div>
                        <p className="text-white font-medium">{template.slug}</p>
                        <p className="text-gray-400 text-sm">
                          Code: {template.equipmentInCode} | DB: {template.equipmentInDatabase} equipment
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="bg-slate-800/50 p-6 rounded-lg border border-purple-500/30">
            <h3 className="text-xl font-bold text-white mb-4">⚡ Migration Actions</h3>

            <div className="grid md:grid-cols-2 gap-4">
              <button
                onClick={handleMigrate}
                disabled={!status || (status.templatesInCode - status.templatesInDatabase) === 0}
                className="bg-gradient-to-br from-green-600 to-green-700 hover:from-green-500 hover:to-green-600 p-6 rounded-lg text-white font-semibold transition-all shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <div className="text-3xl mb-2">🚀</div>
                <div className="text-lg mb-1">Run Migration</div>
                <div className="text-sm text-green-100">
                  {status && (status.templatesInCode - status.templatesInDatabase) === 0
                    ? 'All templates already migrated'
                    : `Migrate ${status ? status.templatesInCode - status.templatesInDatabase : 0} templates`
                  }
                </div>
              </button>

              <button
                onClick={handleValidate}
                disabled={!status || status.templatesInDatabase === 0}
                className="bg-gradient-to-br from-blue-600 to-blue-700 hover:from-blue-500 hover:to-blue-600 p-6 rounded-lg text-white font-semibold transition-all shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <div className="text-3xl mb-2">✓</div>
                <div className="text-lg mb-1">Validate Migration</div>
                <div className="text-sm text-blue-100">Check data integrity</div>
              </button>

              <button
                onClick={handleRollback}
                disabled={!status || status.templatesInDatabase === 0}
                className="bg-gradient-to-br from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 p-6 rounded-lg text-white font-semibold transition-all shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <div className="text-3xl mb-2">⚠️</div>
                <div className="text-lg mb-1">Rollback Migration</div>
                <div className="text-sm text-red-100">⚠️ Deletes all migrated data</div>
              </button>

              <button
                onClick={loadStatus}
                disabled={loading}
                className="bg-gradient-to-br from-purple-600 to-purple-700 hover:from-purple-500 hover:to-purple-600 p-6 rounded-lg text-white font-semibold transition-all shadow-lg disabled:opacity-50"
              >
                <div className="text-3xl mb-2">↻</div>
                <div className="text-lg mb-1">Refresh Status</div>
                <div className="text-sm text-purple-100">Check current state</div>
              </button>
            </div>
          </div>
        </>
      )}

      {result && (
        <div className={`p-6 rounded-lg border ${
          result.success 
            ? 'bg-green-600/20 border-green-500/50' 
            : 'bg-red-600/20 border-red-500/50'
        }`}>
          <h3 className="text-xl font-bold text-white mb-4">
            {result.success ? '✅ Migration Complete' : '❌ Migration Failed'}
          </h3>

          <div className="grid md:grid-cols-3 gap-4 mb-4">
            <div>
              <p className="text-white text-sm mb-1">Templates Created</p>
              <p className="text-white font-bold text-2xl">{result.templatesCreated}</p>
            </div>
            <div>
              <p className="text-white text-sm mb-1">Equipment Created</p>
              <p className="text-white font-bold text-2xl">{result.equipmentCreated}</p>
            </div>
            <div>
              <p className="text-white text-sm mb-1">Errors</p>
              <p className="text-white font-bold text-2xl">{result.errors.length}</p>
            </div>
          </div>

          {result.errors.length > 0 && (
            <div className="bg-black/30 rounded p-3 mb-4">
              <p className="text-white font-semibold mb-2">Errors:</p>
              <ul className="text-red-300 text-sm space-y-1">
                {result.errors.map((error: string, i: number) => (
                  <li key={i}>• {error}</li>
                ))}
              </ul>
            </div>
          )}

          <div className="bg-black/30 rounded p-3">
            <p className="text-white font-semibold mb-2">Details:</p>
            <div className="space-y-2">
              {result.details.map((detail: { templateId: string; name: string; equipmentCount: number }) => (
                <div key={detail.templateId} className="text-sm">
                  <span className="text-green-300">✓</span>
                  <span className="text-white ml-2">{detail.name}</span>
                  <span className="text-gray-400 ml-2">({detail.equipmentCount} equipment)</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {validationResult && (
        <div className={`p-6 rounded-lg border ${
          validationResult.valid 
            ? 'bg-green-600/20 border-green-500/50' 
            : 'bg-orange-600/20 border-orange-500/50'
        }`}>
          <h3 className="text-xl font-bold text-white mb-4">
            {validationResult.valid ? '✅ Validation Passed' : '⚠️ Validation Issues Found'}
          </h3>

          {validationResult.issues && validationResult.issues.length > 0 && (
            <div className="bg-black/30 rounded p-3">
              <p className="text-white font-semibold mb-2">Issues:</p>
              <ul className="text-orange-300 text-sm space-y-1">
                {validationResult.issues.map((issue: string, i: number) => (
                  <li key={i}>• {issue}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {cacheStats && (
        <div className="bg-slate-800/50 p-6 rounded-lg border border-purple-500/30">
          <h3 className="text-xl font-bold text-white mb-4">⚡ Cache Statistics</h3>

          <div className="grid md:grid-cols-4 gap-4 mb-6">
            <div className="bg-purple-600/20 p-4 rounded-lg border border-purple-500/30">
              <p className="text-purple-300 text-sm mb-1">TOTAL ENTRIES</p>
              <p className="text-white font-bold text-3xl">{cacheStats.total}</p>
            </div>
            <div className="bg-blue-600/20 p-4 rounded-lg border border-blue-500/30">
              <p className="text-blue-300 text-sm mb-1">AVG TIME</p>
              <p className="text-white font-bold text-3xl">{Math.round(cacheStats.avgExecutionTimeMs)}ms</p>
            </div>
            <div className="bg-green-600/20 p-4 rounded-lg border border-green-500/30">
              <p className="text-green-300 text-sm mb-1">OLDEST ENTRY</p>
              <p className="text-white font-bold text-lg">
                {cacheStats.oldestEntry ? new Date(cacheStats.oldestEntry).toLocaleDateString() : 'N/A'}
              </p>
            </div>
            <div className="bg-orange-600/20 p-4 rounded-lg border border-orange-500/30">
              <p className="text-orange-300 text-sm mb-1">NEWEST ENTRY</p>
              <p className="text-white font-bold text-lg">
                {cacheStats.newestEntry ? new Date(cacheStats.newestEntry).toLocaleDateString() : 'N/A'}
              </p>
            </div>
          </div>

          <div className="flex gap-4">
            <button
              onClick={handleClearExpiredCache}
              className="bg-yellow-600 hover:bg-yellow-500 text-white px-6 py-3 rounded-lg font-semibold transition-all"
            >
              🧹 Clear Expired Cache
            </button>
            <button
              onClick={handleClearAllCache}
              className="bg-red-600 hover:bg-red-500 text-white px-6 py-3 rounded-lg font-semibold transition-all"
            >
              🗑️ Clear All Cache
            </button>
          </div>
        </div>
      )}

      <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-lg">
        <p className="text-blue-300 text-sm">
          <strong>ℹ️ About Migration:</strong> This tool migrates use case templates from <code className="bg-black/30 px-2 py-1 rounded">useCaseTemplates.ts</code> to the database.
          After migration, the system will use the database as the primary source, with static files as a fallback.
        </p>
      </div>
    </div>
  );
};

export default MigrationManager;

/**
 * PricingAdminDashboard - Database-Driven SSOT Version
 * =====================================================
 * 
 * MIGRATED: December 28, 2025
 * - Reads from pricing_configurations table (Supabase)
 * - Displays TrueQuote™ attribution
 * - Supports inline editing with audit trail
 * - Clears pricing caches on save
 * 
 * Database Schema (pricing_configurations):
 * - id (uuid)
 * - config_key (varchar) - unique identifier
 * - config_category (varchar) - bess, solar, generator, etc.
 * - config_data (jsonb) - the actual pricing values
 * - data_source (varchar) - where the data came from
 * - confidence_level (varchar) - high/medium/low
 * - is_active (boolean)
 * - effective_date, expires_at (timestamptz)
 * - updated_at, created_at (timestamptz)
 * - updated_by (uuid)
 * - vendor_notes (text)
 * - size_min_kw, size_max_kw, size_min_mwh, size_max_mwh (numeric)
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Settings,
  DollarSign,
  Database,
  Save,
  RefreshCw,
  CheckCircle,
  AlertTriangle,
  Search,
  ChevronDown,
  ChevronUp,
  Battery,
  Sun,
  Fuel,
  Zap,
  Wind,
  Cpu,
  Shield,
  Info,
  Edit2,
  X,
  Filter,
  Loader2
} from 'lucide-react';
import { supabase } from '@/services/supabaseClient';
import { adminAuthService } from '@/services/adminAuthService';
import { clearAllPricingCaches } from '@/services/unifiedPricingService';

// ============================================================================
// TYPES
// ============================================================================

interface PricingConfiguration {
  id: string;
  config_key: string;
  config_category: string;
  config_data: Record<string, any>;
  description: string | null;
  version: string | null;
  is_active: boolean;
  effective_date: string | null;
  expires_at: string | null;
  created_at: string;
  updated_at: string;
  updated_by: string | null;
  vendor_notes: string | null;
  data_source: string | null;
  confidence_level: string | null;
  size_min_kw: number | null;
  size_max_kw: number | null;
  size_min_mwh: number | null;
  size_max_mwh: number | null;
}

interface PricingAdminProps {
  isOpen: boolean;
  onClose: () => void;
}

// ============================================================================
// CATEGORY CONFIG
// ============================================================================

const CATEGORY_CONFIG: Record<string, { icon: React.ReactNode; label: string; color: string }> = {
  bess: { icon: <Battery className="w-5 h-5" />, label: 'Battery Storage (BESS)', color: 'cyan' },
  solar: { icon: <Sun className="w-5 h-5" />, label: 'Solar PV', color: 'yellow' },
  generator: { icon: <Fuel className="w-5 h-5" />, label: 'Generators', color: 'orange' },
  ev_charger: { icon: <Zap className="w-5 h-5" />, label: 'EV Chargers', color: 'green' },
  wind: { icon: <Wind className="w-5 h-5" />, label: 'Wind', color: 'blue' },
  fuel_cell: { icon: <Cpu className="w-5 h-5" />, label: 'Fuel Cells', color: 'purple' },
  power_electronics: { icon: <Cpu className="w-5 h-5" />, label: 'Power Electronics', color: 'indigo' },
  transformer: { icon: <Zap className="w-5 h-5" />, label: 'Transformers', color: 'slate' },
  switchgear: { icon: <Settings className="w-5 h-5" />, label: 'Switchgear', color: 'gray' },
  incentives: { icon: <DollarSign className="w-5 h-5" />, label: 'Incentives', color: 'emerald' },
  safety: { icon: <Shield className="w-5 h-5" />, label: 'Safety Systems', color: 'red' },
  hvac: { icon: <Wind className="w-5 h-5" />, label: 'HVAC / Thermal', color: 'teal' },
  controls: { icon: <Cpu className="w-5 h-5" />, label: 'Controls / BMS', color: 'violet' },
  ui_config: { icon: <Settings className="w-5 h-5" />, label: 'UI Configuration', color: 'pink' },
  electricity_rates: { icon: <Zap className="w-5 h-5" />, label: 'Electricity Rates', color: 'amber' },
};

// ============================================================================
// COMPONENT
// ============================================================================

export const PricingAdminDashboard: React.FC<PricingAdminProps> = ({ isOpen, onClose }) => {
  // State
  const [configs, setConfigs] = useState<PricingConfiguration[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [expandedConfigs, setExpandedConfigs] = useState<Set<string>>(new Set());
  const [editingConfig, setEditingConfig] = useState<string | null>(null);
  const [editValues, setEditValues] = useState<Record<string, any>>({});
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [dbStatus, setDbStatus] = useState<'checking' | 'connected' | 'error'>('checking');

  // Permissions
  const canEdit = adminAuthService.hasPermission('edit_pricing');
  const canSave = adminAuthService.hasPermission('save_pricing');

  // Load data on mount
  useEffect(() => {
    if (isOpen) {
      loadConfigurations();
    }
  }, [isOpen]);

  // ============================================================================
  // DATA LOADING
  // ============================================================================

  const loadConfigurations = async () => {
    setLoading(true);
    setError(null);
    setDbStatus('checking');

    try {
      const { data: configData, error: configError } = await supabase
        .from('pricing_configurations')
        .select('*')
        .eq('is_active', true)
        .order('config_category')
        .order('config_key');

      if (configError) {
        throw configError;
      }

      setConfigs(configData || []);
      setDbStatus('connected');
    } catch (err: any) {
      console.error('Failed to load pricing configurations:', err);
      setError(err.message || 'Failed to load configurations');
      setDbStatus('error');
    } finally {
      setLoading(false);
    }
  };

  // ============================================================================
  // FILTERING
  // ============================================================================

  const filteredConfigs = useMemo(() => {
    return configs.filter(config => {
      // Category filter
      if (selectedCategory !== 'all' && config.config_category !== selectedCategory) {
        return false;
      }
      // Search filter
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        return (
          config.config_key.toLowerCase().includes(searchLower) ||
          config.description?.toLowerCase().includes(searchLower) ||
          config.config_category.toLowerCase().includes(searchLower) ||
          JSON.stringify(config.config_data).toLowerCase().includes(searchLower)
        );
      }
      return true;
    });
  }, [configs, selectedCategory, searchTerm]);

  // Get unique categories from data
  const categories = useMemo(() => {
    const cats = new Set(configs.map(c => c.config_category));
    return Array.from(cats).sort();
  }, [configs]);

  // ============================================================================
  // EDITING
  // ============================================================================

  const startEditing = (config: PricingConfiguration) => {
    if (!canEdit) return;
    setEditingConfig(config.id);
    setEditValues(config.config_data);
  };

  const cancelEditing = () => {
    setEditingConfig(null);
    setEditValues({});
  };

  const updateEditValue = (key: string, value: any) => {
    setEditValues(prev => ({ ...prev, [key]: value }));
  };

  const saveConfig = async (configId: string) => {
    if (!canSave) {
      alert('You do not have permission to save pricing configurations.');
      return;
    }

    setSaveStatus('saving');

    try {
      const currentAdmin = adminAuthService.getCurrentAdmin();
      const adminEmail = currentAdmin?.email || null;

      const { error: updateError } = await supabase
        .from('pricing_configurations')
        .update({
          config_data: editValues,
          updated_at: new Date().toISOString(),
          updated_by: adminEmail
        })
        .eq('id', configId);

      if (updateError) throw updateError;

      // Log to audit trail (don't fail if audit log doesn't exist)
      try {
        await supabase.from('pricing_audit_log').insert({
          config_id: configId,
          action: 'update',
          old_value: configs.find(c => c.id === configId)?.config_data,
          new_value: editValues,
          updated_by: adminEmail || 'unknown',
          updated_at: new Date().toISOString()
        });
      } catch (auditError) {
        // Audit log is optional, don't fail if it doesn't exist
        console.warn('Failed to log to audit trail:', auditError);
      }

      // Clear caches
      await clearAllPricingCaches();

      // Reload data
      await loadConfigurations();

      setSaveStatus('saved');
      setEditingConfig(null);
      setEditValues({});

      setTimeout(() => setSaveStatus('idle'), 2000);
    } catch (err: any) {
      console.error('Failed to save configuration:', err);
      setSaveStatus('error');
      alert(`Save failed: ${err.message}`);
    }
  };

  // ============================================================================
  // TOGGLE EXPAND
  // ============================================================================

  const toggleExpand = (configId: string) => {
    setExpandedConfigs(prev => {
      const next = new Set(prev);
      if (next.has(configId)) {
        next.delete(configId);
      } else {
        next.add(configId);
      }
      return next;
    });
  };

  // ============================================================================
  // RENDER HELPERS
  // ============================================================================

  const getConfidenceBadge = (level: string | null) => {
    switch (level) {
      case 'high':
        return <span className="px-2 py-0.5 bg-emerald-500/20 text-emerald-400 text-xs rounded-full">High</span>;
      case 'medium':
        return <span className="px-2 py-0.5 bg-amber-500/20 text-amber-400 text-xs rounded-full">Medium</span>;
      case 'low':
        return <span className="px-2 py-0.5 bg-red-500/20 text-red-400 text-xs rounded-full">Low</span>;
      default:
        return <span className="px-2 py-0.5 bg-slate-500/20 text-slate-400 text-xs rounded-full">Unknown</span>;
    }
  };

  const getCategoryInfo = (category: string) => {
    return CATEGORY_CONFIG[category] || { 
      icon: <Database className="w-5 h-5" />, 
      label: category.replace(/_/g, ' ').toUpperCase(), 
      color: 'slate' 
    };
  };

  const formatValue = (value: any): string => {
    if (typeof value === 'number') {
      if (value >= 1000000) return `$${(value / 1000000).toFixed(2)}M`;
      if (value >= 1000) return `$${(value / 1000).toFixed(1)}K`;
      if (value < 1 && value > 0) return value.toFixed(4);
      return value.toLocaleString();
    }
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    if (typeof value === 'object') return JSON.stringify(value);
    return String(value);
  };

  // ============================================================================
  // RENDER
  // ============================================================================

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 rounded-2xl w-full max-w-6xl max-h-[90vh] overflow-hidden border border-purple-500/30 shadow-2xl">
        {/* Header */}
        <div className="p-6 border-b border-slate-700 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-purple-500/20 rounded-xl">
              <DollarSign className="w-6 h-6 text-purple-400" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">Pricing Configuration</h2>
              <p className="text-slate-400 text-sm">Database-driven pricing (SSOT)</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {/* TrueQuote Badge */}
            <div className="flex items-center gap-2 px-4 py-2 bg-emerald-500/10 border border-emerald-500/30 rounded-full">
              <Shield className="w-4 h-4 text-emerald-400" />
              <span className="text-emerald-400 text-sm font-medium">TrueQuote™</span>
            </div>

            {/* DB Status */}
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm ${
              dbStatus === 'connected' ? 'bg-emerald-500/20 text-emerald-400' :
              dbStatus === 'error' ? 'bg-red-500/20 text-red-400' :
              'bg-amber-500/20 text-amber-400'
            }`}>
              <Database className="w-4 h-4" />
              {dbStatus === 'connected' ? 'Connected' : dbStatus === 'error' ? 'Error' : 'Checking...'}
            </div>

            {/* Refresh */}
            <button
              onClick={loadConfigurations}
              className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
              title="Refresh"
            >
              <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
            </button>

            {/* Close */}
            <button
              onClick={onClose}
              className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="p-4 border-b border-slate-700 flex items-center gap-4 flex-wrap">
          {/* Search */}
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
            <input
              type="text"
              placeholder="Search configurations..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-800 border border-slate-600 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-purple-500"
            />
          </div>

          {/* Category Filter */}
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-slate-500" />
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="px-4 py-2 bg-slate-800 border border-slate-600 rounded-lg text-white focus:outline-none focus:border-purple-500"
            >
              <option value="all">All Categories</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>
                  {getCategoryInfo(cat).label}
                </option>
              ))}
            </select>
          </div>

          {/* Stats */}
          <div className="text-sm text-slate-400">
            Showing {filteredConfigs.length} of {configs.length} configurations
          </div>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[calc(90vh-200px)]">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 text-purple-500 animate-spin" />
            </div>
          ) : error ? (
            <div className="text-center py-12">
              <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-4" />
              <p className="text-red-400">{error}</p>
              <button
                onClick={loadConfigurations}
                className="mt-4 px-4 py-2 bg-slate-700 text-white rounded-lg hover:bg-slate-600"
              >
                Retry
              </button>
            </div>
          ) : filteredConfigs.length === 0 ? (
            <div className="text-center py-12">
              <Database className="w-12 h-12 text-slate-500 mx-auto mb-4" />
              <p className="text-slate-400">No configurations found</p>
            </div>
          ) : (
            <div className="space-y-4">
              {filteredConfigs.map(config => {
                const categoryInfo = getCategoryInfo(config.config_category);
                const isExpanded = expandedConfigs.has(config.id);
                const isEditing = editingConfig === config.id;

                return (
                  <div
                    key={config.id}
                    className={`bg-slate-800/50 border rounded-xl overflow-hidden transition-all ${
                      isExpanded ? 'border-purple-500/50' : 'border-slate-700'
                    }`}
                  >
                    {/* Header Row */}
                    <div
                      className="p-4 flex items-center gap-4 cursor-pointer hover:bg-slate-700/30"
                      onClick={() => toggleExpand(config.id)}
                    >
                      {/* Category Icon */}
                      <div className={`p-2 bg-${categoryInfo.color}-500/20 rounded-lg text-${categoryInfo.color}-400`}>
                        {categoryInfo.icon}
                      </div>

                      {/* Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <h3 className="text-white font-semibold truncate">
                            {config.config_key.replace(/_/g, ' ')}
                          </h3>
                          {getConfidenceBadge(config.confidence_level)}
                        </div>
                        <p className="text-slate-400 text-sm truncate">
                          {config.description || categoryInfo.label}
                        </p>
                      </div>

                      {/* Source */}
                      {config.data_source && (
                        <div className="hidden md:flex items-center gap-1 text-xs text-slate-500">
                          <Info className="w-3 h-3" />
                          {config.data_source}
                        </div>
                      )}

                      {/* Size Range */}
                      {(config.size_min_mwh || config.size_max_mwh) && (
                        <div className="hidden lg:block text-xs text-slate-500">
                          {config.size_min_mwh || 0} - {config.size_max_mwh || '∞'} MWh
                        </div>
                      )}

                      {/* Expand Icon */}
                      <div className="text-slate-400">
                        {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                      </div>
                    </div>

                    {/* Expanded Content */}
                    {isExpanded && (
                      <div className="px-4 pb-4 border-t border-slate-700">
                        {/* Metadata */}
                        <div className="py-3 flex flex-wrap gap-4 text-xs text-slate-500 border-b border-slate-700/50">
                          <span>Updated: {new Date(config.updated_at).toLocaleString()}</span>
                          {config.data_source && <span>Source: {config.data_source}</span>}
                          {config.version && <span>Version: {config.version}</span>}
                        </div>

                        {/* Config Data */}
                        <div className="py-4 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                          {Object.entries(config.config_data).map(([key, value]) => (
                            <div key={key} className="bg-slate-700/30 rounded-lg p-3">
                              <div className="text-xs text-slate-500 mb-1">
                                {key.replace(/_/g, ' ')}
                              </div>
                              {isEditing ? (
                                <input
                                  type={typeof value === 'number' ? 'number' : 'text'}
                                  value={editValues[key] ?? value}
                                  onChange={(e) => updateEditValue(key, 
                                    typeof value === 'number' ? parseFloat(e.target.value) : e.target.value
                                  )}
                                  className="w-full px-2 py-1 bg-slate-600 border border-slate-500 rounded text-white text-sm focus:outline-none focus:border-purple-500"
                                />
                              ) : (
                                <div className="text-white font-medium">
                                  {formatValue(value)}
                                </div>
                              )}
                            </div>
                          ))}
                        </div>

                        {/* Vendor Notes */}
                        {config.vendor_notes && (
                          <div className="py-3 border-t border-slate-700/50">
                            <div className="text-xs text-slate-500 mb-1">Vendor Notes</div>
                            <div className="text-slate-300 text-sm">{config.vendor_notes}</div>
                          </div>
                        )}

                        {/* Actions */}
                        {canEdit && (
                          <div className="pt-4 flex justify-end gap-2 border-t border-slate-700/50">
                            {isEditing ? (
                              <>
                                <button
                                  onClick={cancelEditing}
                                  className="px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-500 transition-colors"
                                >
                                  Cancel
                                </button>
                                <button
                                  onClick={() => saveConfig(config.id)}
                                  disabled={saveStatus === 'saving'}
                                  className="px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-500 transition-colors flex items-center gap-2 disabled:opacity-50"
                                >
                                  {saveStatus === 'saving' ? (
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                  ) : (
                                    <Save className="w-4 h-4" />
                                  )}
                                  Save
                                </button>
                              </>
                            ) : (
                              <button
                                onClick={() => startEditing(config)}
                                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-500 transition-colors flex items-center gap-2"
                              >
                                <Edit2 className="w-4 h-4" />
                                Edit
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-700 flex items-center justify-between text-sm text-slate-500">
          <div className="flex items-center gap-2">
            <Shield className="w-4 h-4 text-emerald-400" />
            <span>All pricing data sourced from NREL ATB 2024 &amp; verified vendor quotes</span>
          </div>
          <div>
            {saveStatus === 'saved' && (
              <span className="text-emerald-400 flex items-center gap-1">
                <CheckCircle className="w-4 h-4" /> Saved successfully
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PricingAdminDashboard;

/**
 * Pricing System Health Dashboard
 * 
 * Monitors the health of the pricing system including:
 * - Market rate pricing updates
 * - ML agent integration status
 * - Price change impact on quotes
 * - System health metrics
 */

import React, { useState, useEffect } from 'react';
import { Activity, AlertTriangle, CheckCircle, Clock, Database, Zap, RefreshCw, BarChart3, DollarSign, Cpu, Cloud, CloudOff, ArrowUp, ArrowDown, Info, Building2 } from 'lucide-react';
import { supabase } from '@/services/supabaseClient';
import { getMarketPriceSummary } from '@/services/marketDataIntegrationService';
import { 
  clearAllPricingCaches 
} from '@/services/unifiedPricingService';
import { dailyPricingValidator } from '@/services/dailyPricingValidator';
import { runMLProcessing } from '@/services/mlProcessingService';

interface PricingHealthMetrics {
  // Market Data Status
  marketDataStatus: 'healthy' | 'degraded' | 'error';
  marketDataPoints: number;
  lastMarketUpdate: Date | null;
  marketDataCoverage: {
    bess: number;
    solar: number;
    generator: number;
    evCharger: number;
    inverter: number;
    transformer: number;
  };

  // ML Agent Status
  mlAgentStatus: 'active' | 'idle' | 'error';
  mlLastProcessed: Date | null;
  mlTrendsGenerated: number;
  mlInsightsGenerated: number;
  mlUnprocessedRecords: number;
  mlProcessingTime: number;

  // Vendor Pricing Status
  vendorPricingStatus: 'active' | 'limited' | 'none';
  approvedVendorProducts: number;
  pendingVendorProducts: number;
  vendorPricingCoverage: {
    battery: number;
    inverter: number;
    ems: number;
    bos: number;
    container: number;
  };
  vendorPricingUtilization: number; // % of quotes using vendor pricing
  vendorPricingLastSync: Date | null;

  // Pricing Configuration Status
  pricingConfigStatus: 'synced' | 'outdated' | 'error';
  pricingConfigLastUpdate: Date | null;
  pricingConfigSource: 'database' | 'localStorage' | 'fallback';

  // Quote Impact Metrics
  quotesUsingMarketData: number;
  quotesUsingDefaults: number;
  quotesUsingVendorPricing: number;
  marketDataUtilizationRate: number;
  averagePriceDeviation: number;

  // System Health
  cacheStatus: 'fresh' | 'stale' | 'expired';
  databaseConnection: 'connected' | 'disconnected' | 'error';
  validationAlerts: number;
  criticalAlerts: number;
}

export const PricingSystemHealthDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<PricingHealthMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [mlTrends, setMlTrends] = useState<any[]>([]);
  const [marketSummaries, setMarketSummaries] = useState<Record<string, any>>({});
  const [validationResults, setValidationResults] = useState<any[]>([]);
  const [lastRefresh, setLastRefresh] = useState<Date>(new Date());
  const [utilityRates, setUtilityRates] = useState<any[]>([]);
  const [utilityRatesLoading, setUtilityRatesLoading] = useState(false);
  const [utilityRatesError, setUtilityRatesError] = useState<string | null>(null);

  useEffect(() => {
    loadHealthMetrics();
    loadUtilityRates();
    // Auto-refresh every 60 seconds
    const interval = setInterval(() => {
      loadHealthMetrics();
      loadUtilityRates();
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  const loadUtilityRates = async () => {
    setUtilityRatesLoading(true);
    setUtilityRatesError(null);
    try {
      const { data, error } = await supabase
        .from('utility_rates_summary')
        .select('*')
        .order('avg_commercial_rate', { ascending: false })
        .limit(50); // Top 50 states by rate

      if (error) {
        console.error('❌ Error loading utility rates:', error);
        setUtilityRatesError(error.message || 'Failed to load utility rates. Please check if the utility_rates_summary view exists in the database.');
        setUtilityRates([]);
        return;
      }
      console.log('✅ Utility rates loaded:', data?.length || 0, 'states');
      setUtilityRates(data || []);
    } catch (error) {
      console.error('❌ Exception loading utility rates:', error);
      setUtilityRatesError(error instanceof Error ? error.message : 'Unknown error loading utility rates');
      setUtilityRates([]);
    } finally {
      setUtilityRatesLoading(false);
    }
  };

  const loadHealthMetrics = async () => {
    setRefreshing(true);
    try {
      console.log('🔄 Refreshing pricing health metrics...');
      // Load all metrics in parallel
      const [
        mlData,
        marketData,
        validationData,
        dbStatus,
        mlTrendsData
      ] = await Promise.all([
        loadMLAgentStatus(),
        loadMarketDataStatus(),
        loadValidationStatus(),
        checkDatabaseConnection(),
        loadMLTrends()
      ]);

      // Calculate market data coverage
      const coverage = await calculateMarketDataCoverage();

      // Calculate quote impact metrics
      const quoteMetrics = await calculateQuoteImpactMetrics();

      // Update last refresh timestamp
      setLastRefresh(new Date());
      console.log('✅ Pricing health metrics refreshed');

      setMetrics({
        // Market Data
        marketDataStatus: marketData.marketDataStatus || 'error',
        marketDataPoints: marketData.marketDataPoints || 0,
        lastMarketUpdate: marketData.lastMarketUpdate || null,
        marketDataCoverage: coverage.marketDataCoverage || {
          bess: 0,
          solar: 0,
          generator: 0,
          evCharger: 0,
          inverter: 0,
          transformer: 0
        },

        // ML Agent
        mlAgentStatus: mlData.mlAgentStatus || 'idle',
        mlLastProcessed: mlData.mlLastProcessed || null,
        mlTrendsGenerated: mlData.mlTrendsGenerated || 0,
        mlInsightsGenerated: mlData.mlInsightsGenerated || 0,
        mlUnprocessedRecords: mlData.mlUnprocessedRecords || 0,
        mlProcessingTime: mlData.mlProcessingTime || 0,

        // Pricing Config
        pricingConfigStatus: 'synced',
        pricingConfigLastUpdate: null,
        pricingConfigSource: 'database',

        // Vendor Pricing (TODO: Load vendor data when vendor service is implemented)
        vendorPricingStatus: 'none',
        approvedVendorProducts: 0,
        pendingVendorProducts: 0,
        vendorPricingCoverage: {
          battery: 0,
          inverter: 0,
          ems: 0,
          bos: 0,
          container: 0,
        },
        vendorPricingUtilization: 0,
        vendorPricingLastSync: null,

        // Quote Impact
        quotesUsingMarketData: quoteMetrics.quotesUsingMarketData || 0,
        quotesUsingDefaults: quoteMetrics.quotesUsingDefaults || 0,
        quotesUsingVendorPricing: quoteMetrics.quotesUsingVendorPricing || 0,
        marketDataUtilizationRate: quoteMetrics.marketDataUtilizationRate || 0,
        averagePriceDeviation: quoteMetrics.averagePriceDeviation || 0,

        // System Health
        cacheStatus: 'fresh',
        databaseConnection: dbStatus.databaseConnection || 'error',
        validationAlerts: validationData.validationAlerts || 0,
        criticalAlerts: validationData.criticalAlerts || 0
      });

      setMlTrends(mlTrendsData);
      setLastRefresh(new Date());
    } catch (error) {
      console.error('Error loading pricing health metrics:', error);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const loadMLAgentStatus = async (): Promise<Partial<PricingHealthMetrics>> => {
    try {
      // Get ML processing log
      const { data: logData } = await supabase
        .from('ml_processing_log')
        .select('*')
        .order('processed_at', { ascending: false })
        .limit(1)
        .single();

      // Get unprocessed records count
      const { count: unprocessedCount } = await supabase
        .from('ai_training_data')
        .select('*', { count: 'exact', head: true })
        .eq('processed_for_ml', false)
        .eq('data_type', 'pricing');

      // Get ML trends count
      const { count: trendsCount } = await supabase
        .from('ml_price_trends')
        .select('*', { count: 'exact', head: true });

      // Get ML insights count
      const { count: insightsCount } = await supabase
        .from('ml_market_insights')
        .select('*', { count: 'exact', head: true });

      const status = logData 
        ? (Date.now() - new Date(logData.processed_at).getTime() < 24 * 60 * 60 * 1000 ? 'active' : 'idle')
        : 'idle';

      return {
        mlAgentStatus: status,
        mlLastProcessed: logData ? new Date(logData.processed_at) : null,
        mlTrendsGenerated: trendsCount || 0,
        mlInsightsGenerated: insightsCount || 0,
        mlUnprocessedRecords: unprocessedCount || 0,
        mlProcessingTime: logData?.processing_time_seconds || 0
      };
    } catch (error) {
      console.error('Error loading ML status:', error);
      return {
        mlAgentStatus: 'error' as const,
        mlLastProcessed: null,
        mlTrendsGenerated: 0,
        mlInsightsGenerated: 0,
        mlUnprocessedRecords: 0,
        mlProcessingTime: 0
      };
    }
  };

  const loadMarketDataStatus = async (): Promise<Partial<PricingHealthMetrics>> => {
    try {
      // Get latest market pricing data
      const { data: marketData, error } = await supabase
        .from('collected_market_prices')
        .select('price_date')
        .order('price_date', { ascending: false })
        .limit(1)
        .single();

      // Get total market data points
      const { count: dataPoints } = await supabase
        .from('collected_market_prices')
        .select('*', { count: 'exact', head: true })
        .gte('price_date', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString());

      const status = marketData && !error
        ? (Date.now() - new Date(marketData.price_date).getTime() < 7 * 24 * 60 * 60 * 1000 ? 'healthy' : 'degraded')
        : 'error';

      return {
        marketDataStatus: status,
        marketDataPoints: dataPoints || 0,
        lastMarketUpdate: marketData ? new Date(marketData.price_date) : null
      };
    } catch (error) {
      console.error('Error loading market data status:', error);
      return {
        marketDataStatus: 'error' as const,
        marketDataPoints: 0,
        lastMarketUpdate: null
      };
    }
  };

  const calculateMarketDataCoverage = async (): Promise<Partial<PricingHealthMetrics>> => {
    try {
      const equipmentTypes = ['bess', 'solar', 'generator', 'ev-charger', 'inverter', 'transformer'];
      const coverage: Record<string, number> = {};

      for (const type of equipmentTypes) {
        try {
          const summary = await getMarketPriceSummary(type as any, 'north-america');
          coverage[type] = summary?.dataPointCount || 0;
        } catch (error) {
          coverage[type] = 0;
        }
      }

      return {
        marketDataCoverage: {
          bess: coverage['bess'] || 0,
          solar: coverage['solar'] || 0,
          generator: coverage['generator'] || 0,
          evCharger: coverage['ev-charger'] || 0,
          inverter: coverage['inverter'] || 0,
          transformer: coverage['transformer'] || 0
        }
      };
    } catch (error) {
      return {
        marketDataCoverage: {
          bess: 0,
          solar: 0,
          generator: 0,
          evCharger: 0,
          inverter: 0,
          transformer: 0
        }
      };
    }
  };

  const loadValidationStatus = async (): Promise<Partial<PricingHealthMetrics>> => {
    try {
      const results = await dailyPricingValidator.validateDailyPricing();
      const critical = results.filter(r => r.severity === 'critical').length;

      setValidationResults(results);

      return {
        validationAlerts: results.length,
        criticalAlerts: critical
      };
    } catch (error) {
      return {
        validationAlerts: 0,
        criticalAlerts: 0
      };
    }
  };

  const checkDatabaseConnection = async (): Promise<Partial<PricingHealthMetrics>> => {
    try {
      const { error } = await supabase
        .from('calculation_constants')
        .select('id')
        .limit(1);

      return {
        databaseConnection: error ? 'error' : 'connected'
      };
    } catch (error) {
      return {
        databaseConnection: 'error' as const
      };
    }
  };

  const loadMLTrends = async (): Promise<any[]> => {
    try {
      const { data, error } = await supabase
        .from('ml_price_trends')
        .select('*')
        .order('updated_at', { ascending: false })
        .limit(10);

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.error('Error loading ML trends:', error);
      return [];
    }
  };

  const calculateQuoteImpactMetrics = async (): Promise<Partial<PricingHealthMetrics>> => {
    // This would ideally track actual quote usage, but for now we'll estimate
    // based on market data availability
    const marketDataAvailable = metrics?.marketDataPoints || 0;
    const totalQuotes = 100; // Placeholder - would come from actual quote tracking

    // Estimate: if market data exists, assume 60% of quotes use it
    const quotesUsingMarket = marketDataAvailable > 0 ? Math.floor(totalQuotes * 0.6) : 0;
    const quotesUsingDefaults = totalQuotes - quotesUsingMarket;

    return {
      quotesUsingMarketData: quotesUsingMarket,
      quotesUsingDefaults: quotesUsingDefaults,
      marketDataUtilizationRate: marketDataAvailable > 0 ? 60 : 0,
      averagePriceDeviation: 0 // Would calculate from actual quote data
    };
  };

  const handleRunMLProcessing = async () => {
    try {
      setRefreshing(true);
      const result = await runMLProcessing();
      console.log('ML Processing Result:', result);
      await loadHealthMetrics();
    } catch (error) {
      console.error('Error running ML processing:', error);
    } finally {
      setRefreshing(false);
    }
  };

  const handleClearCache = async () => {
    try {
      clearAllPricingCaches();
      await loadHealthMetrics();
    } catch (error) {
      console.error('Error clearing cache:', error);
    }
  };

  if (loading && !metrics) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
        <span className="ml-3 text-gray-600">Loading pricing system health...</span>
      </div>
    );
  }

  if (!metrics) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-xl p-6">
        <p className="text-red-700">Unable to load pricing system health metrics.</p>
      </div>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy':
      case 'active':
      case 'connected':
      case 'synced':
      case 'fresh':
        return 'text-emerald-600 bg-emerald-50 border-emerald-200';
      case 'degraded':
      case 'idle':
      case 'stale':
        return 'text-amber-600 bg-amber-50 border-amber-200';
      case 'error':
      case 'disconnected':
      case 'expired':
      case 'outdated':
        return 'text-red-600 bg-red-50 border-red-200';
      default:
        return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'healthy':
      case 'active':
      case 'connected':
      case 'synced':
      case 'fresh':
        return <CheckCircle className="w-5 h-5" />;
      case 'degraded':
      case 'idle':
      case 'stale':
        return <AlertTriangle className="w-5 h-5" />;
      case 'error':
      case 'disconnected':
      case 'expired':
      case 'outdated':
        return <AlertTriangle className="w-5 h-5" />;
      default:
        return <Info className="w-5 h-5" />;
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-500 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-500/25">
            <Activity className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-gray-800">Pricing System Health</h2>
            <p className="text-sm text-gray-500">
              Last updated: {lastRefresh.toLocaleTimeString()}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={async () => {
              await Promise.all([loadHealthMetrics(), loadUtilityRates()]);
            }}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-medium transition-all disabled:opacity-50"
          >
            <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
          <button
            onClick={handleClearCache}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-medium transition-all"
          >
            Clear Cache
          </button>
        </div>
      </div>

      {/* System Status Overview */}
      <div className={`grid grid-cols-1 md:grid-cols-${metrics.marketDataPoints > 0 ? '5' : '4'} gap-4`}>
        {/* Market Data Status - Only show if there's actionable data */}
        {metrics.marketDataPoints > 0 && (
          <div className={`bg-white/90 backdrop-blur-sm p-5 rounded-2xl border-2 ${getStatusColor(metrics.marketDataStatus)} shadow-lg`}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                {getStatusIcon(metrics.marketDataStatus)}
                <span className="font-semibold text-sm">Market Data</span>
              </div>
              {metrics.marketDataStatus === 'healthy' ? (
                <CheckCircle className="w-5 h-5 text-emerald-600" />
              ) : (
                <AlertTriangle className="w-5 h-5 text-amber-600" />
              )}
            </div>
            <div className="text-2xl font-bold mb-1">{metrics.marketDataPoints.toLocaleString()}</div>
            <div className="text-xs opacity-75">Data points (30d)</div>
            {metrics.lastMarketUpdate && (
              <div className="text-xs mt-2 opacity-60">
                Updated: {new Date(metrics.lastMarketUpdate).toLocaleDateString()}
              </div>
            )}
          </div>
        )}

        {/* ML Agent Status */}
        <div className={`bg-white/90 backdrop-blur-sm p-5 rounded-2xl border-2 ${getStatusColor(metrics.mlAgentStatus)} shadow-lg`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              {getStatusIcon(metrics.mlAgentStatus)}
              <span className="font-semibold text-sm">ML Agent</span>
            </div>
            {metrics.mlAgentStatus === 'active' ? (
              <Zap className="w-5 h-5 text-emerald-600" />
            ) : (
              <Clock className="w-5 h-5 text-amber-600" />
            )}
          </div>
          <div className="text-2xl font-bold mb-1">{metrics.mlTrendsGenerated}</div>
          <div className="text-xs opacity-75">Price trends generated</div>
          {metrics.mlUnprocessedRecords > 0 && (
            <div className="text-xs mt-2 text-amber-600 font-medium">
              {metrics.mlUnprocessedRecords} unprocessed
            </div>
          )}
        </div>

        {/* Database Connection */}
        <div className={`bg-white/90 backdrop-blur-sm p-5 rounded-2xl border-2 ${getStatusColor(metrics.databaseConnection)} shadow-lg`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              {metrics.databaseConnection === 'connected' ? (
                <Cloud className="w-5 h-5" />
              ) : (
                <CloudOff className="w-5 h-5" />
              )}
              <span className="font-semibold text-sm">Database</span>
            </div>
            {getStatusIcon(metrics.databaseConnection)}
          </div>
          <div className="text-2xl font-bold mb-1 capitalize">{metrics.databaseConnection}</div>
          <div className="text-xs opacity-75">Connection status</div>
        </div>

        {/* Validation Alerts */}
        <div className={`bg-white/90 backdrop-blur-sm p-5 rounded-2xl border-2 ${metrics.criticalAlerts > 0 ? 'border-red-200 bg-red-50' : 'border-emerald-200 bg-emerald-50'} shadow-lg`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              <span className="font-semibold text-sm">Validation</span>
            </div>
            {metrics.criticalAlerts > 0 ? (
              <AlertTriangle className="w-5 h-5 text-red-600" />
            ) : (
              <CheckCircle className="w-5 h-5 text-emerald-600" />
            )}
          </div>
          <div className="text-2xl font-bold mb-1">{metrics.validationAlerts}</div>
          <div className="text-xs opacity-75">
            {metrics.criticalAlerts > 0 ? (
              <span className="text-red-600 font-medium">{metrics.criticalAlerts} critical</span>
            ) : (
              'All clear'
            )}
          </div>
        </div>

        {/* Vendor Pricing Status */}
        <div className={`bg-white/90 backdrop-blur-sm p-5 rounded-2xl border-2 ${getStatusColor(metrics.vendorPricingStatus)} shadow-lg`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              {getStatusIcon(metrics.vendorPricingStatus)}
              <span className="font-semibold text-sm">Vendor Pricing</span>
            </div>
            {metrics.vendorPricingStatus === 'active' ? (
              <CheckCircle className="w-5 h-5 text-emerald-600" />
            ) : metrics.vendorPricingStatus === 'limited' ? (
              <AlertTriangle className="w-5 h-5 text-amber-600" />
            ) : (
              <Info className="w-5 h-5 text-gray-600" />
            )}
          </div>
          <div className="text-2xl font-bold mb-1">{metrics.approvedVendorProducts}</div>
          <div className="text-xs opacity-75">Approved products</div>
          {metrics.pendingVendorProducts > 0 && (
            <div className="text-xs mt-2 text-amber-600 font-medium">
              {metrics.pendingVendorProducts} pending
            </div>
          )}
        </div>
      </div>

      {/* Market Data Coverage - Only show if there's actionable data */}
      {Object.values(metrics.marketDataCoverage).some(count => count > 0) && (
        <div className="bg-white/90 backdrop-blur-sm p-6 rounded-2xl border border-purple-200 shadow-xl">
          <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-purple-600" />
            Market Data Coverage by Component
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
            {Object.entries(metrics.marketDataCoverage)
              .filter(([_, count]) => count > 0)
              .map(([component, count]) => (
                <div key={component} className="bg-gradient-to-br from-purple-50 to-indigo-50 p-4 rounded-xl border border-purple-200">
                  <div className="text-xs text-gray-600 mb-1 uppercase font-medium">
                    {component === 'evCharger' ? 'EV Charger' : component}
                  </div>
                  <div className="text-2xl font-bold text-purple-700">{count}</div>
                  <div className="text-xs text-gray-500 mt-1">data points</div>
                  <div className="mt-2 h-2 bg-purple-200 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-gradient-to-r from-purple-500 to-indigo-500 transition-all"
                      style={{ width: `${Math.min(100, (count / 10) * 100)}%` }}
                    />
                  </div>
                </div>
              ))}
          </div>
        </div>
      )}

      {/* ML Agent Details */}
      <div className="bg-white/90 backdrop-blur-sm p-6 rounded-2xl border border-purple-200 shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
            <Cpu className="w-5 h-5 text-purple-600" />
            ML Agent Status
          </h3>
          <button
            onClick={handleRunMLProcessing}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-medium transition-all disabled:opacity-50"
          >
            <Zap className="w-4 h-4" />
            Run ML Processing
          </button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-gradient-to-br from-blue-50 to-cyan-50 p-4 rounded-xl border border-blue-200">
            <div className="text-xs text-gray-600 mb-1">Status</div>
            <div className="text-lg font-bold capitalize">{metrics.mlAgentStatus}</div>
            {metrics.mlLastProcessed && (
              <div className="text-xs text-gray-500 mt-1">
                Last: {new Date(metrics.mlLastProcessed).toLocaleDateString()}
              </div>
            )}
          </div>
          <div className="bg-gradient-to-br from-purple-50 to-indigo-50 p-4 rounded-xl border border-purple-200">
            <div className="text-xs text-gray-600 mb-1">Trends Generated</div>
            <div className="text-lg font-bold">{metrics.mlTrendsGenerated}</div>
            <div className="text-xs text-gray-500 mt-1">Price forecasts</div>
          </div>
          <div className="bg-gradient-to-br from-emerald-50 to-teal-50 p-4 rounded-xl border border-emerald-200">
            <div className="text-xs text-gray-600 mb-1">Insights Generated</div>
            <div className="text-lg font-bold">{metrics.mlInsightsGenerated}</div>
            <div className="text-xs text-gray-500 mt-1">Market insights</div>
          </div>
          <div className={`p-4 rounded-xl border ${metrics.mlUnprocessedRecords > 0 ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-200'}`}>
            <div className="text-xs text-gray-600 mb-1">Unprocessed Records</div>
            <div className={`text-lg font-bold ${metrics.mlUnprocessedRecords > 0 ? 'text-amber-700' : 'text-gray-700'}`}>
              {metrics.mlUnprocessedRecords}
            </div>
            <div className="text-xs text-gray-500 mt-1">Pending analysis</div>
          </div>
        </div>

        {/* Recent ML Trends */}
        {mlTrends.length > 0 && (
          <div className="mt-6">
            <h4 className="text-sm font-bold text-gray-700 mb-3">Recent Price Trends</h4>
            <div className="space-y-2">
              {mlTrends.slice(0, 5).map((trend: any, idx: number) => (
                <div key={idx} className="bg-gradient-to-r from-purple-50 to-indigo-50 p-3 rounded-lg border border-purple-200">
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="font-semibold text-sm text-gray-800">
                        {trend.product_type || 'Unknown'}
                      </div>
                      <div className="text-xs text-gray-600">
                        Avg: ${trend.average_price?.toFixed(2) || 'N/A'}
                        {trend.price_change_30d && (
                          <span className={`ml-2 ${trend.price_change_30d > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                            {trend.price_change_30d > 0 ? <ArrowUp className="w-3 h-3 inline" /> : <ArrowDown className="w-3 h-3 inline" />}
                            {Math.abs(trend.price_change_30d).toFixed(1)}% (30d)
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className={`text-xs px-2 py-1 rounded-full ${
                        trend.trend_direction === 'increasing' ? 'bg-red-100 text-red-700' :
                        trend.trend_direction === 'decreasing' ? 'bg-emerald-100 text-emerald-700' :
                        'bg-gray-100 text-gray-700'
                      }`}>
                        {trend.trend_direction || 'stable'}
                      </div>
