      {/* Action Items */}
      <div className="bg-gradient-to-br from-amber-50 to-orange-50 border-2 border-amber-200 rounded-2xl p-6 shadow-xl">
        <h3 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
