                                ${selectedRateData.touRates.superOffPeak.toFixed(3)}/kWh
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    )}

                    <div className="pt-4 border-t border-gray-200">
                      <div className="text-xs text-gray-500">
                        <div className="mb-1">
                          <strong>Effective:</strong> {selectedRateData.effectiveDate}
                        </div>
                        <div>
                          <strong>Source:</strong> {selectedRateData.source}
                        </div>
                      </div>
                    </div>

                    <div className="pt-4">
                      <div className="p-4 bg-purple-50 rounded-lg">
                        <div className="text-sm text-purple-900 mb-2">Selected Rate</div>
                        <div className="text-3xl font-bold text-purple-600">
                          ${getRateValue(selectedRateData).toFixed(3)}
                          <span className="text-lg">/kWh</span>
                        </div>
                        {useTOU && selectedRateData.hasTOU && (
                          <div className="text-xs text-purple-700 mt-1">
                            Peak TOU Rate
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="p-8 text-center text-gray-500">
                  <div className="text-4xl mb-2">⚡</div>
                  <p>Select a utility to view rate details</p>
                </div>
              )}
            </div>
          </div>

          {/* Info Banner */}
          <div className="mt-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
            <div className="flex items-start">
              <span className="text-2xl mr-3">💡</span>
              <div className="flex-1">
                <h4 className="font-semibold text-yellow-900 mb-1">About These Rates</h4>
                <p className="text-sm text-yellow-800">
                  Rates are updated regularly from public utility tariff schedules. Actual rates may vary based on 
                  specific rate schedules, time of use, demand charges, and other factors. Always verify with your 
                  local utility for the most accurate pricing. These rates are for estimation purposes only.
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 flex justify-between items-center">
          <button
            onClick={onClose}
            className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-md"
          >
            Cancel
          </button>
          <button
            onClick={handleApplyRate}
            disabled={!selectedRateData}
            className={`px-6 py-2 rounded-md font-semibold ${
              selectedRateData
                ? 'bg-purple-600 text-white hover:bg-purple-700'
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Apply Rate to Quote
          </button>
        </div>
      </div>
    </div>
  );
};

export default UtilityRatesManager;

/**
 * DOCUMENT UPLOAD ZONE
 * ====================
 * 
 * Drag-and-drop file upload component for Path A workflow.
 * Supports PDF, Excel, and CSV files for AI extraction.
 * 
 * Features:
 * - Drag & drop or click to upload
 * - Multiple file support
 * - File type validation
 * - Upload progress indication
 * - AI extraction status
 * 
 * @component DocumentUploadZone
 */

import React, { useState, useCallback, useRef } from 'react';
import { 
  Upload, FileText, FileSpreadsheet, File, X, 
  CheckCircle, AlertCircle, Loader2, Sparkles,
  FileType, Trash2
} from 'lucide-react';
import { parseDocuments, type ParsedDocument } from '@/services/documentParserService';
import { extractSpecsFromDocuments, type ExtractedSpecsData } from '@/services/openAIExtractionService';

// ============================================
// TYPES
// ============================================

interface DocumentUploadZoneProps {
  onExtractionComplete: (data: ExtractedSpecsData, documents: ParsedDocument[]) => void;
  onError?: (error: string) => void;
  maxFiles?: number;
  maxFileSizeMB?: number;
  className?: string;
}

interface UploadedFile {
  id: string;
  file: File;
  status: 'pending' | 'parsing' | 'parsed' | 'error';
  parsedDoc?: ParsedDocument;
  error?: string;
}

type UploadStatus = 'idle' | 'uploading' | 'parsing' | 'extracting' | 'complete' | 'error';

// ============================================
// CONSTANTS
// ============================================

const ACCEPTED_TYPES = {
  'application/pdf': ['.pdf'],
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
  'application/vnd.ms-excel': ['.xls'],
  'text/csv': ['.csv'],
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
  'application/msword': ['.doc'],
  'image/jpeg': ['.jpg', '.jpeg'],
  'image/png': ['.png'],
};

const ACCEPTED_EXTENSIONS = ['.pdf', '.xlsx', '.xls', '.csv', '.docx', '.doc', '.jpg', '.jpeg', '.png'];

const FILE_TYPE_ICONS: Record<string, React.FC<{ className?: string }>> = {
  pdf: FileText,
  xlsx: FileSpreadsheet,
  xls: FileSpreadsheet,
  csv: FileSpreadsheet,
  docx: FileText,
  doc: FileText,
  jpg: File,
  jpeg: File,
  png: File,
  default: File,
};

// ============================================
// COMPONENT
// ============================================

export function DocumentUploadZone({
  onExtractionComplete,
  onError,
  maxFiles = 5,
  maxFileSizeMB = 10,
  className = '',
}: DocumentUploadZoneProps) {
  // State
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [status, setStatus] = useState<UploadStatus>('idle');
  const [isDragOver, setIsDragOver] = useState(false);
  const [extractionResult, setExtractionResult] = useState<ExtractedSpecsData | null>(null);
  const [errorMessage, setErrorMessage] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // ============================================
  // HANDLERS
  // ============================================

  const validateFile = useCallback((file: File): string | null => {
    // Check file size
    if (file.size > maxFileSizeMB * 1024 * 1024) {
      return `File too large. Maximum size is ${maxFileSizeMB}MB.`;
    }

    // Check file type
    const ext = '.' + file.name.split('.').pop()?.toLowerCase();
    if (!ACCEPTED_EXTENSIONS.includes(ext)) {
      return `Unsupported file type. Accepted: ${ACCEPTED_EXTENSIONS.join(', ')}`;
    }

    return null;
  }, [maxFileSizeMB]);

  const addFiles = useCallback(async (files: FileList | File[]) => {
    const fileArray = Array.from(files);

    // Check max files limit
    if (uploadedFiles.length + fileArray.length > maxFiles) {
      setErrorMessage(`Maximum ${maxFiles} files allowed.`);
      return;
    }

    // Validate and add files
    const newFiles: UploadedFile[] = [];

    for (const file of fileArray) {
      const error = validateFile(file);

      newFiles.push({
        id: `${file.name}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        file,
        status: error ? 'error' : 'pending',
        error: error || undefined,
      });
    }

    setUploadedFiles(prev => [...prev, ...newFiles]);
    setErrorMessage('');

    // Auto-process if all files are valid
    const validFiles = newFiles.filter(f => f.status === 'pending');
    if (validFiles.length > 0) {
      await processFiles([...uploadedFiles, ...newFiles]);
    }
  }, [uploadedFiles, maxFiles, validateFile]);

  const processFiles = useCallback(async (files: UploadedFile[]) => {
    const pendingFiles = files.filter(f => f.status === 'pending');
    if (pendingFiles.length === 0) return;

    setStatus('parsing');

    // Update status to parsing
    setUploadedFiles(prev => 
      prev.map(f => 
        pendingFiles.find(p => p.id === f.id) 
          ? { ...f, status: 'parsing' as const }
          : f
      )
    );

    try {
      // Parse documents
      const parsedDocs = await parseDocuments(pendingFiles.map(f => f.file));

      // Update files with parsed results
      setUploadedFiles(prev => 
        prev.map((f, idx) => {
          const pendingIdx = pendingFiles.findIndex(p => p.id === f.id);
          if (pendingIdx === -1) return f;

          const parsedDoc = parsedDocs[pendingIdx];
          return {
            ...f,
            status: parsedDoc.status === 'failed' ? 'error' : 'parsed',
            parsedDoc,
            error: parsedDoc.errorMessage,
          };
        })
      );

      // Run AI extraction on all successfully parsed docs
      const allParsedDocs = files
        .map((f, idx) => pendingFiles.findIndex(p => p.id === f.id) !== -1 ? parsedDocs[pendingFiles.findIndex(p => p.id === f.id)] : f.parsedDoc)
        .filter((d): d is ParsedDocument => d !== undefined && d.status !== 'failed');

      if (allParsedDocs.length > 0) {
        setStatus('extracting');

        const extracted = await extractSpecsFromDocuments(allParsedDocs);
        setExtractionResult(extracted);

        // Notify parent
        onExtractionComplete(extracted, allParsedDocs);
        setStatus('complete');
      } else {
        setStatus('error');
        setErrorMessage('No documents could be processed successfully.');
        onError?.('No documents could be processed successfully.');
      }

    } catch (error) {
      setStatus('error');
      const message = error instanceof Error ? error.message : 'Processing failed';
      setErrorMessage(message);
      onError?.(message);
    }
  }, [onExtractionComplete, onError]);

  const removeFile = useCallback((id: string) => {
    setUploadedFiles(prev => prev.filter(f => f.id !== id));
    if (uploadedFiles.length <= 1) {
      setExtractionResult(null);
      setStatus('idle');
    }
  }, [uploadedFiles.length]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);

    if (e.dataTransfer.files.length > 0) {
      addFiles(e.dataTransfer.files);
    }
  }, [addFiles]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
  }, []);

  const handleClick = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      addFiles(e.target.files);
      e.target.value = ''; // Reset input
    }
  }, [addFiles]);

  const clearAll = useCallback(() => {
    setUploadedFiles([]);
    setExtractionResult(null);
    setStatus('idle');
    setErrorMessage('');
  }, []);

  // ============================================
  // RENDER HELPERS
  // ============================================

  const getFileIcon = (fileName: string) => {
    const ext = fileName.split('.').pop()?.toLowerCase() || 'default';
    const Icon = FILE_TYPE_ICONS[ext] || FILE_TYPE_ICONS.default;
    return Icon;
  };

  const getStatusIcon = (fileStatus: UploadedFile['status']) => {
    switch (fileStatus) {
      case 'parsing':
        return <Loader2 className="w-4 h-4 text-blue-400 animate-spin" />;
      case 'parsed':
        return <CheckCircle className="w-4 h-4 text-green-400" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-red-400" />;
      default:
        return null;
    }
  };

  // ============================================
  // RENDER
  // ============================================

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Drop Zone */}
      <div
        onClick={handleClick}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        className={`
          relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer
          transition-all duration-200
          ${isDragOver 
            ? 'border-purple-400 bg-purple-500/10' 
            : 'border-gray-600 hover:border-purple-400 hover:bg-purple-500/5'
          }
          ${status === 'extracting' ? 'pointer-events-none' : ''}
        `}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept={ACCEPTED_EXTENSIONS.join(',')}
          onChange={handleFileInput}
          className="hidden"
        />

        {status === 'extracting' ? (
          <div className="space-y-3">
            <div className="flex items-center justify-center gap-2">
              <Sparkles className="w-8 h-8 text-purple-400 animate-pulse" />
              <Loader2 className="w-6 h-6 text-purple-400 animate-spin" />
            </div>
            <p className="text-purple-300 font-medium">AI is analyzing your documents...</p>
            <p className="text-gray-500 text-sm">Extracting power requirements, rates, and facility data</p>
          </div>
        ) : status === 'parsing' ? (
          <div className="space-y-3">
            <Loader2 className="w-10 h-10 text-blue-400 mx-auto animate-spin" />
            <p className="text-blue-300 font-medium">Processing files...</p>
          </div>
        ) : (
          <div className="space-y-3">
            {/* AI-Powered Badge */}
            <div className="flex justify-center mb-2">
              <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-purple-500/20 border border-purple-400/30 rounded-full text-xs text-purple-300 font-medium">
                <Sparkles className="w-3 h-3" />
                AI-Powered Extraction
              </span>
            </div>

            <Upload className={`w-10 h-10 mx-auto ${isDragOver ? 'text-purple-400' : 'text-gray-500'}`} />
            <div>
              <p className="text-gray-300 font-medium">
                {isDragOver ? 'Drop files here' : 'Drag & drop files here'}
              </p>
              <p className="text-gray-500 text-sm">or click to browse</p>
            </div>
            <div className="flex items-center justify-center gap-4 text-xs text-gray-500">
              <span className="flex items-center gap-1">
                <FileText className="w-3 h-3" /> PDF
              </span>
              <span className="flex items-center gap-1">
                <FileSpreadsheet className="w-3 h-3" /> Excel
              </span>
              <span className="flex items-center gap-1">
                <FileType className="w-3 h-3" /> CSV
              </span>
            </div>
            <p className="text-gray-600 text-xs">
              Max {maxFiles} files, {maxFileSizeMB}MB each
            </p>
          </div>
        )}
      </div>

      {/* Error Message */}
      {errorMessage && (
        <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
          <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
          <p className="text-sm text-red-300">{errorMessage}</p>
        </div>
      )}

      {/* Uploaded Files List */}
      {uploadedFiles.length > 0 && (
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <p className="text-sm text-gray-400">{uploadedFiles.length} file(s) uploaded</p>
            <button
              onClick={clearAll}
              className="text-xs text-gray-500 hover:text-red-400 flex items-center gap-1"
            >
              <Trash2 className="w-3 h-3" /> Clear all
            </button>
          </div>

          <div className="space-y-2">
            {uploadedFiles.map(file => {
              const Icon = getFileIcon(file.file.name);

              return (
                <div
                  key={file.id}
                  className={`
                    flex items-center gap-3 p-3 rounded-lg border
                    ${file.status === 'error' 
                      ? 'bg-red-500/10 border-red-500/30' 
                      : 'bg-gray-800/50 border-gray-700'
                    }
                  `}
                >
                  <Icon className={`w-5 h-5 ${file.status === 'error' ? 'text-red-400' : 'text-gray-400'}`} />

                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-gray-300 truncate">{file.file.name}</p>
                    <p className="text-xs text-gray-500">
                      {(file.file.size / 1024).toFixed(1)} KB
                      {file.parsedDoc?.metadata.documentType && (
                        <span className="ml-2 text-purple-400">
                          • {file.parsedDoc.metadata.documentType.replace('-', ' ')}
                        </span>
                      )}
                    </p>
                    {file.error && (
                      <p className="text-xs text-red-400 mt-1">{file.error}</p>
                    )}
                  </div>

                  {getStatusIcon(file.status)}

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      removeFile(file.id);
                    }}
                    className="p-1 hover:bg-gray-700 rounded"
                  >
                    <X className="w-4 h-4 text-gray-500 hover:text-red-400" />
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Extraction Results Summary */}
      {extractionResult && status === 'complete' && (
        <div className="p-4 bg-green-500/10 border border-green-500/30 rounded-lg">
          <div className="flex items-center gap-2 mb-3">
            <CheckCircle className="w-5 h-5 text-green-400" />
            <p className="text-green-300 font-medium">Data Extracted Successfully</p>
            <span className="ml-auto text-xs text-gray-500">
              {extractionResult.confidence}% confidence
            </span>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
            {extractionResult.powerRequirements?.peakDemandKW && (
              <div className="bg-gray-800/50 rounded-lg p-2">
                <p className="text-xs text-gray-500">Peak Demand</p>
                <p className="text-gray-200 font-medium">
                  {extractionResult.powerRequirements.peakDemandKW.toLocaleString()} kW
                </p>
              </div>
            )}
            {extractionResult.powerRequirements?.monthlyKWh && (
              <div className="bg-gray-800/50 rounded-lg p-2">
                <p className="text-xs text-gray-500">Monthly Usage</p>
                <p className="text-gray-200 font-medium">
                  {extractionResult.powerRequirements.monthlyKWh.toLocaleString()} kWh
                </p>
              </div>
            )}
            {extractionResult.utilityInfo?.electricityRate && (
              <div className="bg-gray-800/50 rounded-lg p-2">
                <p className="text-xs text-gray-500">Electricity Rate</p>
                <p className="text-gray-200 font-medium">
                  ${extractionResult.utilityInfo.electricityRate.toFixed(4)}/kWh
                </p>
              </div>
            )}
            {extractionResult.location?.state && (
              <div className="bg-gray-800/50 rounded-lg p-2">
                <p className="text-xs text-gray-500">Location</p>
                <p className="text-gray-200 font-medium">
                  {extractionResult.location.state}
                </p>
              </div>
            )}
          </div>

          {extractionResult.rawInsights && (
            <p className="text-xs text-gray-500 mt-3 italic">
              {extractionResult.rawInsights}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

export default DocumentUploadZone;

/**
 * SPEC UPLOAD MODAL
 * =================
 * 
 * Professional document upload interface for Path A:
 * Upload specs → Extract data → Review → Generate Quote
 * 
 * Features:
 * - Drag & drop file upload
 * - PDF, Excel, CSV, Text support
 * - AI-powered spec extraction
 * - Editable extracted values
 * - Confidence indicators
 * - Direct flow to quote generation
 */

import React, { useState, useCallback, useRef } from 'react';
import { X, Upload, FileText, FileSpreadsheet, File, AlertTriangle, Loader2, Sparkles, ArrowRight, Zap, MapPin, Battery, Sun, Building2, RefreshCw } from 'lucide-react';
import { parseDocument, type ParsedDocument } from '@/services/documentParsingService';
import { extractSpecsFromText, specsToQuoteInput, type ExtractedSpecs, type ExtractionResult } from '@/services/specExtractionService';

interface SpecUploadModalProps {
  onClose: () => void;
  onExtracted: (specs: ReturnType<typeof specsToQuoteInput>) => void;
}

type UploadState = 'idle' | 'uploading' | 'parsing' | 'extracting' | 'review' | 'error';

const SpecUploadModal: React.FC<SpecUploadModalProps> = ({ onClose, onExtracted }) => {
  const [state, setState] = useState<UploadState>('idle');
  const [dragActive, setDragActive] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [parsedDoc, setParsedDoc] = useState<ParsedDocument | null>(null);
  const [extraction, setExtraction] = useState<ExtractionResult | null>(null);
  const [editedSpecs, setEditedSpecs] = useState<ExtractedSpecs | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const processFile = async (uploadedFile: File) => {
    setFile(uploadedFile);
    setError(null);

    try {
      // Step 1: Parse document
      setState('parsing');
      const parsed = await parseDocument(uploadedFile);
      setParsedDoc(parsed);

      if (parsed.error) {
        throw new Error(parsed.error);
      }

      if (!parsed.textContent || parsed.textContent.trim().length < 10) {
        throw new Error('No readable text found in document');
      }

      // Step 2: Extract specs
      setState('extracting');
      const result = await extractSpecsFromText(parsed.textContent);
      setExtraction(result);
      setEditedSpecs(result.specs);

      // Step 3: Move to review
      setState('review');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to process document');
      setState('error');
    }
  };

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFile(e.target.files[0]);
    }
  };

  const handleGenerateQuote = () => {
    if (editedSpecs) {
      const quoteInput = specsToQuoteInput(editedSpecs);
      onExtracted(quoteInput);
      onClose();
    }
  };

  const handleReset = () => {
    setState('idle');
    setFile(null);
    setParsedDoc(null);
    setExtraction(null);
    setEditedSpecs(null);
    setError(null);
  };

  const updateSpec = (field: keyof ExtractedSpecs, value: any) => {
    if (editedSpecs) {
      setEditedSpecs({ ...editedSpecs, [field]: value });
    }
  };

  const getFileIcon = (fileType: string) => {
    switch (fileType) {
      case 'pdf':
        return <FileText className="w-8 h-8 text-red-500" />;
      case 'excel':
        return <FileSpreadsheet className="w-8 h-8 text-green-500" />;
      case 'csv':
        return <FileSpreadsheet className="w-8 h-8 text-blue-500" />;
      default:
        return <File className="w-8 h-8 text-gray-500" />;
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 80) return 'text-green-600 bg-green-100';
    if (confidence >= 50) return 'text-yellow-600 bg-yellow-100';
    return 'text-red-600 bg-red-100';
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="bg-gradient-to-r from-purple-600 via-blue-600 to-cyan-600 text-white p-6">
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-2xl font-bold flex items-center gap-2">
                <Upload className="w-6 h-6" />
                Upload Project Specs
              </h2>
              <p className="text-purple-100 mt-1">
                Upload your RFP, spec sheet, or requirements document
              </p>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-white/20 rounded-lg transition-colors"
            >
              <X className="w-6 h-6" />
            </button>
          </div>

          {/* Progress Steps */}
          <div className="flex items-center gap-2 mt-4 text-sm">
            <div className={`flex items-center gap-1 px-3 py-1 rounded-full ${
              state === 'idle' ? 'bg-white/30' : 'bg-white/10'
            }`}>
