    handleLayoutPreference,
    handleSaveLayoutPreference,
    handleProfileComplete,
    handleContinueToEnhancedProfile,
    handleEnhancedProfileClose,
    handleSaveProject,
    handleUploadProject,
    handleCreateWithWizard,
    handleSaveToPortfolio,
    handleLoadProject,
    handleUploadFromComputer,
    handleUploadFromPortfolio,
    handlePortfolio,
    handleUserProfile,
    handleResetToDefaults,
    handleExportCalculations,
    handleApplyTemplate,
    handleApplyUseCaseTemplate,
    handleExportWord,

    // Utility functions
    convertCurrency,
    loadProjectData,
    loadProjectFromStorage,
  };

  return { state, actions, exchangeRates };
}

/**
 * useSmartWizard Hook
 * ===================
 * Clean, fully-typed wizard state management
 * Built from scratch 2025-11-24
 *
 * PRINCIPLES:
 * - Single source of truth
 * - All actions defined here
 * - No missing functions
 * - Type-safe by default
 */

import { useState, useCallback, useMemo, useEffect } from "react";
import type {
  SmartWizardState,
  WizardActions,
  UseSmartWizardReturn,
  QuoteConfiguration,
  BessSizing,
  UseCaseAnswers,
  EVConfiguration,
} from "@/types/wizard.types";

// Import services
import { calculateDatabaseBaseline } from "@/services/baselineService";
import { buildQuote } from "@/application/workflows/buildQuote";
import { useCaseService } from "@/services/useCaseService";
import { calculatePowerGap as calculateGap } from "@/services/powerGapAnalysis";

// ============================================================================
// INITIAL STATE
// ============================================================================

const INITIAL_CONFIG: QuoteConfiguration = {
  useCaseSlug: null,
  useCaseAnswers: {},
  sizing: {
    storageSizeMW: 0.1,
    durationHours: 4,
    solarMW: 0,
    solarMWp: 0,
    windMW: 0,
    generatorMW: 0,
  },
  location: "California",
  electricityRate: 0.15,
  wantsSolar: false,
  solarSpaceAcres: 0,
  wantsEV: false,
  evConfig: {
    enabled: false,
    chargers: 0,
    kwPerCharger: 50,
    totalMW: 0,
  },
  gridConnection: "reliable",
};

const INITIAL_STATE: SmartWizardState = {
  config: INITIAL_CONFIG,
  ui: {
    currentStep: -1,
    showIntro: true,
    showCompletePage: false,
    isInitialized: false,
    isLoading: false,
    error: null,
  },
  currentQuote: null,
  powerGapAnalysis: null,
  availableUseCases: [],
  useCaseDetails: null,
};

// ============================================================================
// HOOK IMPLEMENTATION
// ============================================================================

export function useSmartWizard(): UseSmartWizardReturn {
  const [state, setState] = useState<SmartWizardState>(INITIAL_STATE);

  // =========================================================================
  // AUTOMATIC BASELINE CALCULATION (THE MAGIC FROM V2!)
  // =========================================================================
  // When user answers questions, automatically calculate baseline
  // This is what made V2 work smoothly - it's REACTIVE, not manual
  useEffect(() => {
    const autoCalculateBaseline = async () => {
      const { useCaseSlug, useCaseAnswers } = state.config;
      const { useCaseDetails } = state;

      // Only calculate if we have a use case selected AND questions answered
      if (!useCaseSlug || !useCaseDetails) return;

      // Check if we have any answers (user has started answering questions)
      const hasAnswers = Object.keys(useCaseAnswers).length > 0;
      if (!hasAnswers) return;

      // Check if all required questions are answered
      const requiredQuestions =
        useCaseDetails.custom_questions?.filter((q: any) => q.required) || [];
      const allRequiredAnswered = requiredQuestions.every((q: any) => {
        const answer = useCaseAnswers[q.question_key];
        return answer !== undefined && answer !== null && answer !== "";
      });

      if (!allRequiredAnswered) return;

      // All conditions met - calculate baseline automatically!
      try {
        const baseline = await calculateDatabaseBaseline(
          useCaseSlug,
          1, // scale
          useCaseAnswers
        );

        setState((prev) => ({
          ...prev,
          config: {
            ...prev.config,
            sizing: {
              ...prev.config.sizing,
              storageSizeMW: baseline.powerMW,
              durationHours: baseline.durationHrs,
              solarMW: baseline.solarMW || 0,
              solarMWp: baseline.solarMW || 0,
            },
          },
        }));
      } catch (error) {
        console.error("[useSmartWizard] Auto-calculate baseline failed:", error);
      }
    };

    autoCalculateBaseline();
  }, [state.config.useCaseSlug, state.config.useCaseAnswers, state.useCaseDetails]);

  // =========================================================================
  // NAVIGATION ACTIONS
  // =========================================================================

  const goToStep = useCallback((step: number) => {
    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, currentStep: step },
    }));
  }, []);

  const nextStep = useCallback(() => {
    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, currentStep: prev.ui.currentStep + 1 },
    }));
  }, []);

  const previousStep = useCallback(() => {
    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, currentStep: Math.max(-1, prev.ui.currentStep - 1) },
    }));
  }, []);

  const skipIntro = useCallback(() => {
    setState((prev) => ({
      ...prev,
      ui: {
        ...prev.ui,
        showIntro: false,
        currentStep: 0,
      },
    }));
  }, []);

  // =========================================================================
  // USE CASE ACTIONS
  // =========================================================================

  const selectUseCase = useCallback(async (slug: string) => {
    if (import.meta.env.DEV) {
      console.log("[useSmartWizard] 🎯 Selecting use case:", slug);
    }
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        useCaseSlug: slug,
      },
      ui: { ...prev.ui, isLoading: true },
    }));

    try {
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] 📡 Fetching use case details from database...");
      }
      const details = await useCaseService.getUseCaseBySlug(slug);
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] ✅ Use case details loaded:", details?.name);
      }

      if (!details) {
        throw new Error(`Use case "${slug}" not found in database`);
      }

      setState((prev) => ({
        ...prev,
        useCaseDetails: details,
        ui: { ...prev.ui, isLoading: false },
      }));
      console.log("[useSmartWizard] ✅ Use case details set in state:", {
        slug: details.slug,
        name: details.name,
        hasQuestions: !!details.custom_questions,
      });

      return true; // Success
    } catch (error) {
      console.error("[useSmartWizard] ❌ Failed to load use case:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error occurred";
      setState((prev) => ({
        ...prev,
        ui: {
          ...prev.ui,
          isLoading: false,
          error: `Failed to load use case details: ${errorMessage}`,
        },
      }));
      return false; // Failure
    }
  }, []);

  const updateAnswers = useCallback((answers: Partial<UseCaseAnswers>) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        useCaseAnswers: {
          ...prev.config.useCaseAnswers,
          ...answers,
        },
      },
    }));
  }, []);

  const calculateBaseline = useCallback(async () => {
    if (!state.config.useCaseSlug || !state.useCaseDetails) {
      console.warn("[useSmartWizard] Cannot calculate baseline: missing use case");
      return;
    }

    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, isLoading: true },
    }));

    try {
      const baseline = await calculateDatabaseBaseline(
        state.config.useCaseSlug,
        1, // scale
        state.config.useCaseAnswers
      );

      setState((prev) => ({
        ...prev,
        config: {
          ...prev.config,
          sizing: {
            ...prev.config.sizing,
            storageSizeMW: baseline.powerMW,
            durationHours: baseline.durationHrs,
            solarMW: baseline.solarMW,
          },
        },
        ui: { ...prev.ui, isLoading: false },
      }));
    } catch (error) {
      console.error("[useSmartWizard] Baseline calculation failed:", error);
      setState((prev) => ({
        ...prev,
        ui: {
          ...prev.ui,
          isLoading: false,
          error: "Failed to calculate baseline",
        },
      }));
    }
  }, [state.config.useCaseSlug, state.useCaseDetails, state.config.useCaseAnswers]);

  const calculatePowerGap = useCallback(async () => {
    if (!state.config.useCaseSlug) {
      console.warn("[useSmartWizard] Cannot calculate power gap: no use case selected");
      return;
    }

    if (import.meta.env.DEV) {
      console.log("[useSmartWizard] 🔍 Calculating power gap analysis...");
    }
    console.log("[useSmartWizard] Current state:", {
      useCaseSlug: state.config.useCaseSlug,
      answers: state.config.useCaseAnswers,
      useCaseDetails: state.useCaseDetails,
    });

    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, isLoading: true },
    }));

    try {
      // First calculate baseline if not already done
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] Calculating baseline first...");
      }
      const baseline = await calculateDatabaseBaseline(
        state.config.useCaseSlug,
        1,
        state.config.useCaseAnswers
      );

      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] Baseline result:", baseline);
      }

      // Now calculate the power gap
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] Now calculating power gap...");
      }
      const gapAnalysis = await calculateGap(
        state.config.useCaseSlug,
        state.config.useCaseAnswers,
        baseline
      );

      console.log("[useSmartWizard] ✅ Power gap analysis complete:", {
        recommendation: gapAnalysis.recommendation,
        powerGap: gapAnalysis.powerGapKW,
        confidence: gapAnalysis.confidenceLevel,
      });

      setState((prev) => ({
        ...prev,
        powerGapAnalysis: gapAnalysis,
        config: {
          ...prev.config,
          sizing: {
            ...prev.config.sizing,
            storageSizeMW: baseline.powerMW,
            durationHours: baseline.durationHrs,
            solarMW: baseline.solarMW,
          },
        },
        ui: { ...prev.ui, isLoading: false },
      }));
    } catch (error) {
      console.error("[useSmartWizard] ❌ Power gap calculation failed:", error);
      console.error("[useSmartWizard] Error details:", {
        message: error instanceof Error ? error.message : "Unknown error",
        stack: error instanceof Error ? error.stack : undefined,
      });
      setState((prev) => ({
        ...prev,
        ui: {
          ...prev.ui,
          isLoading: false,
          error: `Failed to calculate power gap analysis: ${error instanceof Error ? error.message : "Unknown error"}`,
        },
      }));
      // Re-throw so the wizard doesn't proceed
      throw error;
    }
  }, [state.config.useCaseSlug, state.config.useCaseAnswers]);

  // =========================================================================
  // SIZING ACTIONS
  // =========================================================================

  const updateSizing = useCallback((updates: Partial<BessSizing>) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        sizing: {
          ...prev.config.sizing,
          ...updates,
        },
      },
    }));
  }, []);

  // =========================================================================
  // LOCATION ACTIONS
  // =========================================================================

  const updateLocation = useCallback((location: string) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        location,
      },
    }));
  }, []);

  const updateElectricityRate = useCallback((rate: number) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        electricityRate: rate,
      },
    }));
  }, []);

  // =========================================================================
  // RENEWABLES ACTIONS
  // =========================================================================

  const toggleSolar = useCallback((enabled: boolean) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        wantsSolar: enabled,
      },
    }));
  }, []);

  const updateSolarSpaceAcres = useCallback((acres: number) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        solarSpaceAcres: acres,
      },
    }));
  }, []);

  const toggleEV = useCallback((enabled: boolean) => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        wantsEV: enabled,
        evConfig: {
          ...prev.config.evConfig,
          enabled,
        },
      },
    }));
  }, []);

  const updateEVConfig = useCallback((updates: Partial<EVConfiguration>) => {
    setState((prev) => {
      const newConfig = { ...prev.config.evConfig, ...updates };
      const totalMW = (newConfig.chargers * newConfig.kwPerCharger) / 1000;

      return {
        ...prev,
        config: {
          ...prev.config,
          evConfig: {
            ...newConfig,
            totalMW,
          },
        },
      };
    });
  }, []);

  // =========================================================================
  // GRID ACTIONS
  // =========================================================================

  const updateGridConnection = useCallback((connection: "reliable" | "unreliable" | "none") => {
    setState((prev) => ({
      ...prev,
      config: {
        ...prev.config,
        gridConnection: connection,
      },
    }));
  }, []);

  // =========================================================================
  // QUOTE ACTIONS
  // =========================================================================

  const buildCurrentQuote = useCallback(async () => {
    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, isLoading: true },
    }));

    try {
      const quote = await buildQuote({
        useCaseSlug: state.config.useCaseSlug!,
        answers: state.config.useCaseAnswers as Record<string, string | number | boolean>,
        location: { state: state.config.location },
        electricityRate: state.config.electricityRate,
        storageSizeMW: state.config.sizing.storageSizeMW,
        durationHours: state.config.sizing.durationHours,
        solarMW: state.config.sizing.solarMW,
        windMW: state.config.sizing.windMW,
        generatorMW: state.config.sizing.generatorMW,
      });

      setState((prev) => ({
        ...prev,
        currentQuote: quote,
        ui: { ...prev.ui, isLoading: false },
      }));
    } catch (error) {
      console.error("[useSmartWizard] Quote building failed:", error);
      setState((prev) => ({
        ...prev,
        ui: {
          ...prev.ui,
          isLoading: false,
          error: "Failed to build quote",
        },
      }));
      throw error;
    }
  }, [state.config]);

  const reset = useCallback(() => {
    if (import.meta.env.DEV) {
      console.log("[useSmartWizard] 🔄 Resetting wizard to initial state");
    }
    setState(INITIAL_STATE);
  }, []);

  // =========================================================================
  // LIFECYCLE ACTIONS
  // =========================================================================

  const initialize = useCallback(async () => {
    if (import.meta.env.DEV) {
      console.log("[useSmartWizard] 🚀 Starting initialization...");
    }
    setState((prev) => ({
      ...prev,
      ui: { ...prev.ui, isLoading: true },
    }));

    try {
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] 📡 Fetching use cases...");
      }
      const useCases = await useCaseService.getAllUseCases();
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] ✅ Received use cases:", useCases.length);
      }

      if (useCases.length === 0) {
        throw new Error("No use cases available. Please check database connection.");
      }

      setState((prev) => ({
        ...prev,
        availableUseCases: useCases,
        ui: {
          ...prev.ui,
          isInitialized: true,
          isLoading: false,
        },
      }));
      if (import.meta.env.DEV) {
        console.log("[useSmartWizard] ✅ Initialization complete");
      }
    } catch (error) {
      console.error("[useSmartWizard] ❌ Initialization failed:", error);
      setState((prev) => ({
        ...prev,
        ui: {
          ...prev.ui,
          isLoading: false,
          error: "Failed to initialize wizard",
        },
      }));
    }
  }, []);

  // =========================================================================
  // COMPUTED VALUES
  // =========================================================================

  const computed = useMemo(
    () => ({
      canGoNext: state.ui.currentStep < 5 && !state.ui.isLoading,
      canGoPrevious: state.ui.currentStep > -1,
      isStepValid: true, // Future: Add validation logic
      totalSteps: 6,
    }),
    [state.ui.currentStep, state.ui.isLoading]
  );

  // =========================================================================
  // RETURN HOOK API
  // =========================================================================

  const actions: WizardActions = {
    goToStep,
    nextStep,
    previousStep,
    skipIntro,
    selectUseCase,
    updateAnswers,
    calculateBaseline,
    calculatePowerGap,
    updateSizing,
    updateLocation,
    updateElectricityRate,
    toggleSolar,
    updateSolarSpaceAcres,
    toggleEV,
    updateEVConfig,
    updateGridConnection,
    buildQuote: buildCurrentQuote,
    reset,
    initialize,
  };

  return {
    state,
    actions,
    computed,
  };
}

import { useState } from "react";

/**
 * Solar space configuration interface
 */
export interface SolarSpaceConfig {
  hasRoofSpace: boolean;
  roofAreaSqFt: number;
  hasParkingLot: boolean;
  parkingAreaSqFt: number;
  hasOpenLand: boolean;
  openLandAcres: number;
  autoCalculated: boolean;
}

/**
 * Wind configuration interface
 */
export interface WindConfig {
  turbineModel: "small" | "medium" | "large" | "xl";
  turbineCount: number;
  avgWindSpeed: number;
  hubHeight: number;
  manualMW: number;
}

/**
 * Generator configuration interface
 */
export interface GeneratorConfig {
  fuelType: "diesel" | "natural-gas" | "propane" | "biodiesel";
  runtimeHours: number;
  loadFactor: number;
  manualMW: number;
}

/**
 * EV charger configuration interface
 */
export interface EVChargerConfig {
  hasChargers: boolean;
  level2Count: number;
  dcFastCount: number;
}

/**
 * AI use case recommendation interface
 */
export interface AIUseCaseRecommendation {
  message: string;
  savings: string;
  roi: string;
  configuration: string;
}

/**
 * AI baseline data interface
 */
export interface AIBaselineData {
  suggestedStorageMW: number;
  suggestedDurationHours: number;
  estimatedAnnualSavings: number;
  paybackYears: number;
  confidence: number;
}

/**
 * Custom hook for managing all wizard form state
 *
 * Organizes state by logical sections:
 * - Templates & Industry
 * - Use Case Data
 * - System Configuration
 * - Renewables & Power Generation
 * - Location & Pricing
 * - Advanced Analytics
 * - AI Suggestions
 *
 * @returns Form state and setter functions
 */
export function useWizardFormState() {
  // ============================================
  // SECTION 1: Templates & Industry
  // ============================================
  const [selectedTemplate, setSelectedTemplate] = useState<string>("");
  const [useTemplate, setUseTemplate] = useState(true);

  // ============================================
  // SECTION 2: Use Case Data (Step 1 responses)
  // ============================================
  const [useCaseData, setUseCaseData] = useState<{ [key: string]: any }>({});
  const [aiUseCaseRecommendation, setAiUseCaseRecommendation] =
    useState<AIUseCaseRecommendation | null>(null);

  // ============================================
  // SECTION 3: System Configuration (BESS sizing)
  // ============================================
  const [storageSizeMW, setStorageSizeMW] = useState(2);
  const [durationHours, setDurationHours] = useState(4);

  // ============================================
  // SECTION 4: Renewables & Power Generation
  // ============================================
  const [includeRenewables, setIncludeRenewables] = useState(false);
  const [solarMW, setSolarMW] = useState(0);
  const [windMW, setWindMW] = useState(0);
  const [generatorMW, setGeneratorMW] = useState(0);

  // Solar space configuration (with intelligent auto-calculation)
  const [solarSpaceConfig, setSolarSpaceConfig] = useState<SolarSpaceConfig>({
    hasRoofSpace: false,
    roofAreaSqFt: 0,
    hasParkingLot: false,
    parkingAreaSqFt: 0,
    hasOpenLand: false,
    openLandAcres: 0,
    autoCalculated: false,
  });

  // EV charger configuration
  const [evChargerConfig, setEVChargerConfig] = useState<EVChargerConfig>({
    hasChargers: false,
    level2Count: 0,
    dcFastCount: 0,
  });

  // Wind configuration
  const [windConfig, setWindConfig] = useState<WindConfig>({
    turbineModel: "small",
    turbineCount: 1,
    avgWindSpeed: 12,
    hubHeight: 80,
    manualMW: 0,
  });

  // Generator configuration
  const [generatorConfig, setGeneratorConfig] = useState<GeneratorConfig>({
    fuelType: "natural-gas",
    runtimeHours: 8760,
    loadFactor: 0.75,
    manualMW: 0,
  });

  // ============================================
  // SECTION 5: Location & Pricing
  // ============================================
  const [location, setLocation] = useState("");
  const [electricityRate, setElectricityRate] = useState(0.15);
  const [knowsRate, setKnowsRate] = useState(false);

  // Installation, shipping, financing options
  const [selectedInstallation, setSelectedInstallation] = useState("epc");
  const [selectedShipping, setSelectedShipping] = useState("best-value");
  const [selectedFinancing, setSelectedFinancing] = useState("cash");

  // Cost breakdown
  const [costs, setCosts] = useState({
    equipment: 0,
    installation: 0,
    shipping: 0,
    softCosts: 0,
    total: 0,
  });

  // Equipment breakdown (batteries, inverters, containers, etc.)
  const [equipmentBreakdown, setEquipmentBreakdown] = useState<any>(null);

  // ============================================
  // SECTION 6: Advanced Analytics (BESS ML/Optimization)
  // ============================================
  const [showAdvancedAnalytics, setShowAdvancedAnalytics] = useState(false);
  const [loadPatternAnalysis, setLoadPatternAnalysis] = useState<any>(null);
  const [optimizationResults, setOptimizationResults] = useState<any>(null);
  const [controlStrategy, setControlStrategy] = useState<any>(null);
  const [forecastData, setForecastData] = useState<any>(null);
  const [batteryModelData, setBatteryModelData] = useState<any>(null);
  const [mpcStrategy, setMpcStrategy] = useState<any>(null);
  const [analyticsConfidence, setAnalyticsConfidence] = useState(0);

  // ============================================
  // SECTION 7: AI Suggestions & Baseline
  // ============================================
  const [aiSuggestions, setAiSuggestions] = useState<
    Array<{
      type: "optimization" | "cost-saving" | "performance" | "warning";
      title: string;
      description: string;
      currentValue: string;
      suggestedValue: string;
      impact: string;
      savings?: string;
      action: () => void;
    }>
  >([]);

  const [aiBaseline, setAiBaseline] = useState<AIBaselineData | null>(null);

  // ============================================
  // HELPER FUNCTIONS
  // ============================================

  /**
   * Reset all form state to defaults
   */
  const resetFormState = () => {
    setSelectedTemplate("");
    setUseTemplate(true);
    setUseCaseData({});
    setAiUseCaseRecommendation(null);
    setStorageSizeMW(2);
    setDurationHours(4);
    setIncludeRenewables(false);
    setSolarMW(0);
    setWindMW(0);
    setGeneratorMW(0);
    setSolarSpaceConfig({
      hasRoofSpace: false,
      roofAreaSqFt: 0,
      hasParkingLot: false,
      parkingAreaSqFt: 0,
      hasOpenLand: false,
      openLandAcres: 0,
      autoCalculated: false,
    });
    setEVChargerConfig({
      hasChargers: false,
      level2Count: 0,
      dcFastCount: 0,
    });
    setWindConfig({
      turbineModel: "small",
      turbineCount: 1,
      avgWindSpeed: 12,
      hubHeight: 80,
      manualMW: 0,
    });
    setGeneratorConfig({
      fuelType: "natural-gas",
      runtimeHours: 8760,
      loadFactor: 0.75,
      manualMW: 0,
    });
    setLocation("");
    setElectricityRate(0.15);
    setKnowsRate(false);
    setSelectedInstallation("epc");
    setSelectedShipping("best-value");
    setSelectedFinancing("cash");
    setCosts({
      equipment: 0,
      installation: 0,
      shipping: 0,
      softCosts: 0,
      total: 0,
    });
    setEquipmentBreakdown(null);
    setShowAdvancedAnalytics(false);
    setLoadPatternAnalysis(null);
    setOptimizationResults(null);
    setControlStrategy(null);
    setForecastData(null);
    setBatteryModelData(null);
    setMpcStrategy(null);
    setAnalyticsConfidence(0);
    setAiSuggestions([]);
    setAiBaseline(null);
  };

  /**
   * Get total renewable capacity in MW
   */
  const getTotalRenewableCapacity = (): number => {
    return solarMW + windMW + generatorMW;
  };

  /**
   * Get total system capacity (BESS + renewables) in MW
   */
  const getTotalSystemCapacity = (): number => {
    return storageSizeMW + getTotalRenewableCapacity();
  };

  /**
   * Check if any renewables are configured
   */
  const hasRenewables = (): boolean => {
    return includeRenewables && getTotalRenewableCapacity() > 0;
  };

  /**
   * Get system configuration summary object
   */
  const getConfigurationSummary = () => {
    return {
      // Industry & Use Case
      industry: selectedTemplate,
      useTemplate,
      useCaseAnswers: useCaseData,

      // BESS Configuration
      storageSizeMW,
      durationHours,
      storageCapacityMWh: storageSizeMW * durationHours,

      // Renewables
      includeRenewables,
      solarMW,
      windMW,
      generatorMW,
      totalRenewableMW: getTotalRenewableCapacity(),

      // Location & Economics
      location,
      electricityRate,

      // Options
      installation: selectedInstallation,
      shipping: selectedShipping,
      financing: selectedFinancing,

      // Costs
      costs,
      equipmentBreakdown,

      // Total System
      totalSystemMW: getTotalSystemCapacity(),
      hasRenewables: hasRenewables(),
    };
  };

  return {
    // Templates & Industry
    selectedTemplate,
    setSelectedTemplate,
    useTemplate,
    setUseTemplate,

    // Use Case Data
    useCaseData,
    setUseCaseData,
    aiUseCaseRecommendation,
    setAiUseCaseRecommendation,

    // System Configuration
    storageSizeMW,
    setStorageSizeMW,
    durationHours,
    setDurationHours,

    // Renewables & Power Generation
    includeRenewables,
    setIncludeRenewables,
    solarMW,
    setSolarMW,
    windMW,
    setWindMW,
    generatorMW,
    setGeneratorMW,
    solarSpaceConfig,
    setSolarSpaceConfig,
    evChargerConfig,
    setEVChargerConfig,
    windConfig,
    setWindConfig,
    generatorConfig,
    setGeneratorConfig,

    // Location & Pricing
    location,
    setLocation,
    electricityRate,
    setElectricityRate,
    knowsRate,
    setKnowsRate,
    selectedInstallation,
    setSelectedInstallation,
    selectedShipping,
    setSelectedShipping,
    selectedFinancing,
    setSelectedFinancing,
    costs,
    setCosts,
    equipmentBreakdown,
    setEquipmentBreakdown,

    // Advanced Analytics
    showAdvancedAnalytics,
    setShowAdvancedAnalytics,
    loadPatternAnalysis,
    setLoadPatternAnalysis,
    optimizationResults,
    setOptimizationResults,
    controlStrategy,
    setControlStrategy,
    forecastData,
    setForecastData,
    batteryModelData,
    setBatteryModelData,
    mpcStrategy,
    setMpcStrategy,
    analyticsConfidence,
    setAnalyticsConfidence,

    // AI Suggestions
    aiSuggestions,
    setAiSuggestions,
    aiBaseline,
    setAiBaseline,

    // Helper functions
    resetFormState,
    getTotalRenewableCapacity,
    getTotalSystemCapacity,
    hasRenewables,
    getConfigurationSummary,
  };
}

export type WizardFormState = ReturnType<typeof useWizardFormState>;

/**
 * USE WIZARD STATE HOOK - CENTRALIZED STATE MANAGEMENT
 *
 * ⚠️ CRITICAL: This hook manages wizard state and delegates calculations to SSOT.
 *
 * ARCHITECTURE (Option A - Dec 8, 2025):
 * - This hook manages STATE only
 * - Building load calculations DELEGATE to useCasePowerCalculations.ts (SSOT)
 * - EV charger calculations stay here (they're additive, not duplicated)
 * - No duplicate formulas - single source of truth
 *
 * Features:
 * - Centralized state with typed updates
 * - Auto-calculation via SSOT delegation
 * - EV charger load calculations (additive)
 * - Recommended backup hours based on grid reliability and industry
 *
 * Usage:
 * const { wizardState, updateSection, updateEVChargers, resetState } = useWizardState();
 */

import { useState, useCallback, useEffect } from "react";
import type { WizardState } from "@/types/wizardState";
import { INITIAL_WIZARD_STATE } from "@/types/wizardState";
import { calculateUseCasePower } from "@/services/useCasePowerCalculations";
import { QuoteEngine } from "@/core/calculations/QuoteEngine";
import { BESS_POWER_RATIOS } from "@/components/wizard/v6/constants";

// ============================================
// CUSTOM HOOK
// ============================================
export function useWizardState() {
  const [wizardState, setWizardState] = useState<WizardState>(INITIAL_WIZARD_STATE);

  // ────────────────────────────────────────────
  // UPDATE FUNCTIONS
  // ────────────────────────────────────────────

  /**
   * Update a specific section of the wizard state
   */
  const updateSection = useCallback(
    <K extends keyof WizardState>(section: K, updates: Partial<WizardState[K]>) => {
      setWizardState((prev) => ({
        ...prev,
        [section]: {
          ...prev[section],
          ...updates,
        },
      }));
    },
    []
  );

  /**
   * Update nested existing infrastructure properties
   */
  const updateExistingInfra = useCallback(
    (
      key: keyof WizardState["existingInfrastructure"],
      value: WizardState["existingInfrastructure"][typeof key]
    ) => {
      setWizardState((prev) => ({
        ...prev,
        existingInfrastructure: {
          ...prev.existingInfrastructure,
          [key]: value,
        },
      }));
    },
    []
  );

  /**
   * Update EV chargers with specific level
   */
  const updateEVChargers = useCallback(
    (level: "L1" | "L2" | "L3", updates: Partial<{ count: number; powerKW: number }>) => {
      setWizardState((prev) => ({
        ...prev,
        existingInfrastructure: {
          ...prev.existingInfrastructure,
          evChargers: {
            ...prev.existingInfrastructure.evChargers,
            [level]: {
              ...prev.existingInfrastructure.evChargers[level],
              ...updates,
            },
          },
        },
      }));
    },
    []
  );

  /**
   * Update new EV chargers in goals
   */
  const updateNewEVChargers = useCallback(
    (level: "L2" | "L3", updates: Partial<{ count: number; powerKW: number }>) => {
      setWizardState((prev) => ({
        ...prev,
        goals: {
          ...prev.goals,
          newEVChargers: {
            ...prev.goals.newEVChargers,
            [level]: {
              ...prev.goals.newEVChargers[level],
              ...updates,
            },
          },
        },
      }));
    },
    []
  );

  // ────────────────────────────────────────────
  // CALCULATION FUNCTIONS
  // ────────────────────────────────────────────

  /**
   * Calculate building base load by DELEGATING to SSOT (useCasePowerCalculations.ts)
   * This ensures Power Profile shows the same values as the final quote.
   */
  const calculateBuildingLoad = useCallback((state: WizardState): number => {
    const industryType = state.industry.type.toLowerCase();

    // DEBUG: Log input state
    console.log("🔧 [calculateBuildingLoad] INPUT:", {
      industryType,
      facilitySquareFeet: state.facility.squareFeet,
      facilityRoomCount: state.facility.roomCount,
      useCaseData: state.useCaseData,
    });

    // Skip calculation if no industry selected
    if (!industryType || industryType === "") {
      console.log("🔧 [calculateBuildingLoad] No industry - returning 0");
      return 0;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // CRITICAL FIX: Merge useCaseData (template-specific fields) with facility data
    // This ensures industry-specific fields like annualPassengers, gamingSpaceSqFt
    // are passed to SSOT calculations, not just generic facility.squareFeet
    // ═══════════════════════════════════════════════════════════════════════
    const useCaseData: Record<string, any> = {
      // First, spread ALL custom question data (annualPassengers, gamingSpaceSqFt, etc.)
      ...state.useCaseData,

      // Then add facility variants (some templates use facility.*, some use useCaseData.*)
      // Square footage variants
      squareFeet: state.useCaseData.squareFeet || state.facility.squareFeet || 0,
      facilitySqFt: state.useCaseData.facilitySqFt || state.facility.squareFeet || 0,
      buildingSqFt: state.useCaseData.buildingSqFt || state.facility.squareFeet || 0,

      // Room count variants (hotels, apartments)
      roomCount: state.useCaseData.roomCount || state.facility.roomCount || 0,
      numberOfRooms: state.useCaseData.numberOfRooms || state.facility.roomCount || 0,
      rooms: state.useCaseData.rooms || state.facility.roomCount || 0,

      // Bed count (hospitals)
      bedCount:
        state.useCaseData.bedCount || state.facility.bedCount || state.facility.roomCount || 0,
      beds: state.useCaseData.beds || state.facility.bedCount || state.facility.roomCount || 0,

      // Rack count (data centers)
      rackCount: state.useCaseData.rackCount || state.facility.rackCount || 0,
      racks: state.useCaseData.racks || state.facility.rackCount || 0,

      // Data center IT load (convert MW to kW for SSOT)
      // Database stores itLoadMW (in MW), SSOT expects itLoadKW (in kW)
      itLoadKW: (() => {
        const itLoadKW = state.useCaseData.itLoadKW;
        const itLoadMW = state.useCaseData.itLoadMW;
        const converted = itLoadMW ? parseFloat(itLoadMW) * 1000 : undefined;
        console.log("🔧 [useCaseData mapping] IT Load conversion:", {
          raw_itLoadKW: itLoadKW,
          raw_itLoadMW: itLoadMW,
          parsed_MW: itLoadMW ? parseFloat(itLoadMW) : "N/A",
          converted_kW: converted,
          final: itLoadKW || converted,
        });
        return itLoadKW || converted;
      })(),

      // Bay count (car wash)
      washBays: state.useCaseData.washBays || state.facility.bayCount || 0,
      bayCount: state.useCaseData.bayCount || state.facility.bayCount || 0,

      // Unit count (apartments)
      unitCount: state.useCaseData.unitCount || state.facility.unitCount || 0,
      numUnits: state.useCaseData.numUnits || state.facility.unitCount || 0,

      // Hospital-specific equipment (for accurate power calculations)
      surgicalSuites: state.useCaseData.surgicalSuites || state.facility.surgicalSuites || 0,
      operatingRooms:
        state.useCaseData.operatingRooms ||
        state.useCaseData.surgicalSuites ||
        state.facility.surgicalSuites ||
        0,
      mriCount: state.useCaseData.mriCount || state.facility.mriCount || 0,
      mriMachines:
        state.useCaseData.mriMachines || state.useCaseData.mriCount || state.facility.mriCount || 0,
      ctScannerCount: state.useCaseData.ctScannerCount || state.facility.ctScannerCount || 0,
      ctScanners:
        state.useCaseData.ctScanners ||
        state.useCaseData.ctScannerCount ||
        state.facility.ctScannerCount ||
        0,
      icuBeds: state.useCaseData.icuBeds || state.facility.icuBeds || 0,
      icuBedCount:
        state.useCaseData.icuBedCount || state.useCaseData.icuBeds || state.facility.icuBeds || 0,

      // Generic fallback
      facilitySize:
        state.useCaseData.facilitySize ||
        state.facility.squareFeet ||
        state.facility.roomCount ||
        0,
    };

    console.log("🔧 [calculateBuildingLoad] useCaseData being sent to SSOT:", useCaseData);

    try {
      // DELEGATE to SSOT - this is the single source of truth
      const powerResult = calculateUseCasePower(industryType, useCaseData);

      // Convert MW to kW
      const baseLoadKW = powerResult.powerMW * 1000;

      console.log("🔧 [calculateBuildingLoad] SSOT result:", {
        industryType,
        squareFeet: useCaseData.squareFeet,
        powerMW: powerResult.powerMW,
        baseLoadKW,
        description: powerResult.description,
      });

      return Math.round(baseLoadKW * 10) / 10; // Round to 1 decimal
    } catch (error) {
      console.warn("[useWizardState] SSOT calculation failed, using fallback:", error);
      // Fallback: 4 W/sq ft default if SSOT fails
      const fallbackLoad = (state.facility.squareFeet || 0) * 0.004 * 0.75;
      return Math.round(fallbackLoad * 10) / 10;
    }
  }, []);

  /**
   * Calculate total load from existing EV chargers
   * Applies concurrency factor since not all chargers are used simultaneously
   */
  const calculateEVLoad = useCallback(
    (chargers: WizardState["existingInfrastructure"]["evChargers"]): number => {
      // EV charger concurrency: typically 30-50% at commercial sites
      // Hotels: 35% (guests charge overnight, not all at once)
      // Retail/Commercial: 40% (higher turnover)
      // EV stations: 50% (dedicated charging)
      const EV_CONCURRENCY_FACTOR = 0.4; // 40% concurrent usage assumption

      const installedCapacityKW =
        chargers.L1.count * chargers.L1.powerKW +
        chargers.L2.count * chargers.L2.powerKW +
        chargers.L3.count * chargers.L3.powerKW;

      // Apply concurrency - not all chargers run at peak simultaneously
      return Math.round(installedCapacityKW * EV_CONCURRENCY_FACTOR);
    },
    []
  );

  /**
   * Calculate load from NEW EV chargers (goals section)
   * Applies concurrency factor since not all chargers are used simultaneously
   */
  const calculateNewEVLoad = useCallback((goals: WizardState["goals"]): number => {
    if (!goals.addEVChargers) return 0;

    const EV_CONCURRENCY_FACTOR = 0.4; // 40% concurrent usage assumption

    const installedCapacityKW =
      goals.newEVChargers.L2.count * goals.newEVChargers.L2.powerKW +
      goals.newEVChargers.L3.count * goals.newEVChargers.L3.powerKW;

    return Math.round(installedCapacityKW * EV_CONCURRENCY_FACTOR);
  }, []);

  /**
   * Determine recommended backup hours based on grid reliability and industry
   */
  const getRecommendedBackupHours = useCallback((state: WizardState): number => {
    let hours = 4; // Default

    // Check for data center-specific backup duration target
    const datacenterIndustries = ["data-center", "datacenter", "edge-data-center"];
    const isDataCenter = datacenterIndustries.includes(state.industry.type.toLowerCase());

    if (isDataCenter && state.useCaseData?.backupDurationTarget) {
      // Use explicit backup duration from data center configuration
      const durationMap: Record<string, number> = {
        "15_minutes": 0.25,
        "2_hours": 2,
        "4_hours": 4,
        "6_hours": 6,
        "8_hours": 8,
        "12_hours": 12,
        "24_hours": 24,
      };
      return durationMap[state.useCaseData.backupDurationTarget] || 4;
    }

    // Check for data center grid connection status
    if (isDataCenter && state.useCaseData?.gridConnectionStatus) {
      switch (state.useCaseData.gridConnectionStatus) {
        case "off_grid":
          hours = 8; // Off-grid minimum
          break;
case "microgrid":
          hours = 6; // Microgrid with renewable integration
          break;
case "unreliable_grid":
          hours = 6;
          break;
case "limited_grid":
          hours = 5;
          break;
case "on_grid_reliable":
        default:
          hours = 4; // Standard UPS + BESS
      }
      return hours;
    }

    // Fallback: Adjust based on generic grid reliability
    switch (state.existingInfrastructure.gridConnection) {
      case "unreliable":
        hours = 6;
        break;
case "limited":
        hours = 5;
        break;
case "expensive":
        hours = 4; // Peak shaving focus, not backup
        break;
case "off-grid":
        hours = 8;
        break;
      }
default:
        hours = 4;
    }

    // Critical facilities: hospitals need extended backup
    const hospitalIndustries = ["hospital"];
    if (hospitalIndustries.includes(state.industry.type.toLowerCase())) {
      hours = Math.max(hours, 8); // Hospitals need extended backup for patient safety
    }

    // Data centers: Use standard 4 hours unless off-grid
    if (isDataCenter) {
      hours = Math.max(hours, 4); // UPS + 4hr BESS is industry standard minimum
    }

    // Hotels/hospitality need reasonable backup
    const hospitalityIndustries = ["hotel", "hotel-hospitality"];
    if (hospitalityIndustries.includes(state.industry.type.toLowerCase())) {
      hours = Math.max(hours, 4);
    }

    return hours;
  }, []);

  /**
   * Recalculate ALL derived values
   */
  const recalculate = useCallback(
    (state: WizardState): WizardState["calculated"] => {
      const baseBuildingLoadKW = calculateBuildingLoad(state);
      const existingEVLoadKW = calculateEVLoad(state.existingInfrastructure.evChargers);
      const newEVLoadKW = calculateNewEVLoad(state.goals);
      const totalPeakDemandKW = baseBuildingLoadKW + existingEVLoadKW + newEVLoadKW;

      console.log("🔋🔋🔋 [recalculate] CRITICAL DATA CENTER DEBUG:", {
        industryType: state.industry.type,
        baseBuildingLoadKW,
        existingEVLoadKW,
        newEVLoadKW,
        totalPeakDemandKW,
        facilityData: {
          squareFeet: state.facility.squareFeet,
          rackCount: state.facility.rackCount,
          itLoadKW: state.useCaseData?.itLoadKW,
          useCaseDataKeys: Object.keys(state.useCaseData || {}),
        },
      });

      const recommendedBackupHours = getRecommendedBackupHours(state);

      // ═══════════════════════════════════════════════════════════════════════
      // BESS SIZING v2.0 - BENCHMARK-BACKED METHODOLOGY (Dec 2025)
      // Sources: IEEE 4538388, MDPI Energies 11(8):2048, NREL ATB 2024
      // ═══════════════════════════════════════════════════════════════════════

      // BESS Power ratio depends on primary application:
      // | Use Case       | Ratio | Description                          |
      // |----------------|-------|--------------------------------------|
      // | peak_shaving   | 0.40  | Shave top demand peaks only          |
      // | arbitrage      | 0.50  | Peak shaving + TOU energy shifting   |
      // | resilience     | 0.70  | Cover critical loads during outages  |
      // | microgrid      | 1.00  | Full islanding capability            |

      // Map user's primary goal to BESS use case
      let bessRatio = BESS_POWER_RATIOS.peak_shaving; // Default: 0.40 (most common)

      // Check for data center-specific BESS application
      const datacenterIndustries = ["data-center", "datacenter", "edge-data-center"];
      const isDataCenter = datacenterIndustries.includes(state.industry.type.toLowerCase());

      if (isDataCenter && state.useCaseData?.primaryBESSApplication) {
        // Use data center-specific BESS sizing ratios
        switch (state.useCaseData.primaryBESSApplication) {
          case "ups_ride_through":
            bessRatio = 0.25; // 15-30 min ride-through only
            break;
case "backup_power":
            bessRatio = BESS_POWER_RATIOS.resilience; // 0.70 - extended backup
            break;
case "microgrid":
            bessRatio = BESS_POWER_RATIOS.microgrid; // 1.00 - full islanding capability
            break;
case "load_leveling":
            bessRatio = 0.6; // Smooth renewable variability
            break;
case "peak_shaving":
            bessRatio = BESS_POWER_RATIOS.peak_shaving; // 0.40 - demand charge reduction
            break;
case "frequency_regulation":
            bessRatio = 0.3; // Fast response, shorter duration
            break;
          }
default:
            bessRatio = BESS_POWER_RATIOS.peak_shaving;
        }
      } else if (isDataCenter && state.useCaseData?.gridConnectionStatus === "off_grid") {
        // Off-grid data centers require full coverage
        bessRatio = BESS_POWER_RATIOS.microgrid; // 1.00 - must cover full load
      } else if (isDataCenter && state.useCaseData?.gridConnectionStatus === "microgrid") {
        // Microgrid data centers with renewable integration
        bessRatio = BESS_POWER_RATIOS.microgrid; // 1.00 - islanding capability
      } else {
        // Standard goal-based sizing for non-data-center or unspecified
        const primaryGoal = state.goals?.primaryGoal || "savings";
        switch (primaryGoal) {
          case "backup":
            bessRatio = BESS_POWER_RATIOS.resilience; // 0.70 - critical load backup
            break;
case "savings":
            bessRatio = BESS_POWER_RATIOS.arbitrage; // 0.50 - cost optimization
            break;
case "sustainability":
            bessRatio = BESS_POWER_RATIOS.arbitrage; // 0.50 - renewable integration
            break;
case "peak-shaving":
            bessRatio = BESS_POWER_RATIOS.peak_shaving; // 0.40 - demand charge reduction
            break;
          }
default:
            bessRatio = BESS_POWER_RATIOS.peak_shaving; // Default to optimal economic sizing
        }
      }

      // Calculate BESS power and energy
      let recommendedBatteryKW = Math.round(totalPeakDemandKW * bessRatio);
      let recommendedBatteryKWh = Math.round(recommendedBatteryKW * recommendedBackupHours);

      console.log("🔋 [recalculate] BESS sizing v2.0:", {
        totalPeakDemandKW,
        bessRatio,
        primaryGoal:
          state.goals?.primaryGoal || state.useCaseData?.primaryBESSApplication || "default",
        gridStatus:
          state.useCaseData?.gridConnectionStatus || state.existingInfrastructure.gridConnection,
        recommendedBatteryKW,
        recommendedBatteryKWh,
        source: "IEEE 4538388, MDPI Energies 11(8):2048",
      });

      // ⚠️ SOLAR STORAGE: If user adds solar, increase battery to capture solar energy
      // Rule: Battery should be able to store 4-6 hours of solar generation for evening use
      // ⚠️ CRITICAL FIX (Dec 17, 2025): Cap solar influence to prevent feedback loop
      // Solar should NOT inflate battery beyond 2x the building load-based sizing
      const solarHours = state.location.solarHours || 5;

      // ⚠️ GUARD: Ensure solarKW is finite AND reasonable (max 3x peak demand for commercial)
      const maxReasonableSolarKW = totalPeakDemandKW * 3; // Industry standard: solar rarely exceeds 3x peak
      const userSolarKW =
        state.goals.addSolar && Number.isFinite(state.goals.solarKW) ? state.goals.solarKW : 0;
      const safeSolarKW = Math.min(userSolarKW, maxReasonableSolarKW);

      if (safeSolarKW > 0) {
        const solarDailyKWh = safeSolarKW * solarHours;
        const solarStorageKWh = Math.round(solarDailyKWh * 0.6); // Store 60% of daily solar

        // Cap battery increase from solar to max 2x the original load-based sizing
        const maxBatteryKWh = recommendedBatteryKWh * 2;
        const maxBatteryKW = recommendedBatteryKW * 2;

        // Take the larger of: peak demand backup OR solar storage (capped)
        recommendedBatteryKWh = Math.min(
          Math.max(recommendedBatteryKWh, solarStorageKWh),
          maxBatteryKWh
        );

        // Battery power should handle solar input rate (capped)
        const solarInputKW = Math.round(safeSolarKW * 0.8); // 80% of solar capacity
        recommendedBatteryKW = Math.min(Math.max(recommendedBatteryKW, solarInputKW), maxBatteryKW);

        console.log("🔋 [recalculate] Solar storage adjustment:", {
          userSolarKW,
          safeSolarKW,
          maxReasonableSolarKW,
          solarDailyKWh,
          solarStorageKWh,
          finalBatteryKWh: recommendedBatteryKWh,
          finalBatteryKW: recommendedBatteryKW,
        });
      }

      // Solar recommendation: Size solar relative to peak demand (NOT battery capacity)
      // Industry standard: Commercial solar = 0.5x to 1.5x peak demand
      // Using 1.2x to provide meaningful solar offset without oversizing
      const recommendedSolarKW = Math.round(totalPeakDemandKW * 1.2);

      // ⚠️ SAFETY CAP: Prevent any Infinity/NaN from escaping (max 50 MW systems)
      const MAX_KW = 50000; // 50 MW
      const MAX_KWH = 400000; // 400 MWh (8 hours at 50 MW)
      const safeValue = (val: number, max: number) =>
        Number.isFinite(val) ? Math.min(Math.max(0, val), max) : 0;

      const finalValues = {
        baseBuildingLoadKW: safeValue(Math.round(baseBuildingLoadKW * 10) / 10, MAX_KW),
        existingEVLoadKW: safeValue(existingEVLoadKW, MAX_KW),
        newEVLoadKW: safeValue(newEVLoadKW, MAX_KW),
        totalPeakDemandKW: safeValue(Math.round(totalPeakDemandKW * 10) / 10, MAX_KW),
        recommendedBatteryKWh: safeValue(recommendedBatteryKWh, MAX_KWH),
        recommendedBatteryKW: safeValue(recommendedBatteryKW, MAX_KW),
        recommendedSolarKW: safeValue(recommendedSolarKW, MAX_KW),
        recommendedBackupHours,
        // Financial estimates will be updated asynchronously via SSOT
        estimatedAnnualSavings: 0,
        estimatedPaybackYears: 0,
        estimatedCost: 0,
      };

      console.log("🔋 [recalculate] Final values:", {
        baseBuildingLoadKW: finalValues.baseBuildingLoadKW,
        existingEVLoadKW: finalValues.existingEVLoadKW,
        newEVLoadKW: finalValues.newEVLoadKW,
        totalPeakDemandKW: finalValues.totalPeakDemandKW,
        bessRatio,
        recommendedBackupHours,
        recommendedBatteryKWh: finalValues.recommendedBatteryKWh,
        recommendedBatteryKW: finalValues.recommendedBatteryKW,
        recommendedSolarKW: finalValues.recommendedSolarKW,
      });

      return finalValues;
    },
    [calculateBuildingLoad, calculateEVLoad, calculateNewEVLoad, getRecommendedBackupHours]
  );

  // ────────────────────────────────────────────
  // AUTO-RECALCULATE EFFECT
  // ────────────────────────────────────────────
  useEffect(() => {
    const newCalculated = recalculate(wizardState);

    // Debug logging - CRITICAL for tracing Power Gap updates
    console.log("⚡ [useWizardState] RECALCULATE TRIGGERED:", {
      industryType: wizardState.industry.type,
      facilitySquareFeet: wizardState.facility.squareFeet,
      facilityBedCount: wizardState.facility.bedCount,
      facilitySurgicalSuites: wizardState.facility.surgicalSuites,
      facilityMriCount: wizardState.facility.mriCount,
      useCaseData: wizardState.useCaseData,
      gridConnection: wizardState.existingInfrastructure.gridConnection,
      newCalculated,
    });

    // Only update if values actually changed (prevent infinite loop)
    const hasChanged = Object.keys(newCalculated).some(
      (key) =>
        newCalculated[key as keyof typeof newCalculated] !==
        wizardState.calculated[key as keyof typeof newCalculated]
    );

    if (hasChanged) {
      setWizardState((prev) => ({
        ...prev,
        calculated: newCalculated,
      }));
    }
  }, [
    wizardState.location,
    wizardState.industry,
    wizardState.facility,
    wizardState.useCaseData, // CRITICAL: Triggers recalc when template data changes
    wizardState.existingInfrastructure,
    wizardState.goals,
    recalculate,
  ]);

  // ────────────────────────────────────────────
  // ASYNC FINANCIAL ESTIMATION (SSOT - Dec 16, 2025)
  // Uses QuoteEngine.quickEstimate for accurate preview numbers
  // ────────────────────────────────────────────
  useEffect(() => {
    const { recommendedBatteryKW, recommendedBackupHours } = wizardState.calculated;

    // Skip if no battery recommendation yet
    if (recommendedBatteryKW <= 0) return;

    const storageSizeMW = recommendedBatteryKW / 1000;
    const electricityRate = wizardState.location.utilityRate || 0.15;

    // Debounce: only run after values stabilize
    const timeoutId = setTimeout(async () => {
      try {
        console.log("💰 [useWizardState] Calculating financial estimates via SSOT:", {
          storageSizeMW,
          durationHours: recommendedBackupHours,
          electricityRate,
        });

        const estimate = await QuoteEngine.quickEstimate(
          storageSizeMW,
          recommendedBackupHours,
          electricityRate
        );

        console.log("💰 [useWizardState] SSOT financial estimate:", estimate);

        setWizardState((prev) => ({
          ...prev,
          calculated: {
            ...prev.calculated,
            estimatedAnnualSavings: Math.round(estimate.annualSavings),
            estimatedPaybackYears: Math.round(estimate.paybackYears * 10) / 10,
            estimatedCost: Math.round(estimate.estimatedCost),
          },
        }));
      } catch (error) {
        console.error("💰 [useWizardState] Financial estimation failed:", error);
        // Keep previous values on error
      }
    }, 300); // 300ms debounce

    return () => clearTimeout(timeoutId);
  }, [
    wizardState.calculated.recommendedBatteryKW,
    wizardState.calculated.recommendedBackupHours,
    wizardState.location.utilityRate,
  ]);

  // ────────────────────────────────────────────
  // UTILITY FUNCTIONS
  // ────────────────────────────────────────────

  /**
   * Reset wizard to initial state
   */
  const resetState = useCallback(() => {
    setWizardState(INITIAL_WIZARD_STATE);
  }, []);

  /**
   * Get industry-specific info (for UI display purposes)
   * Note: Actual calculations are done by SSOT, this is just for UI hints
   */
  const getLoadFactorInfo = useCallback((industryType: string) => {
    const type = industryType.toLowerCase();

    // Simple mapping for UI display - actual calculation uses SSOT
    const uiHints: Record<string, { perUnit: number; unit: string }> = {
      office: { perUnit: 0.003, unit: "squareFeet" },
      hotel: { perUnit: 3.5, unit: "roomCount" },
      hospital: { perUnit: 0.015, unit: "squareFeet" },
      datacenter: { perUnit: 10, unit: "rackCount" },
      manufacturing: { perUnit: 0.008, unit: "squareFeet" },
      retail: { perUnit: 0.004, unit: "squareFeet" },
      "car-wash": { perUnit: 30, unit: "bays" },
      default: { perUnit: 0.004, unit: "squareFeet" },
    };

    return uiHints[type] || uiHints["default"];
  }, []);

  // ────────────────────────────────────────────
  // RETURN
  // ────────────────────────────────────────────
  return {
    // State
    wizardState,
    setWizardState,

    // Update functions
    updateSection,
    updateExistingInfra,
    updateEVChargers,
    updateNewEVChargers,

    // Utility functions
    resetState,
    getLoadFactorInfo,

    // Calculation functions (for manual recalc if needed)
    recalculate,
  };
}

