import { useState, useEffect } from 'react';
import { calculateFinancialMetrics } from '../../services/centralizedCalculations';

/**
 * Custom hook for financial calculations in StreamlinedWizard
 * Handles NPV, IRR, payback period, and savings calculations
 */

interface UseFinancialMetricsProps {
  storageSizeMW: number;
  durationHours: number;
  solarMW: number;
  windMW: number;
  location: string;
  electricityRate: number;
  costs: {
    equipmentCost: number;
    installationCost: number;
    shippingCost: number;
    totalUpfront: number;
  };
}

interface FinancialMetrics {
  npv: number;
  irr: number;
  paybackYears: number;
  annualSavings: number;
  lifetimeSavings: number;
  roi: number;
  isCalculating: boolean;
}

export const useFinancialMetrics = ({
  storageSizeMW,
  durationHours,
  solarMW,
  windMW,
  location,
  electricityRate,
  costs
}: UseFinancialMetricsProps): FinancialMetrics => {
  const [metrics, setMetrics] = useState<FinancialMetrics>({
    npv: 0,
    irr: 0,
    paybackYears: 0,
    annualSavings: 0,
    lifetimeSavings: 0,
    roi: 0,
    isCalculating: false
  });

  useEffect(() => {
    const calculateMetrics = async () => {
      if (costs.totalUpfront === 0 || storageSizeMW === 0) {
        return;
      }

      setMetrics(prev => ({ ...prev, isCalculating: true }));

      try {
        // Calculate annual savings based on storage and renewables
        const bessAnnualSavings = calculateBESSAnnualSavings(
          storageSizeMW,
          durationHours,
          electricityRate,
          location
        );

        const solarAnnualSavings = calculateSolarAnnualSavings(
          solarMW,
          electricityRate,
          location
        );

        const windAnnualSavings = calculateWindAnnualSavings(
          windMW,
          electricityRate,
          location
        );

        const totalAnnualSavings = bessAnnualSavings + solarAnnualSavings + windAnnualSavings;

        // Use centralized financial calculations
        const financialMetrics = await calculateFinancialMetrics({
          storageSizeMW,
          durationHours,
          solarMW: solarMW || 0,
          windMW: windMW || 0,
          location,
          electricityRate,
          equipmentCost: costs.equipmentCost,
          installationCost: costs.installationCost,
          shippingCost: costs.shippingCost,
          discountRate: 0.08,
          projectLifetimeYears: 25
        });

        // ✅ USE CENTRALIZED RESULTS - Single source of truth
        // DO NOT recalculate payback/roi locally - use what centralizedCalculations returns
        setMetrics({
          npv: financialMetrics.npv || 0,
          irr: financialMetrics.irr || 0, // Already a percentage from centralized service
          paybackYears: Math.round(financialMetrics.paybackYears * 10) / 10,
          annualSavings: financialMetrics.annualSavings,
          lifetimeSavings: financialMetrics.annualSavings * 25,
          roi: Math.round(financialMetrics.roi25Year || 0),
          isCalculating: false
        });

      } catch (error) {
        console.error('❌ [useFinancialMetrics] Error calculating metrics:', error);
        setMetrics(prev => ({ ...prev, isCalculating: false }));
      }
    };

    calculateMetrics();
  }, [storageSizeMW, durationHours, solarMW, windMW, location, electricityRate, costs]);

  return metrics;
};

/**
 * Calculate annual savings from BESS based on use cases
 */
const calculateBESSAnnualSavings = (
  storageMW: number,
  durationHrs: number,
  electricityRate: number,
  location: string
): number => {
  const energyMWh = storageMW * durationHrs;

  // Peak shaving value: ~2 cycles/day average
  const peakShavingCycles = 730; // 365 days * 2 cycles
  const peakShavingValue = energyMWh * peakShavingCycles * electricityRate * 0.6; // 60% efficiency

  // Demand charge reduction: ~$15/kW-month average
  const demandChargeSavings = storageMW * 1000 * 15 * 12; // kW * $/kW-month * months

  // Arbitrage value: ~1 cycle/day, $0.10/kWh spread
  const arbitrageCycles = 365;
  const arbitrageValue = energyMWh * 1000 * arbitrageCycles * 0.10 * 0.85; // 85% efficiency

  return peakShavingValue + demandChargeSavings + arbitrageValue;
};

/**
 * Calculate annual savings from solar
 */
const calculateSolarAnnualSavings = (
  solarMW: number,
  electricityRate: number,
  location: string
): number => {
  if (solarMW === 0) return 0;

  // Capacity factor varies by location (15-25%)
  const capacityFactor = location.toLowerCase().includes('california') ? 0.22 : 0.18;
  const annualGeneration = solarMW * 8760 * capacityFactor * 1000; // kWh/year

  return annualGeneration * electricityRate;
};

/**
 * Calculate annual savings from wind
 */
const calculateWindAnnualSavings = (
  windMW: number,
  electricityRate: number,
  location: string
): number => {
  if (windMW === 0) return 0;

  // Capacity factor varies by location (25-40%)
  const capacityFactor = 0.30; // Average
  const annualGeneration = windMW * 8760 * capacityFactor * 1000; // kWh/year

  return annualGeneration * electricityRate;
};

import { useState, useEffect } from 'react';
import { calculateDatabaseBaseline } from '../../services/baselineService';
import { calculateAutomatedSolarSizing, type SolarSizingResult } from '../../utils/solarSizingUtils';
import { calculateUseCasePower, calculateEVChargingPower } from '../../services/useCasePowerCalculations';

/**
 * Custom hook for system calculation logic in StreamlinedWizard
 * Extracts complex calculation logic from the main component
 * 
 * ⚠️ IMPORTANT: This hook now delegates power calculations to useCasePowerCalculations.ts
 * DO NOT add hardcoded power density values here - update the centralized service instead!
 */

interface UseSystemCalculationsProps {
  selectedTemplate: string;
  useCaseData: { [key: string]: any };
  isQuickstart: boolean;
}

interface SystemCalculations {
  storageSizeMW: number;
  durationHours: number;
  solarSuggestion: SolarSizingResult | null;
  isCalculating: boolean;
}

export const useSystemCalculations = ({
  selectedTemplate,
  useCaseData,
  isQuickstart
}: UseSystemCalculationsProps): SystemCalculations => {
  const [storageSizeMW, setStorageSizeMW] = useState(2);
  const [durationHours, setDurationHours] = useState(4);
  const [solarSuggestion, setSolarSuggestion] = useState<SystemCalculations['solarSuggestion']>(null);
  const [isCalculating, setIsCalculating] = useState(false);

  /**
   * @deprecated Use calculateUseCasePower() from useCasePowerCalculations.ts instead
   * This function is kept for backward compatibility but should not be used.
   * All power density standards are now in: src/services/useCasePowerCalculations.ts
   */
  const _deprecated_getPowerDensity = (buildingType: string, _subType?: string): number => {
    console.warn('⚠️ DEPRECATED: getPowerDensity() is deprecated. Use calculateUseCasePower() from useCasePowerCalculations.ts');
    // Redirect to centralized calculation
    const result = calculateUseCasePower(buildingType, {});
    return result.powerMW * 1000; // Return as kW for backward compatibility
  };

  /**
   * @deprecated Use calculateUseCasePower() directly - it handles scale internally
   * This function is kept ONLY for database baseline calls which still need scale.
   * 
   * ⚠️ WARNING: These scale factors may differ from SSOT calculations.
   * The SSOT (useCasePowerCalculations.ts) handles scaling internally with
   * more accurate industry-specific parameters.
   */
  const calculateScaleFactor = (template: string, data: { [key: string]: any }): number => {
    // Log deprecation in dev mode
    if (import.meta.env.DEV) {
      console.warn('⚠️ calculateScaleFactor is deprecated - SSOT handles scaling internally');
    }
    // For most use cases, we now use calculateUseCasePower directly
    // This function is only used as a fallback for baselineService
    switch (template) {
      case 'hotel':
        return (parseInt(data.numRooms) || 100) / 100;
      case 'car-wash':
        return parseInt(data.numBays) || 3;
      case 'hospital':
        return (parseInt(data.bedCount) || 200) / 100;
      case 'college':
        return (parseInt(data.enrollment) || 5000) / 1000;
      case 'apartment':
        return (parseInt(data.numUnits) || 100) / 100;
      case 'data-center':
        return parseInt(data.capacity) || 5;
      case 'airport':
        return parseInt(data.annual_passengers) || 5;
      case 'manufacturing':
        return parseInt(data.numLines) || parseInt(data.production_lines) || 2;
      case 'warehouse':
      case 'logistics':
        return (parseInt(data.facility_size) || 100) / 100;
      case 'retail':
        return (parseInt(data.store_size) || 50) / 10;
      case 'casino':
        return (parseInt(data.gaming_floor_size) || 50000) / 50000;
      case 'agricultural':
        return (parseInt(data.farm_size) || 1000) / 1000;
      case 'indoor-farm':
        return (parseInt(data.growing_area) || 10000) / 10000;
      case 'cold-storage':
        return (parseInt(data.storage_volume) || parseInt(data.capacity) || 50000) / 50000;
      case 'microgrid':
        return (parseInt(data.numBuildings) || parseInt(data.homes) || 50) / 50;
      default:
        return 1;
    }
  };

  /**
   * Calculate EV charging configuration
   * @deprecated Use calculateEVChargingPower() from useCasePowerCalculations.ts instead
   * This function delegates to the centralized calculation.
   */
  const calculateEVChargingConfig = (data: { [key: string]: any }) => {
    // Use centralized EV charging calculation
    const result = calculateEVChargingPower(
      parseInt(data.numberOfLevel1Chargers) || 0,
      parseInt(data.numberOfLevel2Chargers || data.level2Chargers) || 0,
      parseInt(data.numberOfDCFastChargers || data.dcFastChargers) || 0
    );

    if (import.meta.env.DEV) { console.log('🔌 [useSystemCalculations] EV config from centralized calc:', result); }

    return {
      powerMW: result.powerMW,
      durationHrs: result.durationHrs
    };
  };

  /**
   * Auto-calculate realistic configuration based on use case data
   * Uses centralized calculations from useCasePowerCalculations.ts
   */
  useEffect(() => {
    const calculateConfig = async () => {
      if (!selectedTemplate || Object.keys(useCaseData).length === 0 || isQuickstart) {
        return;
      }

      setIsCalculating(true);

      try {
        // ✅ PRIMARY: Use centralized power calculation for ALL use cases
        // This is the SINGLE SOURCE OF TRUTH for power calculations
        const centralizedResult = calculateUseCasePower(selectedTemplate, useCaseData);
        if (import.meta.env.DEV) { console.log('⚡ [useSystemCalculations] Centralized power calculation:', centralizedResult); }

        // Special handling for EV charging (centralized calc is sufficient)
        if (selectedTemplate === 'ev-charging') {
          setStorageSizeMW(centralizedResult.powerMW);
          setDurationHours(centralizedResult.durationHrs);
          setSolarSuggestion(null); // Solar is optional for EV charging
        } else {
          // For other use cases, also check database baseline for additional config
          const scale = calculateScaleFactor(selectedTemplate, useCaseData);

          // Use shared database-driven baseline calculation
          const baseline = await calculateDatabaseBaseline(selectedTemplate, scale, useCaseData);
          if (import.meta.env.DEV) { console.log('🎯 [useSystemCalculations] Database baseline:', baseline); }

          // Use the higher of centralized or database calculation
          // This ensures we don't undersize due to missing database entries
          const finalPowerMW = Math.max(centralizedResult.powerMW, baseline.powerMW);
          const finalDurationHrs = baseline.durationHrs || centralizedResult.durationHrs;

          if (import.meta.env.DEV) { console.log(`📊 [useSystemCalculations] Final power: ${finalPowerMW} MW (centralized: ${centralizedResult.powerMW}, baseline: ${baseline.powerMW})`); }

          setStorageSizeMW(finalPowerMW);
          setDurationHours(finalDurationHrs);

          // Enhanced solar sizing using automated calculation
          const buildingCharacteristics = {
            useCase: selectedTemplate,
            buildingSize: useCaseData.buildingSize || useCaseData.facilitySize,
            facilitySize: useCaseData.facilitySize,
            peakLoad: finalPowerMW,
            electricalLoad: useCaseData.electricalLoad || useCaseData.peakLoad,
            capacity: useCaseData.capacity,
            numRooms: useCaseData.numRooms,
            storageVolume: useCaseData.storageVolume || useCaseData.storage_volume,
            growingArea: useCaseData.growingArea || useCaseData.growing_area,
            storeSize: useCaseData.storeSize || useCaseData.store_size,
            gamingFloorSize: useCaseData.gamingFloorSize || useCaseData.gaming_floor_size
          };

          const suggestion = calculateAutomatedSolarSizing(buildingCharacteristics);
          setSolarSuggestion(suggestion);

          console.log('🌞 [useSystemCalculations] Solar suggestion:', {
            template: selectedTemplate,
            characteristics: buildingCharacteristics,
            suggestion,
            note: 'User must explicitly choose solar in Step 3'
          });
        }
      } catch (error) {
        console.error('❌ [useSystemCalculations] Error calculating config:', error);
      } finally {
        setIsCalculating(false);
      }
    };

    calculateConfig();
  }, [selectedTemplate, useCaseData, isQuickstart]);

  return {
    storageSizeMW,
    durationHours,
    solarSuggestion,
    isCalculating
  };
};

/**
 * Equipment Repository
 * ====================
 * Infrastructure layer - All database access for equipment data.
 * 
 * This repository handles fetching equipment templates, specifications,
 * and configuration equipment from the database.
 * 
 * Part of the infrastructure layer - handles data persistence only.
 */

import { supabase } from '@/services/supabaseClient';
import type { Database } from '@/types/database.types';

// Database row types
type EquipmentTemplateRow = Database['public']['Tables']['equipment_templates']['Row'];
type ConfigurationEquipmentRow = Database['public']['Tables']['configuration_equipment']['Row'];

/**
 * Repository for Equipment data access
 */
export class EquipmentRepository {

  /**
   * Get equipment template by ID
   */
  async findById(id: string): Promise<EquipmentTemplateRow | null> {
    const { data, error } = await supabase
      .from('equipment_templates')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      if (error.code === 'PGRST116') return null; // Not found
      console.error('Error fetching equipment template:', error);
      throw new Error(`Failed to fetch equipment: ${error.message}`);
    }

    return data;
  }

  /**
   * Get all equipment templates for a use case
   */
  async findByUseCaseId(useCaseId: string): Promise<EquipmentTemplateRow[]> {
    const { data, error } = await supabase
      .from('equipment_templates')
      .select('*')
      .eq('use_case_id', useCaseId)
      .order('display_order');

    if (error) {
      console.error('Error fetching equipment templates:', error);
      throw new Error(`Failed to fetch equipment: ${error.message}`);
    }

    return data || [];
  }

  /**
   * Get equipment for a specific configuration
   */
  async findByConfigurationId(configurationId: string): Promise<Array<ConfigurationEquipmentRow & {
    equipment_template: EquipmentTemplateRow;
  }>> {
    const { data, error } = await supabase
      .from('configuration_equipment')
      .select(`
        *,
        equipment_template:equipment_templates(*)
      `)
      .eq('configuration_id', configurationId)
      .order('display_order');

    if (error) {
      console.error('Error fetching configuration equipment:', error);
      throw new Error(`Failed to fetch configuration equipment: ${error.message}`);
    }

    return data as any || [];
  }

  /**
   * Get equipment templates by category
   */
  async findByCategory(category: string): Promise<EquipmentTemplateRow[]> {
    const { data, error } = await supabase
      .from('equipment_templates')
      .select('*')
      .eq('category', category)
      .eq('is_active', true)
      .order('display_order');

    if (error) {
      console.error('Error fetching equipment by category:', error);
      throw new Error(`Failed to fetch equipment: ${error.message}`);
    }

    return data || [];
  }

  /**
   * Get all active equipment templates
   */
  async findAll(includeInactive = false): Promise<EquipmentTemplateRow[]> {
    let query = supabase
      .from('equipment_templates')
      .select('*')
      .order('display_order');

    if (!includeInactive) {
      query = query.eq('is_active', true);
    }

    const { data, error } = await query;

    if (error) {
      console.error('Error fetching equipment templates:', error);
      throw new Error(`Failed to fetch equipment: ${error.message}`);
    }

    return data || [];
  }

  /**
   * Search equipment templates by name or description
   */
  async search(searchTerm: string): Promise<EquipmentTemplateRow[]> {
    const { data, error } = await supabase
      .from('equipment_templates')
      .select('*')
      .or(`name.ilike.%${searchTerm}%,description.ilike.%${searchTerm}%`)
      .eq('is_active', true)
      .order('display_order');

    if (error) {
      console.error('Error searching equipment:', error);
      throw new Error(`Failed to search equipment: ${error.message}`);
    }

    return data || [];
  }

  /**
   * Get equipment statistics
   */
  async getStatistics(): Promise<{
    totalEquipment: number;
    byCategory: Record<string, number>;
    averagePowerKw: number;
    totalNameplateCapacityKw: number;
  }> {
    const { data, error } = await supabase
      .from('equipment_templates')
      .select('category, nameplate_power_kw')
      .eq('is_active', true);

    if (error) {
      console.error('Error fetching equipment statistics:', error);
      return {
        totalEquipment: 0,
        byCategory: {},
        averagePowerKw: 0,
        totalNameplateCapacityKw: 0
      };
    }

    const stats = {
      totalEquipment: data.length,
      byCategory: {} as Record<string, number>,
      averagePowerKw: 0,
      totalNameplateCapacityKw: 0
    };

    data.forEach(item => {
      // Count by category
      stats.byCategory[item.category] = (stats.byCategory[item.category] || 0) + 1;

      // Sum power
      stats.totalNameplateCapacityKw += item.nameplate_power_kw || 0;
    });

    stats.averagePowerKw = data.length > 0 
      ? stats.totalNameplateCapacityKw / data.length 
      : 0;

    return stats;
  }
}

