}

export interface SolarCapacityResult {
  // Normalized inputs
  roofArea: number;
  roofUnit: 'sqft';
  carportArea: number;
  carportUnit: 'sqft';
  carportInterest: 'yes' | 'no' | 'unsure';

  // Calculated values - ROOF
