  // ─────────────────────────────────────────────────────────────
  // BESS RECOMMENDATION
  // ─────────────────────────────────────────────────────────────
  bess: {
    powerKW: number;
    energyKWh: number;
    durationHours: number;     // energyKWh / powerKW
    chemistry: BatteryChemistry;
    efficiency: number;        // 0.85-0.95
    warrantyYears: number;
    estimatedCost: number;
    costPerKwh: number;
  };

  // ─────────────────────────────────────────────────────────────
  // SOLAR RECOMMENDATION
