    dcfcCount: number;
    dcfcPowerKW: number;
    ultraFastCount: number;
    ultraFastPowerKW: number;
    totalPowerKW: number;
    estimatedCost: number;
  };

  // ─────────────────────────────────────────────────────────────
  // UTILITY & LOCATION DATA
  // ─────────────────────────────────────────────────────────────
  utility: {
    name: string;
    rate: number;              // $/kWh
    demandCharge: number;      // $/kW
    hasTOU: boolean;           // Time of Use pricing
    peakRate?: number;
    offPeakRate?: number;
