    if (solarSources.length > 0) {
      const marketMin = Math.min(...solarSources.map((s) => s.priceRange.min));
      const marketMax = Math.max(...solarSources.map((s) => s.priceRange.max));

      this.checkPriceDeviation(
        "Solar Utility Scale",
