  // Schedule daily validation at 6 AM
  const scheduleDaily = () => {
    const now = new Date();
    const tomorrow6AM = new Date();
    tomorrow6AM.setDate(tomorrow6AM.getDate() + 1);
    tomorrow6AM.setHours(6, 0, 0, 0);

    const msUntil6AM = tomorrow6AM.getTime() - now.getTime();

    setTimeout(() => {
