  model: string;
  manufacturer: string;
  fuelType: "natural_gas" | "diesel" | "propane" | "dual_fuel";
  ratedPowerKW: number;
  standbyPowerKW: number;
  engine: {
    model: string;
    displacement: number; // in liters
    cylinders: number;
    ratedSpeedRPM: number;
