class PricingConfigService {
  private config: PricingConfiguration;
  private useDatabase: boolean = true; // Flag to enable/disable database usage
  private configCache: PricingConfiguration | null = null;
  private cacheExpiry: number = 0;
  private readonly CACHE_DURATION_MS = 5 * 60 * 1000; // 5 minutes

  constructor() {
    // Initialize with defaults (will be overridden by loadFromDatabase)
    this.config = DEFAULT_PRICING_CONFIG;

    // Try to load from database first, fallback to localStorage, then defaults
    this.loadConfiguration();
  }

  /**
   * Load configuration from database, localStorage, or defaults
   * Priority: Database > localStorage > Defaults
   */
  private async loadConfiguration(): Promise<void> {
    try {
      // Try database first
      if (this.useDatabase) {
        const dbConfig = await this.loadFromDatabase();
        if (dbConfig) {
          this.config = dbConfig;
          // Migrate localStorage to database if it exists and is newer
          await this.migrateLocalStorageToDatabase();
          return;
        }
      }

      // Fallback to localStorage
      const savedConfig = localStorage.getItem("pricingConfiguration");
      if (savedConfig) {
        try {
          const parsed = JSON.parse(savedConfig);
          if (this.validateConfig(parsed)) {
            this.config = parsed;
            // Try to save to database for future use
            if (this.useDatabase) {
              await this.saveToDatabase(this.config, "Migrated from localStorage");
            }
            return;
          }
        } catch (e) {
          console.warn("Failed to parse localStorage pricing config:", e);
        }
      }

      // Use defaults
      this.config = DEFAULT_PRICING_CONFIG;
    } catch (error) {
      console.error("Error loading pricing configuration:", error);
      // Fallback to localStorage or defaults
      const savedConfig = localStorage.getItem("pricingConfiguration");
      if (savedConfig) {
        try {
          this.config = JSON.parse(savedConfig);
        } catch {
          this.config = DEFAULT_PRICING_CONFIG;
        }
      }
    }
  }

  /**
   * Load configuration from database
   */
  private async loadFromDatabase(): Promise<PricingConfiguration | null> {
    // Check cache first
    if (this.configCache && Date.now() < this.cacheExpiry) {
      return this.configCache;
    }

    try {
      // Try new schema first (config_key based)
      let { data, error } = await supabase
        .from("pricing_configurations")
        .select("*")
        .eq("is_active", true)
        .order("updated_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      // If no data, try legacy schema (is_default based)
      if (error || !data) {
        const legacyQuery = await supabase
          .from("pricing_configurations")
          .select("*")
          .eq("is_active", true)
          .eq("is_default", true)
          .order("updated_at", { ascending: false })
          .limit(1)
          .maybeSingle();

        if (!legacyQuery.error && legacyQuery.data) {
          data = legacyQuery.data;
          error = null;
        }
      }

      if (error) {
        // Table might not exist yet - that's okay during migration
        if (error.code === "PGRST116" || error.message?.includes("does not exist")) {
          console.warn("pricing_configurations table not found - using fallback");
          return null;
        }
        // Column doesn't exist - table schema mismatch, use fallback
        if (
          error.code === "42703" ||
          error.message?.includes("column") ||
          error.message?.includes("does not exist")
        ) {
          console.warn("pricing_configurations table schema mismatch - using fallback");
          return null;
        }
        throw error;
      }

      if (!data || !data.config_data) {
        return null;
      }

      // Convert database format to PricingConfiguration
      const config: PricingConfiguration = {
        ...(data.config_data as any),
        lastUpdated: data.last_updated || data.updated_at,
        updatedBy: data.updated_by || "System",
        version: data.version || "1.0.0",
      };

      // Validate the config
      if (!this.validateConfig(config)) {
        console.warn("Invalid config from database, using defaults");
        return null;
      }

      // Cache the result
      this.configCache = config;
      this.cacheExpiry = Date.now() + this.CACHE_DURATION_MS;

      return config;
    } catch (error) {
      console.error("Error loading from database:", error);
      return null;
    }
  }

  /**
   * Save configuration to database
   */
  private async saveToDatabase(config: PricingConfiguration, notes?: string): Promise<boolean> {
    try {
      // First, unset any existing default
      await supabase
        .from("pricing_configurations")
        .update({ is_default: false })
        .eq("is_default", true);

      // Check if default config exists
      const { data: existing } = await supabase
        .from("pricing_configurations")
        .select("id")
        .eq("is_default", true)
        .limit(1)
        .single();

      const configData = {
        name: "Default Pricing Configuration",
        description: "Active pricing configuration for quote calculations",
        version: config.version,
        is_active: true,
        is_default: true,
        config_data: {
          bess: config.bess,
          solar: config.solar,
          officeBuilding: config.officeBuilding,
          wind: config.wind,
          generators: config.generators,
          powerElectronics: config.powerElectronics,
          evCharging: config.evCharging,
          balanceOfPlant: config.balanceOfPlant,
          systemControls: config.systemControls,
        },
        updated_by: config.updatedBy || "System",
        notes: notes || `Updated via pricingConfigService`,
      };

      let error;
      if (existing?.id) {
        // Update existing
        const { error: updateError } = await supabase
          .from("pricing_configurations")
          .update(configData)
          .eq("id", existing.id);
        error = updateError;
      } else {
        // Insert new
        const { error: insertError } = await supabase
          .from("pricing_configurations")
          .insert(configData);
        error = insertError;
      }

      if (error) {
        // If table doesn't exist, that's okay - we'll use localStorage
        if (error.code === "PGRST116" || error.message?.includes("does not exist")) {
          console.warn("pricing_configurations table not found - saving to localStorage");
          return false;
        }
        throw error;
      }

      // Clear cache
      this.configCache = null;
      this.cacheExpiry = 0;

      return true;
    } catch (error) {
      console.error("Error saving to database:", error);
      return false;
    }
  }

  /**
   * Migrate localStorage config to database if it's newer
   */
  private async migrateLocalStorageToDatabase(): Promise<void> {
    try {
      const savedConfig = localStorage.getItem("pricingConfiguration");
      if (!savedConfig) return;

      const localConfig = JSON.parse(savedConfig);
      if (!this.validateConfig(localConfig)) return;

      // Check if localStorage config is newer
      const localDate = new Date(localConfig.lastUpdated || 0);
      const dbDate = new Date(this.config.lastUpdated || 0);

      if (localDate > dbDate) {
        // localStorage is newer - migrate to database
        console.log("Migrating newer localStorage config to database...");
        await this.saveToDatabase(localConfig, "Migrated from localStorage (newer version)");
        // Keep localStorage as backup
      } else {
        // Database is newer or same - remove localStorage
        localStorage.removeItem("pricingConfiguration");
      }
    } catch (error) {
      console.error("Error during localStorage migration:", error);
    }
  }

  getConfiguration(): PricingConfiguration {
    return { ...this.config };
  }

  async updateConfiguration(newConfig: Partial<PricingConfiguration>): Promise<void> {
    this.config = {
      ...this.config,
      ...newConfig,
      lastUpdated: new Date().toISOString(),
      version: this.incrementVersion(this.config.version),
    };

    // Save to database
    const savedToDb = await this.saveToDatabase(this.config);

    // Also save to localStorage as backup (during migration period)
    if (!savedToDb) {
      localStorage.setItem("pricingConfiguration", JSON.stringify(this.config));
    } else {
      // Remove localStorage if database save succeeded
      localStorage.removeItem("pricingConfiguration");
    }

    // Trigger recalculation of all quotes
    window.dispatchEvent(new CustomEvent("pricingConfigUpdated", { detail: this.config }));
  }

  async updateSection<K extends keyof PricingConfiguration>(
    section: K,
    updates: Partial<PricingConfiguration[K]>
  ): Promise<void> {
    this.config[section] = { ...(this.config[section] as any), ...(updates as any) };
    this.config.lastUpdated = new Date().toISOString();
    this.config.version = this.incrementVersion(this.config.version);

    // Save to database
    const savedToDb = await this.saveToDatabase(this.config);

    // Also save to localStorage as backup
    if (!savedToDb) {
      localStorage.setItem("pricingConfiguration", JSON.stringify(this.config));
    } else {
      localStorage.removeItem("pricingConfiguration");
    }

    window.dispatchEvent(new CustomEvent("pricingConfigUpdated", { detail: this.config }));
  }

  async resetToDefaults(): Promise<void> {
    this.config = {
      ...DEFAULT_PRICING_CONFIG,
      lastUpdated: new Date().toISOString(),
      version: "1.0.0",
    };

    // Save to database
    await this.saveToDatabase(this.config, "Reset to defaults");

    // Remove localStorage
    localStorage.removeItem("pricingConfiguration");

    window.dispatchEvent(new CustomEvent("pricingConfigUpdated", { detail: this.config }));
  }

  exportConfiguration(): string {
    return JSON.stringify(this.config, null, 2);
  }

  async importConfiguration(configJson: string): Promise<boolean> {
    try {
      const importedConfig = JSON.parse(configJson);
      // Validate the structure
      if (this.validateConfig(importedConfig)) {
        this.config = {
          ...importedConfig,
          lastUpdated: new Date().toISOString(),
          version: this.incrementVersion(this.config.version),
        };

        // Save to database
        const savedToDb = await this.saveToDatabase(this.config, "Imported from JSON");

        // Also save to localStorage as backup
        if (!savedToDb) {
          localStorage.setItem("pricingConfiguration", JSON.stringify(this.config));
        } else {
          localStorage.removeItem("pricingConfiguration");
        }

        window.dispatchEvent(new CustomEvent("pricingConfigUpdated", { detail: this.config }));
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  private validateConfig(config: any): boolean {
    // Basic validation to ensure required sections exist
    const requiredSections = [
      "bess",
      "solar",
      "wind",
      "generators",
      "powerElectronics",
      "evCharging",
      "balanceOfPlant",
      "systemControls",
    ];
    return requiredSections.every((section) => section in config);
  }

  private incrementVersion(version: string): string {
    const parts = version.split(".");
    const patch = parseInt(parts[2] || "0") + 1;
    return `${parts[0]}.${parts[1]}.${patch}`;
  }

  // Convenience methods for common calculations
  getBESSCostPerKWh(capacityMWh: number): number {
    if (capacityMWh >= 15) {
      return this.config.bess.largeSystemPerKWh;
    }
    if (capacityMWh >= 5) {
      return this.config.bess.mediumLargeSystemPerKWh;
    }
    if (capacityMWh >= 1) {
      return this.config.bess.mediumSystemPerKWh;
    }
    return this.config.bess.smallSystemPerKWh;
  }

  getSolarCostPerWatt(capacityMW: number): number {
    if (capacityMW >= 5) return this.config.solar.utilityScalePerWatt;
    if (capacityMW >= 0.1) return this.config.solar.commercialPerWatt;
    return this.config.solar.smallScalePerWatt;
  }

  getWindCostPerKW(capacityMW: number): number {
    if (capacityMW >= 10) return this.config.wind.utilityScalePerKW;
    if (capacityMW >= 1) return this.config.wind.commercialPerKW;
    return this.config.wind.smallScalePerKW;
  }

  getGeneratorCostPerKW(
    fuelType: "naturalGas" | "diesel" | "propane" | "bioGas" = "naturalGas"
  ): number {
    const fuelTypeMap = {
      naturalGas: "naturalGasPerKW",
      diesel: "dieselPerKW",
      propane: "propanePerKW",
      bioGas: "bioGasPerKW",
    } as const;

    return this.config.generators[fuelTypeMap[fuelType]];
  }

  /**
   * Force refresh from database (clears cache)
   */
  async refreshFromDatabase(): Promise<void> {
    this.configCache = null;
    this.cacheExpiry = 0;
    await this.loadConfiguration();
  }
}

export const pricingConfigService = new PricingConfigService();

// Main exports
export { PricingConfigService, DEFAULT_PRICING_CONFIG, defaultBESSPricing };

/**
 * Pricing Tier Service
 * ====================
 *
 * Service for querying size-based pricing tiers from the pricing_configurations table.
 * Supports both kW and MWh units for system sizing.
 *
 * Features:
 * - Size-based pricing tiers (different prices for different system sizes)
 * - 5 pricing levels: low, low_plus, mid, mid_plus, high
 * - Dual unit support: kW for most systems, MWh for very large systems
 * - Source tracking and confidence levels for TrueQuote compliance
 *
 * Usage:
 * ```typescript
 * const pricing = await getPricingTier('bess', 5000, null, 'mid');
 * // Returns pricing tier for 5 MW BESS system with mid-level pricing
 * ```
 *
 * Date: December 25, 2025
 */

import { supabase } from "./supabaseClient";

/**
 * Pricing tier price levels
 */
export type PriceLevel = "low" | "low_plus" | "mid" | "mid_plus" | "high";

/**
 * Pricing tier result from database
 */
export interface PricingTier {
  id: string;
  config_key: string;
  config_category: string;
  config_data: {
    price_low: number;
    price_low_plus: number;
    price_mid: number;
    price_mid_plus: number;
    price_high: number;
    price_unit: string;
    equipment_pct?: number;
    bos_pct?: number;
    labor_pct?: number;
    soft_costs_pct?: number;
    annual_om_pct?: number;
    source_type?: string;
    source_name?: string;
    source_date?: string;
    notes?: string;
  };
  size_min_kw: number | null;
  size_max_kw: number | null;
  size_min_mwh: number | null;
  size_max_mwh: number | null;
  data_source: string | null;
  confidence_level: "high" | "medium" | "low" | null;
  description: string | null;
  effective_date: string;
  expires_at: string | null;
}

/**
 * Get pricing tier for a system size
 *
 * @param category - Technology category ('bess', 'solar', 'wind', etc.)
 * @param sizeKW - System size in kW (use for systems < 50 MW)
 * @param sizeMWh - System size in MWh (use for very large systems, e.g., 300 MW = 300 MWh at 1 hour)
 * @param priceLevel - Price level to return (default: 'mid')
 * @returns Pricing tier with selected price level, or null if no tier found
 */
export async function getPricingTier(
  category: string,
  sizeKW?: number | null,
  sizeMWh?: number | null,
  priceLevel: PriceLevel = "mid"
): Promise<{ price: number; unit: string; tier: PricingTier } | null> {
  try {
    // Try using database function first (more reliable)
    if (sizeKW !== null && sizeKW !== undefined) {
      const { data: funcData, error: funcError } = await supabase.rpc("get_pricing_tier", {
        p_category: category,
        p_size_kw: sizeKW,
        p_size_mwh: null,
      });

      if (!funcError && funcData && funcData.length > 0) {
        const tierData = funcData[0];
        const configData = tierData.config_data as PricingTier["config_data"];

        let price: number = configData.price_mid;
        if (priceLevel === "low") price = configData.price_low;
        else if (priceLevel === "low_plus") price = configData.price_low_plus;
        else if (priceLevel === "mid") price = configData.price_mid;
        else if (priceLevel === "mid_plus") price = configData.price_mid_plus;
        else if (priceLevel === "high") price = configData.price_high;

        return {
          price,
          unit: configData.price_unit || "$/kWh",
          tier: tierData as PricingTier,
        };
      }
    } else if (sizeMWh !== null && sizeMWh !== undefined) {
      const { data: funcData, error: funcError } = await supabase.rpc("get_pricing_tier", {
        p_category: category,
        p_size_kw: null,
        p_size_mwh: sizeMWh,
      });

      if (!funcError && funcData && funcData.length > 0) {
        const tierData = funcData[0];
        const configData = tierData.config_data as PricingTier["config_data"];

        let price: number = configData.price_mid;
        if (priceLevel === "low") price = configData.price_low;
        else if (priceLevel === "low_plus") price = configData.price_low_plus;
        else if (priceLevel === "mid") price = configData.price_mid;
        else if (priceLevel === "mid_plus") price = configData.price_mid_plus;
        else if (priceLevel === "high") price = configData.price_high;

        return {
          price,
          unit: configData.price_unit || "$/kWh",
          tier: tierData as PricingTier,
        };
      }
    }

    // Fallback: Manual query with proper filtering
    let query = supabase
      .from("pricing_configurations")
      .select("*")
      .eq("config_category", category)
      .eq("is_active", true);

    if (sizeKW !== null && sizeKW !== undefined) {
      // Filter: size_min_kw <= sizeKW AND (size_max_kw >= sizeKW OR size_max_kw IS NULL)
      query = query
        .or(`size_min_kw.is.null,size_min_kw.lte.${sizeKW}`)
        .or(`size_max_kw.is.null,size_max_kw.gte.${sizeKW}`);
    } else if (sizeMWh !== null && sizeMWh !== undefined) {
      query = query
        .or(`size_min_mwh.is.null,size_min_mwh.lte.${sizeMWh}`)
        .or(`size_max_mwh.is.null,size_max_mwh.gte.${sizeMWh}`);
    }

    const orderBy = sizeKW !== null && sizeKW !== undefined ? "size_min_kw" : "size_min_mwh";
    const { data, error } = await query.order(orderBy, { ascending: false }).limit(1).single();

    if (error || !data) {
      console.warn(
        `[pricingTierService] No pricing tier found for ${sizeKW || sizeMWh} ${category}`
      );
      return null;
    }

    // Extract config_data JSONB
    const configData = data.config_data as PricingTier["config_data"];
    if (!configData) {
      console.warn(`[pricingTierService] Invalid config_data for tier ${data.config_key}`);
      return null;
    }

    // Get price based on selected level
    let price: number;
    const priceKey = `price_${priceLevel}` as keyof typeof configData;

    if (priceLevel === "low") {
      price = configData.price_low;
    } else if (priceLevel === "low_plus") {
      price = configData.price_low_plus;
    } else if (priceLevel === "mid") {
      price = configData.price_mid;
    } else if (priceLevel === "mid_plus") {
      price = configData.price_mid_plus;
    } else if (priceLevel === "high") {
      price = configData.price_high;
    } else {
      // Fallback to mid if invalid level
      price = configData.price_mid;
    }

    if (price === null || price === undefined) {
      console.warn(
        `[pricingTierService] Price not found for level ${priceLevel} in tier ${data.config_key}`
      );
      return null;
    }

    return {
      price,
      unit: configData.price_unit || "$/kWh",
      tier: data as PricingTier,
    };
  } catch (error) {
    console.error("[pricingTierService] Error fetching pricing tier:", error);
    return null;
  }
}

