      return {
        category: "Template Formats",
        status: "warning",
        score: 50,
        message: "No use cases found",
        timestamp: new Date().toISOString(),
        duration: Date.now() - startTime,
      };
    }

    // Validate template structure
    const issues: string[] = [];
    useCases.forEach((uc) => {
      if (!uc.power_profile || typeof uc.power_profile !== "object") {
