  powerMW: number,
  durationHours: number,
  location: string = "United States"
): Promise<BatteryPricing> {
  // Check cache first
  if (isCacheValid() && pricingCache.battery) {
    if (import.meta.env.DEV) {
      console.log("💾 Using cached battery pricing");
