function getSystemCategory(storageSizeMW: number): "residential" | "commercial" | "utility" {
  if (storageSizeMW < 0.05) return "residential"; // < 50 kW
  if (storageSizeMW < 1.0) return "commercial"; // < 1 MW (C&I)
  return "utility"; // >= 1 MW
}

