    durationHrs: 4, // Standard UPS backup target
    description: `Data Center: ${method} = ${powerKW.toFixed(1)} kW`,
    calculationMethod: "Uptime Institute standards (PUE 1.5)",
    inputs: { itLoadKW, rackCount, rackDensityKW },
