// ============================================

export interface UtilityRate {
  utilityName: string;
  utilityId: string;
  rateName: string;
  rateId: string;

  // Core Rates ($/kWh)
  residentialRate: number;
  commercialRate: number;
  industrialRate: number;

  // Time-of-Use Rates
  hasTOU: boolean;
  peakRate?: number;
  offPeakRate?: number;
  partPeakRate?: number;
  peakHours?: string;

  // Demand Charges ($/kW)
  hasDemandCharge: boolean;
  demandCharge?: number;
