export interface VendorRegistrationData {
  company_name: string;
  contact_name: string;
  email: string;
  phone?: string;
  password: string;
  specialty: "battery" | "inverter" | "ems" | "bos" | "epc" | "integrator";
  website?: string;
  description?: string;
}

export interface VendorLoginData {
  email: string;
  password: string;
}

/**
 * Register a new vendor
 */
export const registerVendor = async (data: VendorRegistrationData) => {
  if (!isSupabaseConfigured()) {
    throw new Error("Supabase is not configured");
  }

  try {
    // 1. Create auth user
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email: data.email,
      password: data.password,
      options: {
        data: {
          user_type: "vendor",
          company_name: data.company_name,
          contact_name: data.contact_name,
        },
      },
    });

    if (authError) throw authError;
    if (!authData.user) throw new Error("Failed to create user");

    // 2. Create vendor profile (status: pending by default)
    const { data: vendorData, error: vendorError } = await supabase
      .from("vendors")
      .insert({
        id: authData.user.id,
        company_name: data.company_name,
        contact_name: data.contact_name,
        email: data.email,
        phone: data.phone,
        specialty: data.specialty,
        website: data.website,
        description: data.description,
        status: "pending",
      })
      .select()
      .single();

    if (vendorError) throw vendorError;

    return {
      success: true,
      vendor: vendorData,
      message: "Registration successful! Your account is pending approval.",
    };
  } catch (error: any) {
    return {
      success: false,
      error: error.message || "Registration failed",
    };
  }
};

/**
 * Login vendor
 */
export const loginVendor = async (data: VendorLoginData) => {
  if (!isSupabaseConfigured()) {
    throw new Error("Supabase is not configured");
  }

  try {
    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email: data.email,
      password: data.password,
    });

    if (authError) throw authError;
    if (!authData.user) throw new Error("Login failed");

    // Get vendor profile
    const { data: vendorData, error: vendorError } = await supabase
      .from("vendors")
      .select("*")
      .eq("id", authData.user.id)
      .single();

    if (vendorError) throw vendorError;
    if (!vendorData) throw new Error("Vendor profile not found");

    // Check if approved
    if (vendorData.status === "pending") {
      await supabase.auth.signOut();
      throw new Error("Your account is pending approval. Please wait for admin review.");
    }

    if (vendorData.status === "rejected" || vendorData.status === "suspended") {
      await supabase.auth.signOut();
      throw new Error("Your account is not active. Please contact support.");
    }

    // Update last login
    await supabase
      .from("vendors")
      .update({ last_login: new Date().toISOString() })
      .eq("id", authData.user.id);

    return {
      success: true,
      vendor: vendorData,
      session: authData.session,
    };
  } catch (error: any) {
    return {
      success: false,
      error: error.message || "Login failed",
    };
  }
};

/**
 * Logout vendor
 */
export const logoutVendor = async () => {
  const { error } = await supabase.auth.signOut();
  if (error) throw error;
  return { success: true };
};

/**
 * Get current vendor session
 */
export const getCurrentVendor = async () => {
  const {
    data: { session },
  } = await supabase.auth.getSession();
  if (!session) return null;

  const { data: vendor, error } = await supabase
    .from("vendors")
    .select("*")
    .eq("id", session.user.id)
    .single();

  if (error) throw error;
  return vendor;
};

